import { NextRequest, NextResponse } from 'next/server';
import { createAdminDbClient } from '@/lib/db/client';
import { requireSupplierOrMasterUser } from '@/lib/admin-auth-server';
import { importProductsFromCsvText } from '@/lib/import-products-from-csv';

export async function POST(_request: NextRequest) {
  const auth = await requireSupplierOrMasterUser();
  if (!auth.ok) {
    return NextResponse.json({ error: auth.error }, { status: auth.status });
  }

  const sftpHost = process.env.SFTP_HOST;
  const sftpPort = Number.parseInt(process.env.SFTP_PORT || '22', 10);
  const sftpUser = process.env.SFTP_USER;
  const sftpPassword = process.env.SFTP_PASSWORD;
  const sftpPrivateKey = process.env.SFTP_PRIVATE_KEY;
  const sftpProductsPath = process.env.SFTP_PRODUCTS_PATH;

  if (!sftpHost || !sftpUser || !sftpProductsPath) {
    return NextResponse.json(
      { error: 'Configuracao SFTP ausente: SFTP_HOST, SFTP_USER e SFTP_PRODUCTS_PATH.' },
      { status: 400 }
    );
  }

  if (!sftpPassword && !sftpPrivateKey) {
    return NextResponse.json(
      { error: 'Defina SFTP_PASSWORD ou SFTP_PRIVATE_KEY para autenticar no SFTP.' },
      { status: 400 }
    );
  }

  const admin = createAdminDbClient();
  const logs: string[] = [];

  // import dinâmico: ssh2 tem código nativo; ajuda o bundler (Turbopack/Vercel).
  let sftp: import('ssh2-sftp-client') | null = null;

  try {
    const { default: SftpClient } = await import('ssh2-sftp-client');
    sftp = new SftpClient();

    logs.push(`Conectando ao SFTP ${sftpHost}:${sftpPort}...`);

    await sftp.connect({
      host: sftpHost,
      port: sftpPort,
      username: sftpUser,
      password: sftpPassword || undefined,
      privateKey: sftpPrivateKey || undefined,
      readyTimeout: 20000,
    });

    logs.push(`Baixando arquivo CSV: ${sftpProductsPath}`);
    const raw = await sftp.get(sftpProductsPath);
    const csvText = Buffer.isBuffer(raw) ? raw.toString('utf-8') : String(raw);

    const result = await importProductsFromCsvText(csvText, admin, auth.user.id, logs);

    return NextResponse.json({
      ok: true,
      ...result,
      logs,
    });
  } catch (error: unknown) {
    console.error('SFTP import error:', error);
    const msg = error instanceof Error ? error.message : 'Falha na importacao SFTP';
    return NextResponse.json(
      {
        ok: false,
        error: msg,
        logs,
      },
      { status: 500 }
    );
  } finally {
    if (sftp) {
      try {
        await sftp.end();
      } catch {
        // ignore
      }
    }
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { createServerSupabaseClient } from '@/lib/supabase-server';

export async function POST(request: NextRequest) {
  try {
    const { message, userId } = await request.json();

    if (!message) {
      return NextResponse.json({ error: 'Message is required' }, { status: 400 });
    }

    // Verificar autenticação e buscar dados do usuário se logado
    let userContext = '';
    let userData = null;

    if (userId) {
      const supabase = await createServerSupabaseClient();
      const { data: { user } } = await supabase.auth.getUser();
      
      if (user && user.id === userId) {
        // Buscar perfil
        const { data: profile } = await supabase
          .from('profiles')
          .select('*')
          .eq('id', user.id)
          .single();

        // Buscar pedidos
        const { data: orders } = await supabase
          .from('orders')
          .select('*, order_items(quantity, price, products(name))')
          .eq('user_id', user.id)
          .order('created_at', { ascending: false })
          .limit(5);

        userData = {
          name: profile?.full_name || user.email,
          email: user.email,
          role: profile?.role || 'customer',
          ordersCount: orders?.length || 0,
          recentOrders: orders?.map((o: any) => ({
            id: o.id,
            total: o.total_amount,
            status: o.status,
            date: o.created_at,
            items: o.order_items?.length || 0
          })) || []
        };

        userContext = `O usuário está logado como ${userData.name} (${userData.email}), com role ${userData.role}. 
        Total de pedidos: ${userData.ordersCount}. 
        Pedidos recentes: ${JSON.stringify(userData.recentOrders)}.
        Você pode fornecer informações sobre a conta, pedidos, histórico de compras, etc.`;
      }
    } else {
      userContext = `O usuário NÃO está logado. Você deve fornecer informações sobre produtos, categorias, preços, especificações de pneus, etc. 
      Não mencione informações pessoais ou de conta.`;
    }

    // Buscar produtos para contexto (se não logado)
    let productsContext = '';
    if (!userId) {
      const supabase = await createServerSupabaseClient();
      const { data: products } = await supabase
        .from('products')
        .select('name, category, base_price, specs')
        .eq('is_active', true)
        .limit(10);

      if (products && products.length > 0) {
        productsContext = `Produtos disponíveis: ${products.map((p: any) => 
          `${p.name} (${p.category}) - €${p.base_price}`
        ).join(', ')}`;
      }
    }

    // Preparar mensagem para ChatGPT
    const systemPrompt = `Você é um assistente virtual da MecaniDoc, uma loja online especializada em pneus.
    
${userContext}

${productsContext}

Você deve:
- Ser amigável e profissional
- Responder em francês
- Se o usuário estiver logado, fornecer informações sobre sua conta e pedidos
- Se não estiver logado, ajudar com informações sobre produtos, categorias, preços
- Não inventar informações que não foram fornecidas
- Se não souber algo, sugerir que o usuário entre em contato com o suporte`;

    // Chamar API do OpenAI
    const apiKey = process.env.OPENAI_API_KEY;
    if (!apiKey) {
      return NextResponse.json({ 
        error: 'OpenAI API key not configured',
        message: 'Desculpe, o serviço de chat está temporariamente indisponível. Por favor, entre em contato conosco através do email de suporte.'
      }, { status: 500 });
    }

    const response = await fetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${apiKey}`
      },
      body: JSON.stringify({
        model: 'gpt-3.5-turbo',
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: message }
        ],
        max_tokens: 500,
        temperature: 0.7
      })
    });

    if (!response.ok) {
      const error = await response.json();
      console.error('OpenAI API error:', error);
      return NextResponse.json({ 
        error: 'Failed to get response from AI',
        message: 'Desculpe, ocorreu um erro ao processar sua mensagem. Por favor, tente novamente.'
      }, { status: 500 });
    }

    const data = await response.json();
    const aiMessage = data.choices[0]?.message?.content || 'Desculpe, não consegui processar sua mensagem.';

    return NextResponse.json({ 
      message: aiMessage,
      userData: userData || null
    });

  } catch (error: any) {
    console.error('Chat API error:', error);
    return NextResponse.json({ 
      error: 'Internal server error',
      message: 'Desculpe, ocorreu um erro. Por favor, tente novamente mais tarde.'
    }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { createServerSupabaseClient } from '@/lib/supabase-server';
import { getStripe } from '@/lib/stripe-wrapper';

export async function GET(request: NextRequest) {
  try {
    const supabase = await createServerSupabaseClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    // Verificar se é master ou admin
    const { data: profile } = await supabase
      .from('profiles')
      .select('role')
      .eq('id', user.id)
      .single();

    if (profile?.role !== 'master') {
      return NextResponse.json(
        { error: 'Forbidden' },
        { status: 403 }
      );
    }

    const { searchParams } = new URL(request.url);
    const startDate = searchParams.get('startDate');
    const endDate = searchParams.get('endDate');
    const status = searchParams.get('status');

    // Buscar pedidos
    let query = supabase
      .from('orders')
      .select(`
        *,
        order_items (
          *,
          products (
            id,
            name,
            base_price,
            category
          ),
          garages (
            id,
            name,
            address,
            city,
            zip_code
          )
        ),
        profiles (
          id,
          email,
          full_name
        )
      `)
      .order('created_at', { ascending: false });

    // Só filtrar por data se ambas existirem (evita "só início" = cortar todas as encomendas antigas)
    if (startDate && endDate) {
      const startIso = `${startDate}T00:00:00.000Z`;
      const endIso = `${endDate}T23:59:59.999Z`;
      query = query.gte('created_at', startIso).lte('created_at', endIso);
    }
    if (status) {
      query = query.eq('payment_status', status);
    }

    const { data: orders, error } = await query;

    if (error) {
      throw error;
    }

    // Buscar informações adicionais do Stripe para pedidos pagos (apenas se Stripe estiver configurado)
    const stripe = await getStripe();
    const ordersWithStripeData = await Promise.all(
      ((orders as any[]) || []).map(async (order: any) => {
        if (stripe && order.stripe_payment_intent_id && order.payment_status === 'paid') {
          try {
            const paymentIntent = await stripe.paymentIntents.retrieve(
              order.stripe_payment_intent_id
            );
            return {
              ...order,
              stripe_data: {
                payment_method: paymentIntent.payment_method_types[0],
                receipt_url: paymentIntent.charges?.data[0]?.receipt_url,
              },
            };
          } catch (err) {
            console.error('Error fetching Stripe data:', err);
            return order;
          }
        }
        return order;
      })
    );

    // Calcular estatísticas
    const totalSales = ordersWithStripeData
      .filter((o) => o.payment_status === 'paid')
      .reduce((sum, o) => sum + parseFloat(o.total_amount.toString()), 0);

    const totalOrders = ordersWithStripeData.length;
    const paidOrders = ordersWithStripeData.filter((o) => o.payment_status === 'paid').length;
    const pendingOrders = ordersWithStripeData.filter((o) => o.payment_status === 'pending').length;

    return NextResponse.json({
      orders: ordersWithStripeData,
      statistics: {
        totalSales,
        totalOrders,
        paidOrders,
        pendingOrders,
      },
    });
  } catch (error: any) {
    console.error('Error fetching sales:', error);
    return NextResponse.json(
      { error: error.message || 'Failed to fetch sales' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getStripe } from '@/lib/stripe-wrapper';
import { getSupabaseAdmin } from '@/lib/neumaticos-andres/server-helpers';
import { createServerSupabaseClient } from '@/lib/supabase-server';
import {
  STRIPE_CURRENCY,
  STRIPE_MIN_AMOUNT_CENTS,
  toStripeAmountCents,
} from '@/lib/stripe-payments';

function resolveOrigin(request: NextRequest): string {
  const headerOrigin = request.headers.get('origin');
  if (headerOrigin) return headerOrigin.replace(/\/$/, '');
  const appUrl = (process.env.NEXT_PUBLIC_APP_URL || '').replace(/\/$/, '');
  if (appUrl.startsWith('http://') || appUrl.startsWith('https://')) return appUrl;
  try {
    return new URL(request.url).origin;
  } catch {
    return 'http://localhost:3002';
  }
}

export async function POST(request: NextRequest) {
  const stripe = await getStripe();
  if (!stripe) {
    return NextResponse.json(
      { error: 'Stripe n’est pas configuré. Ajoutez les clés dans Admin → Paiement Stripe.' },
      { status: 503 }
    );
  }

  try {
    const body = await request.json().catch(() => null);
    const orderId = body?.orderId;

    if (!orderId || typeof orderId !== 'string') {
      return NextResponse.json({ error: 'orderId is required' }, { status: 400 });
    }

    const supabase = await createServerSupabaseClient();
    const {
      data: { user },
    } = await supabase.auth.getUser();

    if (!user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { data: order, error: orderError } = await supabase
      .from('orders')
      .select('*')
      .eq('id', orderId)
      .eq('user_id', user.id)
      .single();

    if (orderError || !order) {
      return NextResponse.json({ error: 'Order not found' }, { status: 404 });
    }

    if (order.payment_status === 'paid' || order.status === 'paid') {
      return NextResponse.json(
        { error: 'Order is already paid', alreadyPaid: true },
        { status: 409 }
      );
    }

    if (order.payment_status === 'refunded') {
      return NextResponse.json(
        { error: 'Order was refunded and cannot be paid again' },
        { status: 409 }
      );
    }

    const amountCents = toStripeAmountCents(order.total_amount);
    if (amountCents < STRIPE_MIN_AMOUNT_CENTS) {
      return NextResponse.json(
        { error: `Invalid order amount (minimum ${STRIPE_MIN_AMOUNT_CENTS} cents)` },
        { status: 400 }
      );
    }

    // Réutiliser une session Checkout encore ouverte (évite sessions orphelines)
    if (order.stripe_checkout_session_id) {
      try {
        const existing = await stripe.checkout.sessions.retrieve(order.stripe_checkout_session_id);
        if (
          existing.status === 'open' &&
          existing.client_secret &&
          existing.metadata?.order_id === orderId
        ) {
          return NextResponse.json({
            clientSecret: existing.client_secret,
            sessionId: existing.id,
            reused: true,
          });
        }
      } catch (retrieveError) {
        console.warn('Could not reuse checkout session:', retrieveError);
      }
    }

    const origin = resolveOrigin(request);

    // Idempotence pour les retries réseau ; nouvelle clé si une session précédente existe déjà
    const idempotencyKey = order.stripe_checkout_session_id
      ? `checkout-session-${orderId}-${Date.now()}`
      : `checkout-session-${orderId}`;

    const session = await stripe.checkout.sessions.create(
      {
        mode: 'payment',
        ui_mode: 'embedded',
        locale: 'fr',
        line_items: [
          {
            price_data: {
              currency: STRIPE_CURRENCY,
              unit_amount: amountCents,
              product_data: {
                name: `Commande MecaniDoc #${orderId.slice(0, 8)}`,
                description: 'Pneus et services MecaniDoc',
              },
            },
            quantity: 1,
          },
        ],
        return_url: `${origin}/checkout/success?session_id={CHECKOUT_SESSION_ID}&order_id=${encodeURIComponent(orderId)}`,
        metadata: {
          order_id: orderId,
          user_id: user.id,
        },
        // Copie les métadonnées sur le PaymentIntent (webhooks payment_intent.*)
        payment_intent_data: {
          metadata: {
            order_id: orderId,
            user_id: user.id,
          },
        },
        customer_email: order.contact_email || undefined,
      },
      { idempotencyKey }
    );

    if (!session.client_secret) {
      return NextResponse.json(
        { error: 'Stripe did not return a client secret for embedded checkout.' },
        { status: 500 }
      );
    }

    const admin = getSupabaseAdmin();
    const { error: updateError } = await admin
      .from('orders')
      .update({
        stripe_checkout_session_id: session.id,
        payment_status: 'pending',
        payment_method: 'stripe',
      })
      .eq('id', orderId);

    if (updateError) {
      // Colonne absente ou autre : on logue mais on renvoie quand même le secret
      // (le webhook peut encore marquer paid via metadata.order_id)
      console.warn('Could not persist checkout session id on order:', updateError.message);
    }

    return NextResponse.json({
      clientSecret: session.client_secret,
      sessionId: session.id,
    });
  } catch (error: any) {
    console.error('Error creating checkout session:', error);
    return NextResponse.json(
      { error: error.message || 'Failed to create checkout session' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getStripe } from '@/lib/stripe-wrapper';
import { getSupabaseAdmin } from '@/lib/neumaticos-andres/server-helpers';
import { createServerSupabaseClient } from '@/lib/supabase-server';
import {
  STRIPE_CURRENCY,
  STRIPE_MIN_AMOUNT_CENTS,
  toStripeAmountCents,
} from '@/lib/stripe-payments';

export async function POST(request: NextRequest) {
  const stripe = await getStripe();
  if (!stripe) {
    return NextResponse.json(
      { error: 'Stripe n’est pas configuré. Ajoutez les clés dans Admin → Paiement Stripe.' },
      { status: 503 }
    );
  }

  try {
    const body = await request.json().catch(() => null);
    const orderId = body?.orderId;
    const customerEmail =
      typeof body?.customerEmail === 'string' ? body.customerEmail.trim() : '';
    const customerName =
      typeof body?.customerName === 'string' ? body.customerName.trim() : undefined;

    if (!orderId || typeof orderId !== 'string') {
      return NextResponse.json({ error: 'orderId is required' }, { status: 400 });
    }

    const supabase = await createServerSupabaseClient();
    const {
      data: { user },
    } = await supabase.auth.getUser();

    if (!user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { data: order, error: orderError } = await supabase
      .from('orders')
      .select('*')
      .eq('id', orderId)
      .eq('user_id', user.id)
      .single();

    if (orderError || !order) {
      return NextResponse.json({ error: 'Order not found' }, { status: 404 });
    }

    if (order.payment_status === 'paid' || order.status === 'paid') {
      return NextResponse.json(
        { error: 'Order is already paid', alreadyPaid: true },
        { status: 409 }
      );
    }

    // Toujours utiliser le montant serveur — jamais le montant envoyé par le client
    const amountCents = toStripeAmountCents(order.total_amount);
    if (amountCents < STRIPE_MIN_AMOUNT_CENTS) {
      return NextResponse.json(
        { error: `Invalid order amount (minimum ${STRIPE_MIN_AMOUNT_CENTS} cents)` },
        { status: 400 }
      );
    }

    // Réutiliser un PaymentIntent pending encore utilisable
    if (order.stripe_payment_intent_id) {
      try {
        const existing = await stripe.paymentIntents.retrieve(order.stripe_payment_intent_id);
        if (
          ['requires_payment_method', 'requires_confirmation', 'requires_action'].includes(
            existing.status
          ) &&
          existing.amount === amountCents &&
          existing.client_secret
        ) {
          return NextResponse.json({
            clientSecret: existing.client_secret,
            paymentIntentId: existing.id,
            reused: true,
          });
        }
      } catch (retrieveError) {
        console.warn('Could not reuse payment intent:', retrieveError);
      }
    }

    let customerId: string | null = order.stripe_customer_id || null;
    const email = customerEmail || order.contact_email || '';

    if (!customerId && email) {
      const customers = await stripe.customers.list({ email, limit: 1 });
      if (customers.data.length > 0) {
        customerId = customers.data[0].id;
      } else {
        const customer = await stripe.customers.create({
          email,
          name: customerName || order.contact_name || undefined,
          metadata: {
            user_id: user.id,
          },
        });
        customerId = customer.id;
      }
    }

    const idempotencyKey = order.stripe_payment_intent_id
      ? `payment-intent-${orderId}-${amountCents}-${Date.now()}`
      : `payment-intent-${orderId}-${amountCents}`;

    const paymentIntent = await stripe.paymentIntents.create(
      {
        amount: amountCents,
        currency: STRIPE_CURRENCY,
        customer: customerId || undefined,
        metadata: {
          order_id: orderId,
          user_id: user.id,
        },
        automatic_payment_methods: {
          enabled: true,
        },
      },
      { idempotencyKey }
    );

    const admin = getSupabaseAdmin();
    await admin
      .from('orders')
      .update({
        stripe_payment_intent_id: paymentIntent.id,
        stripe_customer_id: customerId,
        payment_status: 'pending',
        payment_method: 'stripe',
      })
      .eq('id', orderId);

    return NextResponse.json({
      clientSecret: paymentIntent.client_secret,
      paymentIntentId: paymentIntent.id,
    });
  } catch (error: any) {
    console.error('Error creating payment intent:', error);
    return NextResponse.json(
      { error: error.message || 'Failed to create payment intent' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getSupabaseAdmin } from '@/lib/neumaticos-andres/server-helpers';
import {
  extractPaymentIntentId,
  markOrderPaid,
  toStripeAmountCents,
} from '@/lib/stripe-payments';
import { getStripe } from '@/lib/stripe-wrapper';
import { createServerSupabaseClient } from '@/lib/supabase-server';

/**
 * Vérifie une Checkout Session côté Stripe et synchronise le statut de la commande.
 * Sert de filet de sécurité si le webhook est en retard (page /checkout/success).
 */
export async function POST(request: NextRequest) {
  const stripe = await getStripe();
  if (!stripe) {
    return NextResponse.json({ error: 'Stripe n’est pas configuré' }, { status: 503 });
  }

  try {
    const body = await request.json().catch(() => null);
    const sessionId = body?.sessionId;
    const orderId = body?.orderId;

    if (!sessionId || typeof sessionId !== 'string') {
      return NextResponse.json({ error: 'sessionId is required' }, { status: 400 });
    }

    const supabase = await createServerSupabaseClient();
    const {
      data: { user },
    } = await supabase.auth.getUser();

    if (!user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const session = await stripe.checkout.sessions.retrieve(sessionId);
    const sessionOrderId = session.metadata?.order_id;

    if (!sessionOrderId) {
      return NextResponse.json({ error: 'Session has no order metadata' }, { status: 400 });
    }

    if (orderId && orderId !== sessionOrderId) {
      return NextResponse.json({ error: 'Order mismatch' }, { status: 400 });
    }

    if (session.metadata?.user_id && session.metadata.user_id !== user.id) {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }

    const { data: order, error: orderError } = await supabase
      .from('orders')
      .select('id, user_id, payment_status, status, total_amount')
      .eq('id', sessionOrderId)
      .single();

    if (orderError || !order) {
      return NextResponse.json({ error: 'Order not found' }, { status: 404 });
    }

    if (order.user_id !== user.id) {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }

    const stripePaymentStatus = session.payment_status; // paid | unpaid | no_payment_required
    const sessionStatus = session.status; // open | complete | expired

    if (stripePaymentStatus === 'paid') {
      if (
        typeof session.amount_total === 'number' &&
        session.amount_total > 0 &&
        session.amount_total !== toStripeAmountCents(order.total_amount)
      ) {
        return NextResponse.json(
          {
            status: 'error',
            paymentStatus: order.payment_status,
            stripePaymentStatus,
            sessionStatus,
            orderId: order.id,
            error: 'Amount mismatch',
          },
          { status: 409 }
        );
      }

      // Synchronisation si le webhook n'est pas encore passé (transition atomique, idempotente)
      if (order.payment_status !== 'paid') {
        const admin = getSupabaseAdmin();
        const result = await markOrderPaid(admin, order.id, {
          paymentIntentId: extractPaymentIntentId(session.payment_intent),
          checkoutSessionId: session.id,
          customerId:
            typeof session.customer === 'string'
              ? session.customer
              : session.customer && typeof session.customer === 'object'
                ? (session.customer as { id?: string }).id
                : null,
          amountCents: typeof session.amount_total === 'number' ? session.amount_total : null,
          currency: session.currency || null,
        });
        if (!result.ok) {
          console.error('verify-session markOrderPaid:', result.error);
          return NextResponse.json(
            { status: 'error', paymentStatus: order.payment_status, stripePaymentStatus, sessionStatus, orderId: order.id, error: 'Vérification impossible' },
            { status: result.code === 'DB_ERROR' ? 500 : 409 }
          );
        }
      }

      return NextResponse.json({
        status: 'paid',
        paymentStatus: 'paid',
        stripePaymentStatus,
        sessionStatus,
        orderId: order.id,
      });
    }

    if (sessionStatus === 'expired') {
      return NextResponse.json({
        status: 'expired',
        paymentStatus: order.payment_status,
        stripePaymentStatus,
        sessionStatus,
        orderId: order.id,
      });
    }

    return NextResponse.json({
      status: stripePaymentStatus === 'unpaid' ? 'unpaid' : 'pending',
      paymentStatus: order.payment_status,
      stripePaymentStatus,
      sessionStatus,
      orderId: order.id,
    });
  } catch (error: any) {
    console.error('Error verifying checkout session:', error);
    return NextResponse.json(
      { error: error.message || 'Failed to verify session' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { createAdminDbClient } from '@/lib/db/client';
import { requireSupplierOrMasterUser } from '@/lib/admin-auth-server';
import { generateApiKey } from '@/lib/supplier-api/crypto';

async function resolveSupplierId(userId: string, bodySupplierId?: string) {
  const admin = createAdminDbClient();
  const { data: profile } = await admin.from('profiles').select('role').eq('id', userId).single();

  if (profile?.role === 'master' && bodySupplierId) {
    return bodySupplierId;
  }

  const { data: supplier } = await admin
    .from('suppliers')
    .select('id, is_approved')
    .eq('profile_id', userId)
    .maybeSingle();

  if (!supplier) return null;
  if (!supplier.is_approved && profile?.role !== 'master') return null;
  return supplier.id as string;
}

export async function GET() {
  const auth = await requireSupplierOrMasterUser();
  if (!auth.ok) {
    return NextResponse.json({ error: auth.error }, { status: auth.status });
  }

  const supplierId = await resolveSupplierId(auth.user.id);
  if (!supplierId) {
    return NextResponse.json({ error: 'Fornecedor não encontrado ou não aprovado' }, { status: 403 });
  }

  const admin = createAdminDbClient();
  const { data, error } = await admin
    .from('supplier_api_keys')
    .select('id, name, key_prefix, is_active, last_used_at, created_at, revoked_at')
    .eq('supplier_id', supplierId)
    .order('created_at', { ascending: false });

  if (error) {
    return NextResponse.json({ error: error.message }, { status: 500 });
  }

  return NextResponse.json({
    keys: (data || []).map((k: any) => ({
      id: k.id,
      name: k.name,
      prefix: k.key_prefix,
      is_active: Boolean(k.is_active) && !k.revoked_at,
      last_used_at: k.last_used_at,
      created_at: k.created_at,
      revoked_at: k.revoked_at,
    })),
  });
}

export async function POST(request: NextRequest) {
  const auth = await requireSupplierOrMasterUser();
  if (!auth.ok) {
    return NextResponse.json({ error: auth.error }, { status: auth.status });
  }

  const body = await request.json().catch(() => ({}));
  const name =
    typeof body.name === 'string' && body.name.trim() ? body.name.trim() : 'Chave API';
  const supplierId = await resolveSupplierId(
    auth.user.id,
    typeof body.supplier_id === 'string' ? body.supplier_id : undefined
  );

  if (!supplierId) {
    return NextResponse.json({ error: 'Fornecedor não encontrado ou não aprovado' }, { status: 403 });
  }

  const generated = generateApiKey();
  const admin = createAdminDbClient();
  const { data, error } = await admin
    .from('supplier_api_keys')
    .insert({
      supplier_id: supplierId,
      name,
      key_prefix: generated.keyPrefix,
      key_hash: generated.keyHash,
      is_active: true,
    })
    .single();

  if (error) {
    return NextResponse.json({ error: error.message }, { status: 500 });
  }

  return NextResponse.json({
    ok: true,
    key: {
      id: data.id,
      name: data.name,
      prefix: data.key_prefix,
      created_at: data.created_at,
      /** Mostrada apenas uma vez — guarde em local seguro. */
      api_key: generated.rawKey,
    },
    message: 'Guarde a API key agora — não será mostrada novamente.',
  });
}

export async function DELETE(request: NextRequest) {
  const auth = await requireSupplierOrMasterUser();
  if (!auth.ok) {
    return NextResponse.json({ error: auth.error }, { status: auth.status });
  }

  const body = await request.json().catch(() => ({}));
  const keyId = typeof body.id === 'string' ? body.id : null;
  if (!keyId) {
    return NextResponse.json({ error: 'Campo "id" obrigatório' }, { status: 400 });
  }

  const supplierId = await resolveSupplierId(auth.user.id);
  if (!supplierId) {
    return NextResponse.json({ error: 'Fornecedor não encontrado ou não aprovado' }, { status: 403 });
  }

  const admin = createAdminDbClient();
  const { data: existing } = await admin
    .from('supplier_api_keys')
    .select('id, supplier_id')
    .eq('id', keyId)
    .maybeSingle();

  if (!existing || existing.supplier_id !== supplierId) {
    const { data: profile } = await admin.from('profiles').select('role').eq('id', auth.user.id).single();
    if (profile?.role !== 'master' || !existing) {
      return NextResponse.json({ error: 'Chave não encontrada' }, { status: 404 });
    }
  }

  const { error } = await admin
    .from('supplier_api_keys')
    .update({
      is_active: false,
      revoked_at: new Date().toISOString(),
    })
    .eq('id', keyId);

  if (error) {
    return NextResponse.json({ error: error.message }, { status: 500 });
  }

  return NextResponse.json({ ok: true });
}

import { NextRequest, NextResponse } from 'next/server';
import { createAdminDbClient } from '@/lib/db/client';
import { authenticateSupplierApi } from '@/lib/supplier-api/auth';
import {
  PRODUCT_PUBLIC_FIELDS,
  findSupplierProduct,
  normalizeProductInput,
  serializeProduct,
  type SupplierProductInput,
} from '@/lib/supplier-api/products';

export async function GET(request: NextRequest) {
  const authResult = await authenticateSupplierApi(request);
  if (!authResult.ok) {
    return NextResponse.json({ error: authResult.error }, { status: authResult.status });
  }

  const { searchParams } = new URL(request.url);
  const page = Math.max(1, Number(searchParams.get('page') || 1));
  const limit = Math.min(100, Math.max(1, Number(searchParams.get('limit') || 50)));
  const ean = searchParams.get('ean')?.trim() || null;
  const sku = searchParams.get('sku')?.trim() || null;
  const q = searchParams.get('q')?.trim() || null;
  const activeOnly = searchParams.get('active') === '1' || searchParams.get('active') === 'true';

  const admin = createAdminDbClient();

  if (ean || sku) {
    const row = await findSupplierProduct(admin, authResult.auth.supplierId, { ean, sku });
    return NextResponse.json({
      data: row ? [serializeProduct(row)] : [],
      meta: { page: 1, limit: 1, total: row ? 1 : 0 },
    });
  }

  let query = admin
    .from('products')
    .select(PRODUCT_PUBLIC_FIELDS)
    .eq('supplier_id', authResult.auth.supplierId)
    .order('created_at', { ascending: false })
    .limit(limit);

  if (activeOnly) query = query.eq('is_active', true);
  if (q) query = query.ilike('name', `%${q}%`);

  const { data, error } = await query;
  if (error) {
    return NextResponse.json({ error: error.message }, { status: 500 });
  }

  const rows = data || [];
  // offset simples via page (o query builder não tem range; fazemos slice)
  const offset = (page - 1) * limit;
  const sliced = page > 1 ? rows.slice(0, limit) : rows;

  return NextResponse.json({
    data: sliced.map((row: Record<string, unknown>) => serializeProduct(row)),
    meta: {
      page,
      limit,
      count: sliced.length,
      offset,
      supplier: authResult.auth.companyName,
    },
  });
}

export async function POST(request: NextRequest) {
  const authResult = await authenticateSupplierApi(request);
  if (!authResult.ok) {
    return NextResponse.json({ error: authResult.error }, { status: authResult.status });
  }

  const body = await request.json().catch(() => null);
  if (!body || typeof body !== 'object') {
    return NextResponse.json({ error: 'JSON inválido' }, { status: 400 });
  }

  const items: SupplierProductInput[] = Array.isArray((body as any).products)
    ? (body as any).products
    : Array.isArray(body)
      ? body
      : [body as SupplierProductInput];

  if (!items.length) {
    return NextResponse.json({ error: 'Envie um produto ou products[]' }, { status: 400 });
  }
  if (items.length > 100) {
    return NextResponse.json({ error: 'Máximo 100 produtos por pedido' }, { status: 400 });
  }

  const admin = createAdminDbClient();
  const results: Array<{ action: string; product?: unknown; error?: string }> = [];

  for (const item of items) {
    const normalized = normalizeProductInput(item, authResult.auth, false);
    if (!normalized.ok) {
      results.push({ action: 'error', error: normalized.error });
      continue;
    }

    const ean = typeof normalized.data.ean === 'string' ? normalized.data.ean : null;
    const sku =
      typeof normalized.data.external_product_id === 'string'
        ? normalized.data.external_product_id
        : null;

    try {
      const existing = await findSupplierProduct(admin, authResult.auth.supplierId, { ean, sku });
      if (existing) {
        const { data, error } = await admin
          .from('products')
          .update({
            ...normalized.data,
            last_stock_sync_at: new Date().toISOString(),
          })
          .eq('id', existing.id)
          .eq('supplier_id', authResult.auth.supplierId)
          .single();

        if (error) {
          results.push({ action: 'error', error: error.message });
        } else {
          results.push({ action: 'updated', product: serializeProduct(data) });
        }
      } else {
        const { data, error } = await admin
          .from('products')
          .insert({
            ...normalized.data,
            last_stock_sync_at: new Date().toISOString(),
          })
          .single();

        if (error) {
          results.push({ action: 'error', error: error.message });
        } else {
          results.push({ action: 'created', product: serializeProduct(data) });
        }
      }
    } catch (err: unknown) {
      results.push({
        action: 'error',
        error: err instanceof Error ? err.message : 'Erro ao gravar produto',
      });
    }
  }

  const created = results.filter((r) => r.action === 'created').length;
  const updated = results.filter((r) => r.action === 'updated').length;
  const errors = results.filter((r) => r.action === 'error').length;

  return NextResponse.json(
    {
      ok: errors === 0,
      summary: { created, updated, errors, total: results.length },
      results,
    },
    { status: errors && !created && !updated ? 400 : 200 }
  );
}

"use client";

import React, { useState } from 'react';
import Header from "@/components/Header";
import Footer from "@/components/Footer";
import { createClient } from '@/lib/supabase';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { Loader2, AlertCircle } from 'lucide-react';

export default function RegisterCompanyPage() {
  const router = useRouter();
  const supabase = createClient();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Form State
  const [formData, setFormData] = useState({
    companyName: '',
    username: '',
    email: '',
    password: '',
    confirmPassword: ''
  });

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    if (formData.password !== formData.confirmPassword) {
      setError("Les mots de passe ne correspondent pas.");
      setLoading(false);
      return;
    }

    try {
      // Utilisateur + profil (rôle company) + fiche entreprise en une seule transaction côté serveur.
      // La remise B2B est attribuée ensuite par l'administrateur.
      const { data: authData, error: authError } = await supabase.auth.register({
        email: formData.email,
        password: formData.password,
        fullName: formData.username,
        role: 'company',
        company: { companyName: formData.companyName },
      });

      if (authError) throw new Error(authError.message);
      if (authData.user) {
        router.push('/dashboard/entreprise');
      }
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : "Une erreur est survenue lors de l'inscription.";
      setError(message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <main className="min-h-screen bg-[#F1F1F1]">
      <Header />

      <div className="container mx-auto px-4 py-12 flex justify-center">
        <div className="bg-white w-full max-w-md rounded shadow-sm overflow-hidden">
          
          {/* Tabs */}
          <div className="flex border-b border-gray-200">
            <Link href="/auth/login" className="flex-1 py-4 text-center text-sm font-medium text-gray-500 hover:text-gray-700 hover:bg-gray-50">
              Connexion
            </Link>
            <div className="flex-1 py-4 text-center text-sm font-bold text-blue-600 border-b-2 border-blue-600 bg-blue-50/30">
              Inscription
            </div>
          </div>

          <div className="p-8">
            {error && (
              <div className="bg-red-50 text-red-600 p-4 rounded mb-6 flex items-center gap-2 text-sm">
                <AlertCircle size={16} />
                {error}
              </div>
            )}

            <form onSubmit={handleSubmit} className="space-y-6">
              
              <div>
                <label className="block text-xs font-bold text-gray-700 mb-1">Nom de l'entreprise</label>
                <input 
                  type="text" 
                  name="companyName" 
                  required 
                  onChange={handleInputChange} 
                  className="w-full border border-gray-200 rounded-lg px-3 py-3 text-sm focus:border-blue-500 focus:outline-none bg-gray-50/50" 
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-gray-700 mb-1">Nom d'utilisateur</label>
                <input 
                  type="text" 
                  name="username" 
                  required 
                  onChange={handleInputChange} 
                  className="w-full border border-gray-200 rounded-lg px-3 py-3 text-sm focus:border-blue-500 focus:outline-none bg-blue-50/20" 
                  placeholder="johndoe123"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-gray-700 mb-1">Email</label>
                <input 
                  type="email" 
                  name="email" 
                  required 
                  onChange={handleInputChange} 
                  className="w-full border border-gray-200 rounded-lg px-3 py-3 text-sm focus:border-blue-500 focus:outline-none bg-gray-50/50" 
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-gray-700 mb-1">Mot de passe</label>
                <input 
                  type="password" 
                  name="password" 
                  required 
                  onChange={handleInputChange} 
                  className="w-full border border-gray-200 rounded-lg px-3 py-3 text-sm focus:border-blue-500 focus:outline-none bg-blue-50/20" 
                  placeholder="••••••••••••"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-gray-700 mb-1">Confirmer le mot de passe</label>
                <input 
                  type="password" 
                  name="confirmPassword" 
                  required 
                  onChange={handleInputChange} 
                  className="w-full border border-gray-200 rounded-lg px-3 py-3 text-sm focus:border-blue-500 focus:outline-none bg-gray-50/50" 
                />
              </div>

              <div className="pt-2">
                <button 
                  type="submit" 
                  disabled={loading}
                  className="bg-[#0044CC] text-white font-bold py-3 px-8 rounded-lg shadow-md hover:bg-blue-800 transition-colors text-sm disabled:opacity-70 flex items-center justify-center gap-2"
                >
                  {loading && <Loader2 size={16} className="animate-spin" />}
                  S'inscrire
                </button>
              </div>

            </form>
          </div>
        </div>
      </div>

      <Footer />
    </main>
  );
}

