"use client";

import React, { useState, useEffect, useMemo } from "react";
import { createClient } from "@/lib/supabase";
import { Loader2, Tag, Trash2, Plus, ImageIcon } from "lucide-react";

const OVERLAY_OPTIONS = [
  { value: "strong", label: "Forte (texte très lisible)" },
  { value: "medium", label: "Moyenne (recommandé)" },
  { value: "soft", label: "Légère (photo plus visible)" },
] as const;

export default function PromotionsSection() {
  const supabase = createClient();
  const [promotions, setPromotions] = useState<any[]>([]);
  const [products, setProducts] = useState<any[]>([]);
  const [productsLoading, setProductsLoading] = useState(false);
  const [selectedProductIds, setSelectedProductIds] = useState<string[]>([]);
  const [productSearch, setProductSearch] = useState("");
  const [loading, setLoading] = useState(true);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [editing, setEditing] = useState<any>(null);
  const [isAdding, setIsAdding] = useState(false);

  const fetchPromotions = async () => {
    setLoading(true);
    setErrorMsg(null);
    const { data, error } = await supabase.from("promotions").select("*").order("sort_order", { ascending: true });
    if (error) {
      console.error("promotions:", error);
      setErrorMsg(
        'Table « promotions » introuvable dans ce projet Supabase. Exécutez les scripts SQL (migrations).'
      );
      setPromotions([]);
      setLoading(false);
      return;
    }
    setPromotions(data || []);
    setLoading(false);
  };

  useEffect(() => {
    fetchPromotions();
  }, []);

  const buildPromoProductsLink = (category: string, productIds: string[]) => {
    const params = new URLSearchParams();
    params.set("category", category || "Toutes");
    params.set("product_ids", productIds.join(","));
    return `/search?${params.toString()}`;
  };

  const parseProductIdsFromLink = (linkUrl?: string | null): string[] => {
    if (!linkUrl?.trim()) return [];
    const raw = linkUrl.trim();
    if (!raw.startsWith("/search?")) return [];
    const query = raw.split("?")[1] || "";
    const ids = new URLSearchParams(query).get("product_ids") || "";
    return ids
      .split(",")
      .map((id) => id.trim())
      .filter(Boolean);
  };

  const fetchProducts = async (parentCategory?: string | null) => {
    setProductsLoading(true);
    let query = supabase
      .from("products")
      .select("id, name, brand, category")
      .eq("is_active", true)
      .order("name", { ascending: true })
      .limit(400);
    const cat = (parentCategory || "").trim();
    if (cat) {
      if (cat === "Tracteurs") {
        query = query.or("category.ilike.Tracteur,category.ilike.Tracteurs");
      } else {
        query = query.ilike("category", cat);
      }
    }
    const { data } = await query;
    setProducts(data || []);
    setProductsLoading(false);
  };

  const selectedProductsLabel = useMemo(() => {
    const map = new Map(products.map((p) => [p.id, p]));
    return selectedProductIds
      .map((id) => map.get(id))
      .filter(Boolean)
      .map((p: any) => `${p.name}${p.brand ? ` (${p.brand})` : ""}`);
  }, [products, selectedProductIds]);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    const form = e.target as HTMLFormElement;
    const formData = new FormData(form);
    const parentRaw = ((formData.get("parent_category") as string) || "").trim();
    const badgeColorRaw = ((formData.get("badge_color") as string) || "").trim();
    let overlayRaw = ((formData.get("card_overlay") as string) || "medium").trim().toLowerCase();
    if (!["strong", "medium", "soft"].includes(overlayRaw)) overlayRaw = "medium";

    const linkRaw = ((formData.get("link_url") as string) || "").trim();
    const finalLink =
      !linkRaw && selectedProductIds.length > 0
        ? buildPromoProductsLink(parentRaw || "Toutes", selectedProductIds)
        : linkRaw || null;

    const payload = {
      title: formData.get("title") as string,
      discount_text: (formData.get("discount_text") as string) || null,
      description: (formData.get("description") as string) || null,
      link_url: finalLink,
      is_active: formData.get("is_active") === "on",
      start_date: (formData.get("start_date") as string) || null,
      end_date: (formData.get("end_date") as string) || null,
      sort_order: parseInt(formData.get("sort_order") as string, 10) || 0,
      parent_category: parentRaw || null,
      badge_text: ((formData.get("badge_text") as string) || "").trim() || null,
      badge_color: badgeColorRaw || null,
      card_image_url: ((formData.get("card_image_url") as string) || "").trim() || null,
      card_overlay: overlayRaw,
      updated_at: new Date().toISOString(),
    };
    if (editing?.id) {
      const { error } = await supabase.from("promotions").update(payload).eq("id", editing.id);
      if (error) {
        alert(`Erreur lors de l'enregistrement : ${error.message}`);
        return;
      }
    } else {
      const { error } = await supabase.from("promotions").insert([payload]);
      if (error) {
        alert(`Erreur lors de la création : ${error.message}`);
        return;
      }
    }
    setEditing(null);
    setIsAdding(false);
    setSelectedProductIds([]);
    setProductSearch("");
    fetchPromotions();
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Supprimer cette promotion ?")) return;
    const { error } = await supabase.from("promotions").delete().eq("id", id);
    if (error) {
      alert(`Erreur lors de la suppression : ${error.message}`);
      return;
    }
    fetchPromotions();
  };

  if (loading) {
    return (
      <div className="p-8 flex justify-center">
        <Loader2 className="animate-spin" size={32} />
      </div>
    );
  }

  return (
    <div>
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 md:mb-8 gap-3">
        <h1 className="text-xl md:text-2xl font-bold text-gray-800">Promotions &amp; publicité</h1>
        <button
          type="button"
          onClick={() => {
            setIsAdding(true);
            setEditing({
              title: "",
              discount_text: "20%",
              description: "",
              link_url: "",
              is_active: true,
              sort_order: promotions.length,
              card_overlay: "medium",
              parent_category: "",
            });
            setSelectedProductIds([]);
            setProductSearch("");
            fetchProducts("");
          }}
          className="bg-[#0066CC] text-white px-4 py-2 rounded-lg font-bold text-sm flex items-center gap-2"
        >
          <Plus size={18} /> Nouvelle promotion
        </button>
      </header>

      <p className="text-gray-600 text-sm mb-6 leading-relaxed">
        <strong>Catégorie mère vide</strong> : la promotion s&apos;affiche dans le <strong>bandeau orange</strong> en haut
        du site. Avec <strong>Auto, Moto, Camion ou Tracteurs</strong> : elle apparaît dans le{" "}
        <strong>carrousel d&apos;offres</strong> au-dessus des meilleures ventes sur :{" "}
        <strong>Auto</strong> → page d&apos;accueil <code className="text-xs bg-gray-100 px-1 rounded">/</code> ;{" "}
        <strong>Moto</strong> → <code className="text-xs bg-gray-100 px-1 rounded">/moto</code> ;{" "}
        <strong>Camion</strong> → <code className="text-xs bg-gray-100 px-1 rounded">/camion</code> ;{" "}
        <strong>Tracteurs</strong> → <code className="text-xs bg-gray-100 px-1 rounded">/tracteurs</code> ; et les pages{" "}
        <code className="text-xs bg-gray-100 px-1 rounded">/categorie/…</code> rattachées à cette famille. Sur l&apos;accueil{" "}
        <code className="text-xs bg-gray-100 px-1 rounded">/</code>, un carrousel est affiché pour chaque famille qui a au moins une promotion active.
        Pour le carrousel, vous pouvez ajouter une <strong>image de fond</strong> avec un voile pour garder le texte lisible.
      </p>
      {errorMsg && (
        <div className="mb-4 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">{errorMsg}</div>
      )}

      <div className="space-y-4">
        {promotions.map((p) => (
          <div
            key={p.id}
            className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 md:p-5 flex flex-wrap items-center justify-between gap-3"
          >
            <div className="flex items-center gap-3 flex-1 min-w-0">
              <div className="w-10 h-10 rounded-lg bg-amber-100 flex items-center justify-center flex-shrink-0">
                <Tag className="text-amber-600" size={20} />
              </div>
              <div className="min-w-0">
                <p className="font-bold text-gray-800 truncate">{p.title}</p>
                <p className="text-sm text-gray-500">
                  {p.parent_category && (
                    <span className="inline-block mr-2 text-xs font-bold uppercase text-blue-700 bg-blue-50 px-2 py-0.5 rounded">
                      {p.parent_category}
                    </span>
                  )}
                  {p.card_image_url && (
                    <span className="inline-flex items-center gap-1 mr-2 text-xs text-violet-700 bg-violet-50 px-2 py-0.5 rounded">
                      <ImageIcon size={12} /> Fond
                    </span>
                  )}
                  {p.discount_text && <span className="text-green-600 font-medium">{p.discount_text}</span>}
                  {p.discount_text && p.description && " · "}
                  {p.description && <span className="truncate block">{p.description}</span>}
                </p>
              </div>
              {!p.is_active && (
                <span className="text-xs bg-gray-200 text-gray-600 px-2 py-0.5 rounded">Inactive</span>
              )}
            </div>
            <div className="flex gap-2">
              <button
                type="button"
                onClick={() => {
                  setEditing(p);
                  setSelectedProductIds(parseProductIdsFromLink(p.link_url));
                  setProductSearch("");
                  fetchProducts(p.parent_category);
                }}
                className="text-blue-600 hover:bg-blue-50 px-3 py-1.5 rounded text-sm font-medium"
              >
                Modifier
              </button>
              <button
                type="button"
                onClick={() => handleDelete(p.id)}
                className="text-red-600 hover:bg-red-50 px-3 py-1.5 rounded text-sm font-medium flex items-center gap-1"
              >
                <Trash2 size={14} /> Supprimer
              </button>
            </div>
          </div>
        ))}
        {promotions.length === 0 && !editing && !isAdding && (
          <div className="bg-gray-50 rounded-xl border border-dashed border-gray-200 p-12 text-center text-gray-500">
            Aucune promotion. Cliquez sur « Nouvelle promotion » pour en créer une.
          </div>
        )}
      </div>

      {(editing || isAdding) && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4 overflow-y-auto">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-xl my-8 max-h-[95vh] overflow-y-auto">
            <div className="p-4 border-b flex justify-between items-center sticky top-0 bg-white z-10">
              <h3 className="font-bold text-lg">{editing?.id ? "Modifier" : "Nouvelle"} promotion</h3>
              <button
                type="button"
                onClick={() => {
                  setEditing(null);
                  setIsAdding(false);
                }}
                className="text-gray-400 hover:text-gray-600 text-2xl leading-none"
                aria-label="Fermer"
              >
                &times;
              </button>
            </div>
            <form onSubmit={handleSave} className="p-4 md:p-6 space-y-4">
              <div>
                <label className="block text-xs font-bold text-gray-500 mb-1">Titre *</label>
                <input
                  name="title"
                  defaultValue={editing?.title}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2"
                  placeholder="Ex. : Jusqu'à 80 € remboursés"
                  required
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 mb-1">Texte d&apos;accroche / promo</label>
                <input
                  name="discount_text"
                  defaultValue={editing?.discount_text}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2"
                  placeholder="Ex. : 20 %, ou texte utilisé sur le badge si le champ « Badge » est vide"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 mb-1">Description (sous-titre)</label>
                <textarea
                  name="description"
                  defaultValue={editing?.description}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2"
                  rows={2}
                  placeholder="Ex. : Sur les pneus Hankook jusqu'au 30/06"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 mb-1">Lien (optionnel)</label>
                <input
                  name="link_url"
                  defaultValue={editing?.link_url}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2"
                  placeholder="Vide = page Recherche filtrée (catégorie + promo). Sinon URL interne ou https://…"
                />
                <p className="text-xs text-gray-500 mt-1">
                  Si le champ est vide, un clic sur la carte ouvre <strong>/search</strong> avec la catégorie mère et
                  l&apos;identifiant de la promotion.
                </p>
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 mb-1">Catégorie mère (carrousel)</label>
                <select
                  name="parent_category"
                  defaultValue={editing?.parent_category || ""}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2 bg-white"
                  onChange={(e) => {
                    const next = e.target.value;
                    setSelectedProductIds([]);
                    fetchProducts(next);
                  }}
                >
                  <option value="">— Bandeau général uniquement (pas de carrousel)</option>
                  <option value="Auto">Auto</option>
                  <option value="Moto">Moto</option>
                  <option value="Camion">Camion</option>
                  <option value="Tracteurs">Tracteurs</option>
                </select>
              </div>
              <div className="rounded-xl border border-gray-200 bg-white p-4 space-y-3">
                <p className="text-xs font-bold text-gray-600 uppercase tracking-wide">Produits de la promotion</p>
                <input
                  type="text"
                  value={productSearch}
                  onChange={(e) => setProductSearch(e.target.value)}
                  placeholder="Rechercher un produit…"
                  className="w-full border border-gray-300 rounded-lg px-3 py-2"
                />
                <div className="max-h-52 overflow-y-auto border border-gray-200 rounded-lg p-2 space-y-1 bg-gray-50">
                  {productsLoading ? (
                    <div className="flex items-center gap-2 text-sm text-gray-500 px-1 py-2">
                      <Loader2 size={14} className="animate-spin" />
                      Chargement des produits...
                    </div>
                  ) : (
                    products
                      .filter((p) => {
                        const q = productSearch.trim().toLowerCase();
                        if (!q) return true;
                        return `${p.name || ""} ${p.brand || ""}`.toLowerCase().includes(q);
                      })
                      .map((p) => (
                        <label key={p.id} className="flex items-start gap-2 rounded px-2 py-1 hover:bg-white">
                          <input
                            type="checkbox"
                            checked={selectedProductIds.includes(p.id)}
                            onChange={(e) => {
                              setSelectedProductIds((prev) =>
                                e.target.checked ? [...prev, p.id] : prev.filter((id) => id !== p.id)
                              );
                            }}
                            className="mt-1"
                          />
                          <span className="text-xs text-gray-700">
                            {p.name} {p.brand ? <strong>({p.brand})</strong> : null}
                          </span>
                        </label>
                      ))
                  )}
                </div>
                <p className="text-xs text-gray-500">
                  {selectedProductIds.length > 0
                    ? `${selectedProductIds.length} produit(s) sélectionné(s).`
                    : "Aucun produit sélectionné : la promo ouvre la recherche générale de la catégorie."}
                </p>
                {selectedProductsLabel.length > 0 && (
                  <div className="text-xs text-gray-600 max-h-20 overflow-y-auto">
                    {selectedProductsLabel.slice(0, 6).join(" • ")}
                    {selectedProductsLabel.length > 6 ? " • ..." : ""}
                  </div>
                )}
              </div>

              <div className="rounded-xl border border-gray-200 bg-gray-50/80 p-4 space-y-3">
                <p className="text-xs font-bold text-gray-600 uppercase tracking-wide">Carte carrousel</p>
                <div>
                  <label className="block text-xs font-bold text-gray-500 mb-1">Image de fond (URL)</label>
                  <input
                    name="card_image_url"
                    defaultValue={editing?.card_image_url || ""}
                    className="w-full border border-gray-300 rounded-lg px-3 py-2 bg-white"
                    placeholder="https://… (visible uniquement si une catégorie mère est choisie)"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-500 mb-1">Superposition (voile sombre)</label>
                  <select
                    name="card_overlay"
                    defaultValue={editing?.card_overlay || "medium"}
                    className="w-full border border-gray-300 rounded-lg px-3 py-2 bg-white"
                  >
                    {OVERLAY_OPTIONS.map((o) => (
                      <option key={o.value} value={o.value}>
                        {o.label}
                      </option>
                    ))}
                  </select>
                </div>
                <p className="text-xs text-gray-500">
                  Laissez vide pour le fond dégradé par défaut. L&apos;image est recouverte d&apos;un dégradé sombre
                  pour garder le texte blanc lisible.
                </p>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-gray-500 mb-1">Texte du badge</label>
                  <input
                    name="badge_text"
                    defaultValue={editing?.badge_text || ""}
                    className="w-full border border-gray-300 rounded-lg px-3 py-2"
                    placeholder="Ex. : PROMO, OFFRE"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-500 mb-1">Couleur du badge</label>
                  <select
                    name="badge_color"
                    defaultValue={editing?.badge_color || "red"}
                    className="w-full border border-gray-300 rounded-lg px-3 py-2 bg-white"
                  >
                    <option value="red">Rouge</option>
                    <option value="green">Vert</option>
                    <option value="blue">Bleu</option>
                    <option value="orange">Orange</option>
                  </select>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-gray-500 mb-1">Date de début</label>
                  <input
                    type="datetime-local"
                    name="start_date"
                    defaultValue={editing?.start_date ? editing.start_date.slice(0, 16) : ""}
                    className="w-full border border-gray-300 rounded-lg px-3 py-2"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-500 mb-1">Date de fin</label>
                  <input
                    type="datetime-local"
                    name="end_date"
                    defaultValue={editing?.end_date ? editing.end_date.slice(0, 16) : ""}
                    className="w-full border border-gray-300 rounded-lg px-3 py-2"
                  />
                </div>
              </div>
              <div className="flex items-center gap-2">
                <input
                  type="checkbox"
                  name="is_active"
                  id="promo_active"
                  defaultChecked={editing?.is_active !== false}
                  className="rounded text-blue-600"
                />
                <label htmlFor="promo_active" className="text-sm font-medium text-gray-700">
                  Promotion active (visible sur le site)
                </label>
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 mb-1">Ordre d&apos;affichage</label>
                <input
                  type="number"
                  name="sort_order"
                  defaultValue={editing?.sort_order ?? 0}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2"
                />
              </div>
              <div className="flex gap-2 pt-2">
                <button type="submit" className="bg-[#0066CC] text-white px-4 py-2 rounded-lg font-bold text-sm">
                  Enregistrer
                </button>
                <button
                  type="button"
                  onClick={() => {
                    setEditing(null);
                    setIsAdding(false);
                  }}
                  className="bg-gray-200 text-gray-700 px-4 py-2 rounded-lg font-bold text-sm"
                >
                  Annuler
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useState, useEffect, useRef } from "react";
import { createClient } from "@/lib/supabase";
import { Settings, Trash2, Loader2, ImageIcon } from "lucide-react";

type HeroOverlay = "strong" | "medium" | "soft";

export default function SubcategoriesSection() {
  const supabase = createClient();
  const [subcategories, setSubcategories] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [editingSub, setEditingSub] = useState<any>(null);
  const [isAdding, setIsAdding] = useState(false);
  const [filterParent, setFilterParent] = useState<string>("");
  const [heroImageUrl, setHeroImageUrl] = useState("");
  const [heroOverlay, setHeroOverlay] = useState<HeroOverlay>("medium");
  const [ingestHeroBusy, setIngestHeroBusy] = useState(false);
  const formRef = useRef<HTMLFormElement>(null);

  const fetchSubcategories = async () => {
    setLoading(true);
    let query = supabase.from('menu_subcategories').select('*').order('parent_category').order('sort_order');
    if (filterParent) {
      query = query.eq('parent_category', filterParent);
    }
    const { data } = await query;
    setSubcategories(data || []);
    setLoading(false);
  };

  useEffect(() => {
    fetchSubcategories();
  }, [filterParent]);

  useEffect(() => {
    if (editingSub) {
      setHeroImageUrl((editingSub.hero_image_url as string) || "");
      const o = String(editingSub.hero_overlay || "medium").toLowerCase();
      setHeroOverlay(o === "strong" || o === "soft" ? o : "medium");
    }
  }, [editingSub]);

  const ingestHeroFromUrl = async () => {
    const slugInput = formRef.current?.elements.namedItem("slug") as HTMLInputElement | null;
    const slug = (slugInput?.value || editingSub?.slug || "").trim();
    const url = heroImageUrl.trim();
    if (!slug) {
      alert("Indiquez le slug avant d'importer l'image.");
      return;
    }
    if (!url) {
      alert("Indiquez l'URL de l'image à importer.");
      return;
    }
    setIngestHeroBusy(true);
    try {
      const res = await fetch("/api/admin/ingest-image-url", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ url, kind: "subcategory", subcategorySlug: slug }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(typeof data.error === "string" ? data.error : "Échec de l'import");
      if (!data.url || typeof data.url !== "string") throw new Error("Réponse serveur invalide");
      setHeroImageUrl(data.url);
    } catch (err) {
      alert(err instanceof Error ? err.message : "Erreur");
    } finally {
      setIngestHeroBusy(false);
    }
  };

  const handleSave = async (e: React.FormEvent, subData: any) => {
    e.preventDefault();
    const data = {
      ...subData,
      sort_order: parseInt(subData.sort_order, 10) || 0,
      is_active: subData.is_active === "true" || subData.is_active === true,
      product_category_filter: subData.product_category_filter || subData.parent_category,
      hero_image_url: heroImageUrl.trim() || null,
      hero_overlay: heroOverlay,
    };
    
    if (subData.id) {
      await supabase.from('menu_subcategories').update(data).eq('id', subData.id);
    } else {
      await supabase.from('menu_subcategories').insert([data]);
    }
    setEditingSub(null);
    setIsAdding(false);
    fetchSubcategories();
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Supprimer cette sous-catégorie ?')) return;
    await supabase.from('menu_subcategories').delete().eq('id', id);
    fetchSubcategories();
  };

  if (loading) return <div className="p-8 flex justify-center"><Loader2 className="animate-spin" /></div>;

  return (
    <div>
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 md:mb-8 gap-3">
        <h1 className="text-xl md:text-2xl font-bold text-gray-800">Gestion des Sous-catégories du Menu</h1>
        <button
          onClick={() => {
            setIsAdding(true);
            setEditingSub({
              name: "",
              slug: "",
              parent_category: "Auto",
              product_category_filter: "Auto",
              icon_name: "",
              sort_order: 0,
              is_active: true,
              hero_image_url: "",
              hero_overlay: "medium",
            });
          }}
          className="bg-blue-600 text-white px-3 py-2 md:px-4 md:py-2 rounded-lg font-bold text-sm md:text-base w-full sm:w-auto"
        >
          + Nouvelle Sous-catégorie
        </button>
      </header>

      {/* Filter */}
      <div className="mb-4">
        <label className="block text-xs font-bold text-gray-500 mb-1">Filtrer par catégorie parente:</label>
        <select
          value={filterParent}
          onChange={(e) => setFilterParent(e.target.value)}
          className="border border-gray-300 rounded px-3 py-2 text-sm"
        >
          <option value="">Toutes</option>
          <option value="Auto">Auto</option>
          <option value="Moto">Moto</option>
          <option value="Camion">Camion</option>
          <option value="Tracteur">Tracteur</option>
        </select>
      </div>

      {/* Mobile Cards View */}
      <div className="md:hidden space-y-3">
        {subcategories.map((sub) => (
          <div key={sub.id} className="bg-white rounded-xl shadow-sm border border-gray-100 p-4">
            <div className="flex justify-between items-start">
              <div className="flex-1 pr-2">
                <p className="font-bold text-gray-800 text-sm mb-1">{sub.name}</p>
                <p className="text-gray-500 text-xs mb-1">Parent: {sub.parent_category} | Produit: {sub.product_category_filter || sub.parent_category}</p>
                <p className="text-blue-600 text-xs font-mono">{sub.slug}</p>
              </div>
              <div className="flex gap-2">
                <button
                  onClick={() => setEditingSub(sub)}
                  className="text-blue-600 p-1.5"
                >
                  <Settings size={16} />
                </button>
                <button
                  onClick={() => handleDelete(sub.id)}
                  className="text-red-600 p-1.5"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            </div>
          </div>
        ))}
        {subcategories.length === 0 && (
          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-8 text-center text-gray-400">
            Aucune sous-catégorie trouvée
          </div>
        )}
      </div>

      {/* Desktop Table View */}
      <div className="hidden md:block bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
        <table className="w-full text-left text-sm">
          <thead className="bg-gray-50 border-b border-gray-100">
            <tr>
              <th className="px-6 py-4">Nom</th>
              <th className="px-6 py-4">Slug</th>
              <th className="px-6 py-4">Catégorie Parente</th>
              <th className="px-6 py-4">Catégorie Produit</th>
              <th className="px-6 py-4">Ordre</th>
              <th className="px-6 py-4">Statut</th>
              <th className="px-6 py-4">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {subcategories.map((sub) => (
              <tr key={sub.id} className="hover:bg-gray-50">
                <td className="px-6 py-4 font-medium text-gray-800">{sub.name}</td>
                <td className="px-6 py-4 font-mono text-blue-600 text-xs">{sub.slug}</td>
                <td className="px-6 py-4 text-gray-600">{sub.parent_category}</td>
                <td className="px-6 py-4">
                  <span className="px-2 py-1 bg-blue-100 text-blue-700 rounded text-xs font-bold">
                    {sub.product_category_filter || sub.parent_category}
                  </span>
                </td>
                <td className="px-6 py-4 text-gray-500">{sub.sort_order}</td>
                <td className="px-6 py-4">
                  <span className={`px-2 py-1 rounded-full text-xs font-bold ${
                    sub.is_active ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-700'
                  }`}>
                    {sub.is_active ? 'Actif' : 'Inactif'}
                  </span>
                </td>
                <td className="px-6 py-4">
                  <div className="flex gap-2">
                    <button
                      onClick={() => setEditingSub(sub)}
                      className="text-blue-600 hover:text-blue-800 p-1"
                      title="Modifier"
                    >
                      <Settings size={16} />
                    </button>
                    <button
                      onClick={() => handleDelete(sub.id)}
                      className="text-red-600 hover:text-red-800 p-1"
                      title="Supprimer"
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>
                </td>
              </tr>
            ))}
            {subcategories.length === 0 && (
              <tr>
                <td colSpan={7} className="px-6 py-8 text-center text-gray-400">
                  Aucune sous-catégorie trouvée
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {(editingSub || isAdding) && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-2 md:p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl max-h-[95vh] overflow-y-auto">
            <div className="p-4 md:p-6 border-b sticky top-0 bg-white z-10 flex justify-between items-center">
              <h3 className="font-bold text-lg">{editingSub?.id ? 'Modifier' : 'Ajouter'} une sous-catégorie</h3>
              <button
                onClick={() => {
                  setEditingSub(null);
                  setIsAdding(false);
                }}
                className="text-gray-400 hover:text-gray-600 text-2xl"
              >
                &times;
              </button>
            </div>
            <form
              ref={formRef}
              onSubmit={(e) => {
                e.preventDefault();
                const formData = new FormData(e.target as HTMLFormElement);
                const data = Object.fromEntries(formData.entries());
                handleSave(e, { ...editingSub, ...data });
              }}
              className="p-4 md:p-6 space-y-4"
            >
              <div>
                <label className="block text-xs font-bold text-gray-500 mb-1">Nom *</label>
                <input
                  name="name"
                  type="text"
                  defaultValue={editingSub?.name || ''}
                  className="w-full border border-gray-300 rounded px-3 py-2"
                  required
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 mb-1">Slug *</label>
                <input
                  name="slug"
                  type="text"
                  defaultValue={editingSub?.slug || ''}
                  className="w-full border border-gray-300 rounded px-3 py-2 font-mono text-sm"
                  required
                  placeholder="pneus-4-saisons"
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-gray-500 mb-1">Catégorie Parente *</label>
                  <select
                    name="parent_category"
                    defaultValue={editingSub?.parent_category || 'Auto'}
                    className="w-full border border-gray-300 rounded px-3 py-2"
                    required
                  >
                    <option value="Auto">Auto</option>
                    <option value="Moto">Moto</option>
                    <option value="Camion">Camion</option>
                    <option value="Tracteur">Tracteur</option>
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-500 mb-1">Catégorie Produit *</label>
                  <select
                    name="product_category_filter"
                    defaultValue={editingSub?.product_category_filter || editingSub?.parent_category || 'Auto'}
                    className="w-full border border-gray-300 rounded px-3 py-2"
                    required
                  >
                    <option value="Auto">Auto</option>
                    <option value="Moto">Moto</option>
                    <option value="Camion">Camion</option>
                    <option value="Tracteurs">Tracteurs</option>
                  </select>
                  <p className="text-[10px] text-gray-400 mt-1">Type de produits filtrés sur la page</p>
                </div>
              </div>

              <div className="rounded-xl border border-gray-200 bg-slate-50/80 p-4 space-y-3">
                <p className="text-xs font-bold text-gray-600 uppercase tracking-wide flex items-center gap-2">
                  <ImageIcon size={14} /> Hero (bandeau + formulaire)
                </p>
                <div>
                  <label className="block text-xs font-bold text-gray-500 mb-1">Image de fond (URL)</label>
                  <input
                    type="text"
                    value={heroImageUrl}
                    onChange={(e) => setHeroImageUrl(e.target.value)}
                    className="w-full border border-gray-300 rounded px-3 py-2 bg-white"
                    placeholder="https://… ou URL /imagem/… après import"
                  />
                </div>
                <div className="flex flex-col sm:flex-row gap-2 sm:items-end">
                  <div className="flex-1">
                    <label className="block text-xs font-bold text-gray-500 mb-1">Superposition sur la photo</label>
                    <select
                      value={heroOverlay}
                      onChange={(e) => setHeroOverlay(e.target.value as HeroOverlay)}
                      className="w-full border border-gray-300 rounded px-3 py-2 bg-white"
                    >
                      <option value="strong">Forte (texte très lisible)</option>
                      <option value="medium">Moyenne (recommandé)</option>
                      <option value="soft">Légère (photo plus visible)</option>
                    </select>
                  </div>
                  <button
                    type="button"
                    onClick={ingestHeroFromUrl}
                    disabled={ingestHeroBusy}
                    className="shrink-0 bg-slate-800 text-white px-3 py-2 rounded-lg text-sm font-bold disabled:opacity-50"
                  >
                    {ingestHeroBusy ? "Import…" : "Importer depuis URL"}
                  </button>
                </div>
                <p className="text-[11px] text-gray-500 leading-relaxed">
                  Renseignez le <strong>slug</strong> puis collez une URL externe et cliquez sur « Importer » pour
                  héberger l&apos;image sur votre domaine. Laissez vide pour l&apos;image par défaut du site.
                </p>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-gray-500 mb-1">Icône (optionnel)</label>
                  <input
                    name="icon_name"
                    type="text"
                    defaultValue={editingSub?.icon_name || ''}
                    className="w-full border border-gray-300 rounded px-3 py-2"
                    placeholder="Car, Bike, Truck, etc."
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-500 mb-1">Ordre</label>
                  <input
                    name="sort_order"
                    type="number"
                    defaultValue={editingSub?.sort_order || 0}
                    className="w-full border border-gray-300 rounded px-3 py-2"
                  />
                </div>
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 mb-1">Statut</label>
                <select
                  name="is_active"
                  defaultValue={editingSub?.is_active ? 'true' : 'false'}
                  className="w-full border border-gray-300 rounded px-3 py-2"
                >
                  <option value="true">Actif</option>
                  <option value="false">Inactif</option>
                </select>
              </div>
              <div className="flex flex-col sm:flex-row justify-end gap-2 pt-4">
                <button
                  type="button"
                  onClick={() => {
                    setEditingSub(null);
                    setIsAdding(false);
                  }}
                  className="px-4 py-2 border rounded font-medium order-2 sm:order-1"
                >
                  Annuler
                </button>
                <button
                  type="submit"
                  className="bg-blue-600 text-white px-4 py-2 rounded font-bold order-1 sm:order-2"
                >
                  Sauvegarder
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

