"use client";

import React, { useEffect, useMemo, useState } from 'react';
import { Inbox, Loader2, RefreshCcw, Send } from 'lucide-react';

type EmailThread = {
  id: string;
  subject: string | null;
  from_name: string | null;
  from_email: string;
  preview: string | null;
  status: string;
  last_message_at: string;
};

type EmailMessage = {
  id: string;
  direction: 'inbound' | 'outbound';
  from_email: string | null;
  to_email: string | null;
  subject: string | null;
  body_text: string | null;
  created_at: string;
};

export default function SupportInboxSection() {
  const [threads, setThreads] = useState<EmailThread[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [messages, setMessages] = useState<EmailMessage[]>([]);
  const [reply, setReply] = useState('');
  const [loading, setLoading] = useState(true);
  const [syncing, setSyncing] = useState(false);
  const [sending, setSending] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const selected = useMemo(() => threads.find((thread) => thread.id === selectedId) ?? null, [threads, selectedId]);

  const loadThreads = async () => {
    const response = await fetch('/api/support/email/threads');
    const data = await response.json();
    if (response.ok) {
      setThreads(data.threads || []);
      if (!selectedId && data.threads?.[0]?.id) setSelectedId(data.threads[0].id);
      setError(null);
    } else {
      setError(data.error || 'Falha ao carregar inbox.');
    }
    setLoading(false);
  };

  const loadThread = async (threadId: string) => {
    const response = await fetch(`/api/support/email/thread/${threadId}`);
    const data = await response.json();
    if (response.ok) {
      setMessages(data.messages || []);
      setError(null);
    } else {
      setError(data.error || 'Falha ao abrir thread.');
    }
  };

  useEffect(() => {
    loadThreads();
  }, []);

  useEffect(() => {
    if (selectedId) loadThread(selectedId);
  }, [selectedId]);

  const syncInbox = async () => {
    setSyncing(true);
    const response = await fetch('/api/support/email/sync', { method: 'POST' });
    const data = await response.json();
    if (!response.ok) {
      setError(data.error || 'Falha ao sincronizar emails.');
    } else {
      setError(null);
      await loadThreads();
      if (selectedId) await loadThread(selectedId);
    }
    setSyncing(false);
  };

  const sendReply = async () => {
    if (!selected || !reply.trim() || sending) return;
    setSending(true);
    const response = await fetch('/api/support/email/send', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        threadId: selected.id,
        to: selected.from_email,
        subject: selected.subject || 'Réponse MecaniDoc',
        body: reply,
      }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) {
      setError(data.error || 'Falha ao enviar email.');
    } else {
      setReply('');
      setError(null);
      await loadThread(selected.id);
      await loadThreads();
    }
    setSending(false);
  };

  return (
    <div className="space-y-6">
      <header className="flex items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">Inbox Email</h1>
          <p className="text-sm text-gray-500">
            Synchronisation IMAP et réponses SMTP. Configurez les serveurs dans <strong>Configuration Globale</strong> → Messagerie support (ou variables SUPPORT_* sur le serveur).
          </p>
        </div>
        <button onClick={syncInbox} disabled={syncing} className="inline-flex items-center gap-2 rounded-lg border px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:opacity-50">
          {syncing ? <Loader2 className="animate-spin" size={16} /> : <RefreshCcw size={16} />} Synchroniser
        </button>
      </header>

      {error ? <div className="rounded-lg border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-900">{error}</div> : null}

      <div className="grid gap-6 lg:grid-cols-[360px_1fr]">
        <section className="rounded-xl border bg-white">
          <div className="border-b p-4 font-semibold text-gray-800">Boîte de réception</div>
          <div className="max-h-[70vh] overflow-y-auto">
            {loading ? <div className="flex justify-center p-6"><Loader2 className="animate-spin" /></div> : null}
            {!loading && threads.length === 0 ? (
              <div className="flex flex-col items-center gap-3 p-8 text-center text-sm text-gray-500">
                <Inbox size={28} />
                <span>Aucun email synchronisé pour le moment.</span>
              </div>
            ) : null}
            {threads.map((thread) => (
              <button key={thread.id} onClick={() => setSelectedId(thread.id)} className={`w-full border-b p-4 text-left hover:bg-gray-50 ${selectedId === thread.id ? 'bg-blue-50' : ''}`}>
                <div className="font-medium text-gray-800">{thread.subject || '(Sans sujet)'}</div>
                <div className="mt-1 text-xs text-gray-500">{thread.from_name || thread.from_email} • {thread.status}</div>
                <div className="mt-2 line-clamp-2 text-sm text-gray-600">{thread.preview || 'Sans aperçu'}</div>
              </button>
            ))}
          </div>
        </section>

        <section className="rounded-xl border bg-white">
          {!selected ? (
            <div className="flex min-h-[500px] items-center justify-center text-gray-500">Sélectionnez un email.</div>
          ) : (
            <>
              <div className="border-b p-4">
                <div className="font-semibold text-gray-800">{selected.subject || '(Sans sujet)'}</div>
                <div className="text-sm text-gray-500">{selected.from_name || selected.from_email}</div>
              </div>
              <div className="max-h-[55vh] space-y-3 overflow-y-auto bg-gray-50 p-4">
                {messages.map((message) => (
                  <div key={message.id} className={`flex ${message.direction === 'outbound' ? 'justify-end' : 'justify-start'}`}>
                    <div className={`max-w-[85%] rounded-xl px-4 py-3 text-sm ${message.direction === 'outbound' ? 'bg-blue-600 text-white' : 'border bg-white text-gray-800'}`}>
                      <div className="mb-1 text-xs opacity-70">{message.direction === 'outbound' ? message.to_email : message.from_email}</div>
                      <div className="whitespace-pre-wrap">{message.body_text || '(Sans contenu texte)'}</div>
                    </div>
                  </div>
                ))}
              </div>
              <div className="border-t p-4">
                <div className="flex gap-2">
                  <textarea value={reply} onChange={(event) => setReply(event.target.value)} placeholder="Répondre par email..." className="min-h-[120px] flex-1 rounded-lg border px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-blue-500" />
                  <button onClick={sendReply} disabled={sending || !reply.trim()} className="inline-flex items-center justify-center rounded-lg bg-blue-600 px-4 text-white hover:bg-blue-700 disabled:opacity-50">
                    {sending ? <Loader2 className="animate-spin" size={18} /> : <Send size={18} />}
                  </button>
                </div>
              </div>
            </>
          )}
        </section>
      </div>
    </div>
  );
}

"use client";

import React, { Fragment, useEffect, useState } from 'react';
import { createClient } from '@/lib/supabase';
import { useRouter } from 'next/navigation';
import { Loader2, Download, DollarSign, Package, CheckCircle, Clock, ChevronDown, ChevronRight } from 'lucide-react';
import OrderPurchaseDetails from '@/components/OrderPurchaseDetails';

export default function SalesPage() {
  const [sales, setSales] = useState<any[]>([]);
  const [statistics, setStatistics] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({
    startDate: '',
    endDate: '',
    status: '',
  });
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [masterReady, setMasterReady] = useState(false);
  const supabase = createClient();
  const router = useRouter();

  useEffect(() => {
    (async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        router.push('/auth/login');
        return;
      }
      const { data: profile } = await supabase
        .from('profiles')
        .select('role')
        .eq('id', user.id)
        .single();
      if (profile?.role !== 'master') {
        router.push('/dashboard/admin');
        return;
      }
      setMasterReady(true);
    })();
  }, [router, supabase]);

  const fetchSales = async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (filters.startDate && filters.endDate) {
        params.append('startDate', filters.startDate);
        params.append('endDate', filters.endDate);
      }
      if (filters.status) params.append('status', filters.status);

      const response = await fetch(`/api/sales?${params.toString()}`);
      const data = await response.json();

      if (response.ok) {
        setSales(data.orders || []);
        setStatistics(data.statistics || null);
      } else {
        console.error('Error fetching sales:', data.error);
      }
    } catch (error) {
      console.error('Error fetching sales:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (!masterReady) return;
    fetchSales();
    // eslint-disable-next-line react-hooks/exhaustive-deps -- recarregar quando filtros mudam
  }, [masterReady, filters]);

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('fr-FR', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const getStatusBadge = (status: string) => {
    const styles: Record<string, string> = {
      paid: 'bg-green-100 text-green-800',
      pending: 'bg-yellow-100 text-yellow-800',
      failed: 'bg-red-100 text-red-800',
      canceled: 'bg-orange-100 text-orange-800',
      refunded: 'bg-gray-100 text-gray-800',
      partially_refunded: 'bg-gray-100 text-gray-800',
    };
    const labels: Record<string, string> = {
      paid: 'Payé',
      pending: 'En attente',
      failed: 'Échoué',
      canceled: 'Annulé',
      refunded: 'Remboursé',
      partially_refunded: 'Remb. partiel',
    };

    return (
      <span className={`px-2 py-1 rounded text-xs font-medium ${styles[status] || styles.pending}`}>
        {labels[status] || status}
      </span>
    );
  };

  if (loading && !sales.length) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Loader2 className="animate-spin text-gray-400" size={32} />
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold text-gray-800">Ventes</h1>
        <button
          onClick={fetchSales}
          className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
        >
          <Download size={18} />
          Actualiser
        </button>
      </div>

      {/* Statistics */}
      {statistics && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-500 mb-1">Chiffre d'affaires</p>
                <p className="text-2xl font-bold text-gray-800">€{statistics.totalSales.toFixed(2)}</p>
              </div>
              <DollarSign className="text-green-600" size={32} />
            </div>
          </div>

          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-500 mb-1">Total commandes</p>
                <p className="text-2xl font-bold text-gray-800">{statistics.totalOrders}</p>
              </div>
              <Package className="text-blue-600" size={32} />
            </div>
          </div>

          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-500 mb-1">Commandes payées</p>
                <p className="text-2xl font-bold text-gray-800">{statistics.paidOrders}</p>
              </div>
              <CheckCircle className="text-green-600" size={32} />
            </div>
          </div>

          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-500 mb-1">En attente</p>
                <p className="text-2xl font-bold text-gray-800">{statistics.pendingOrders}</p>
              </div>
              <Clock className="text-yellow-600" size={32} />
            </div>
          </div>
        </div>
      )}

      {/* Filters */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100">
        <p className="text-sm text-gray-600 mb-3">
          Pour filtrer par période, indiquez <strong>les deux dates</strong> (début et fin). Une seule date
          laissée vide = toutes les commandes sont affichées. Le statut « Tous » n’applique aucun filtre
          de paiement.
        </p>
        <div className="flex flex-wrap gap-4 items-end">
          <div className="flex-1 min-w-[200px]">
            <label className="block text-sm font-medium text-gray-700 mb-1">Date de début</label>
            <input
              type="date"
              value={filters.startDate}
              onChange={(e) => setFilters({ ...filters, startDate: e.target.value })}
              className="w-full border border-gray-300 rounded-lg px-3 py-2"
            />
          </div>
          <div className="flex-1 min-w-[200px]">
            <label className="block text-sm font-medium text-gray-700 mb-1">Date de fin</label>
            <input
              type="date"
              value={filters.endDate}
              onChange={(e) => setFilters({ ...filters, endDate: e.target.value })}
              className="w-full border border-gray-300 rounded-lg px-3 py-2"
            />
          </div>
          <div className="flex-1 min-w-[200px]">
            <label className="block text-sm font-medium text-gray-700 mb-1">Statut</label>
            <select
              value={filters.status}
              onChange={(e) => setFilters({ ...filters, status: e.target.value })}
              className="w-full border border-gray-300 rounded-lg px-3 py-2"
            >
              <option value="">Tous</option>
              <option value="paid">Payé</option>
              <option value="pending">En attente</option>
              <option value="failed">Échoué</option>
              <option value="refunded">Remboursé</option>
            </select>
          </div>
          <button
            onClick={() => setFilters({ startDate: '', endDate: '', status: '' })}
            className="px-4 py-2 text-gray-600 hover:text-gray-800"
          >
            Réinitialiser
          </button>
        </div>
      </div>

      {/* Sales Table */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead className="bg-gray-50 border-b border-gray-200">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Commande</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Client</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Date</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Montant</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Statut</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Articles</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider w-12"></th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {sales.map((sale) => (
                <Fragment key={sale.id}>
                  <tr className="hover:bg-gray-50">
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="text-sm font-medium text-gray-900">#{sale.id.slice(0, 8)}</div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="text-sm text-gray-900">{sale.contact_name || sale.profiles?.full_name || 'N/A'}</div>
                      <div className="text-xs text-gray-500">{sale.contact_email || sale.profiles?.email || ''}</div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {formatDate(sale.created_at)}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="text-sm font-bold text-gray-900">€{parseFloat(sale.total_amount.toString()).toFixed(2)}</div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      {getStatusBadge(sale.payment_status || sale.status)}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {sale.order_items?.length || 0} article(s)
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <button
                        type="button"
                        onClick={() => setExpandedId(expandedId === sale.id ? null : sale.id)}
                        className="p-2 rounded-lg text-gray-500 hover:bg-gray-100 hover:text-gray-800"
                        aria-expanded={expandedId === sale.id}
                        title="Détails de la commande"
                      >
                        {expandedId === sale.id ? <ChevronDown size={20} /> : <ChevronRight size={20} />}
                      </button>
                    </td>
                  </tr>
                  {expandedId === sale.id && (
                    <tr>
                      <td colSpan={7} className="p-0 border-t border-gray-100">
                        <OrderPurchaseDetails order={sale} />
                      </td>
                    </tr>
                  )}
                </Fragment>
              ))}
            </tbody>
          </table>
        </div>

        {sales.length === 0 && (
          <div className="text-center py-12">
            <p className="text-gray-500">Aucune vente trouvée</p>
          </div>
        )}
      </div>
    </div>
  );
}

