"use client";

import React, { useState, useEffect } from 'react';
import { CheckCircle, Loader2 } from 'lucide-react';
import { createClient } from '@/lib/supabase';

export default function ApprovalsSection() { 
  const supabase = createClient();
  const [garages, setGarages] = useState<any[]>([]);
  const [pendingCustomers, setPendingCustomers] = useState<any[]>([]);
  const [pendingSuppliers, setPendingSuppliers] = useState<any[]>([]);
  const [companyNames, setCompanyNames] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(true);

  const loadAll = async () => {
    setLoading(true);
    const [gRes, pRes, sRes] = await Promise.all([
      supabase.from('garages').select('*').eq('is_approved', false).order('created_at', { ascending: false }),
      supabase
        .from('profiles')
        .select('id, email, full_name, created_at')
        .eq('role', 'customer')
        .eq('supplier_promotion_pending', true)
        .order('created_at', { ascending: false }),
      supabase.from('suppliers').select('*').eq('is_approved', false).order('created_at', { ascending: false }),
    ]);
    setGarages(gRes.data || []);
    const profiles = pRes.data || [];
    setPendingCustomers(profiles);
    const names: Record<string, string> = {};
    profiles.forEach((row: any) => {
      names[row.id] = row.full_name || row.email?.split('@')[0] || 'Fournisseur';
    });
    setCompanyNames(names);
    setPendingSuppliers(sRes.data || []);
    setLoading(false);
  };

  useEffect(() => {
    loadAll();
  }, []);

  const handleApproveGarage = async (id: string) => {
    await supabase.from('garages').update({ is_approved: true }).eq('id', id);
    setGarages(garages.filter(g => g.id !== id));
  };

  const handleRejectGarage = async (id: string) => {
    if(!confirm('Rejeter cette demande ?')) return;
    await supabase.from('garages').delete().eq('id', id);
    setGarages(garages.filter(g => g.id !== id));
  };

  const handlePromoteToSupplier = async (profileId: string) => {
    const companyName = (companyNames[profileId] || '').trim();
    if (!companyName) {
      alert('Indiquez un nom de société (raison sociale) pour ce fournisseur.');
      return;
    }
    const { data: existing } = await supabase.from('suppliers').select('id').eq('profile_id', profileId).maybeSingle();
    if (!existing) {
      const { error: insErr } = await supabase.from('suppliers').insert({
        profile_id: profileId,
        company_name: companyName,
        is_approved: true,
      });
      if (insErr) {
        alert(insErr.message);
        return;
      }
    } else {
      await supabase.from('suppliers').update({ is_approved: true, company_name: companyName }).eq('profile_id', profileId);
    }
    const { error: upErr } = await supabase
      .from('profiles')
      .update({ role: 'supplier', supplier_promotion_pending: false })
      .eq('id', profileId);
    if (upErr) {
      alert(upErr.message);
      return;
    }
    setPendingCustomers(pendingCustomers.filter(p => p.id !== profileId));
  };

  const handleDismissCustomerPromotion = async (profileId: string) => {
    if (!confirm('Retirer ce compte de la file ? Il restera client.')) return;
    await supabase.from('profiles').update({ supplier_promotion_pending: false }).eq('id', profileId);
    setPendingCustomers(pendingCustomers.filter(p => p.id !== profileId));
  };

  const handleApproveSupplierRow = async (id: string) => {
    await supabase.from('suppliers').update({ is_approved: true }).eq('id', id);
    setPendingSuppliers(pendingSuppliers.filter(s => s.id !== id));
  };

  const handleRejectSupplierRow = async (id: string) => {
    if (!confirm('Supprimer ce profil fournisseur non approuvé ?')) return;
    await supabase.from('suppliers').delete().eq('id', id);
    setPendingSuppliers(pendingSuppliers.filter(s => s.id !== id));
  };

  if (loading) return <div className="p-8 flex justify-center"><Loader2 className="animate-spin" /></div>;

  const totalPending =
    pendingCustomers.length + garages.length + pendingSuppliers.length;

  if (totalPending === 0) {
    return (
      <div>
        <h1 className="text-xl md:text-2xl font-bold mb-4 md:mb-6 text-gray-800">Approbations en attente</h1>
        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-8 text-center">
          <CheckCircle className="mx-auto text-green-500 mb-3" size={48} />
          <p className="text-gray-600">Aucune approbation en attente</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-10">
      <h1 className="text-xl md:text-2xl font-bold text-gray-800">Approbations en attente</h1>

      {/* Comptes clients → fournisseur */}
      <section>
        <h2 className="text-lg font-bold text-gray-800 mb-3 flex items-center gap-2">
          Comptes clients (promotion fournisseur)
          {pendingCustomers.length > 0 && (
            <span className="text-sm font-bold bg-amber-100 text-amber-800 px-2 py-0.5 rounded-full">{pendingCustomers.length}</span>
          )}
        </h2>
        {pendingCustomers.length === 0 ? (
          <p className="text-gray-500 text-sm">Aucun nouveau compte client en file.</p>
        ) : (
          <div className="space-y-3 md:space-y-4">
            {pendingCustomers.map((row) => (
              <div key={row.id} className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 md:p-6">
                <div className="flex flex-col gap-4">
                  <div>
                    <h3 className="font-bold text-gray-800">{row.full_name || 'Sans nom'}</h3>
                    <p className="text-gray-500 text-sm">{row.email}</p>
                    <p className="text-gray-400 text-xs mt-1">Inscrit le {new Date(row.created_at).toLocaleDateString('fr-FR')}</p>
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-gray-500 mb-1">Raison sociale (fournisseur)</label>
                    <input
                      type="text"
                      value={companyNames[row.id] ?? ''}
                      onChange={(e) => setCompanyNames((prev) => ({ ...prev, [row.id]: e.target.value }))}
                      className="w-full max-w-md border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-blue-500"
                      placeholder="Ex. Pneus Dupont SARL"
                    />
                  </div>
                  <div className="flex flex-wrap gap-2">
                    <button
                      type="button"
                      onClick={() => handlePromoteToSupplier(row.id)}
                      className="bg-green-600 text-white font-bold py-2 px-4 rounded-lg hover:bg-green-700 text-sm"
                    >
                      Transformer en fournisseur
                    </button>
                    <button
                      type="button"
                      onClick={() => handleDismissCustomerPromotion(row.id)}
                      className="bg-gray-100 text-gray-700 font-bold py-2 px-4 rounded-lg hover:bg-gray-200 text-sm"
                    >
                      Retirer de la file
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </section>

      {/* Garages */}
      <section>
        <h2 className="text-lg font-bold text-gray-800 mb-3 flex items-center gap-2">
          Garages partenaires
          {garages.length > 0 && (
            <span className="text-sm font-bold bg-blue-100 text-blue-800 px-2 py-0.5 rounded-full">{garages.length}</span>
          )}
        </h2>
        {garages.length === 0 ? (
          <p className="text-gray-500 text-sm">Aucune demande garage en attente.</p>
        ) : (
          <div className="space-y-3 md:space-y-4">
            {garages.map((garage) => (
              <div key={garage.id} className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 md:p-6">
                <div className="flex flex-col md:flex-row md:justify-between md:items-start gap-4">
                  <div className="flex-1">
                    <h3 className="font-bold text-gray-800 text-lg">{garage.name}</h3>
                    <p className="text-gray-500 text-sm mt-1">{garage.address}, {garage.city} {garage.zip_code}</p>
                    <p className="text-gray-500 text-sm">{garage.phone_primary}</p>
                    <p className="text-gray-400 text-xs mt-2">Demandé le: {new Date(garage.created_at).toLocaleDateString('fr-FR')}</p>
                  </div>
                  <div className="flex gap-2 w-full md:w-auto">
                    <button onClick={() => handleApproveGarage(garage.id)} className="flex-1 md:flex-none bg-green-600 text-white font-bold py-2 px-4 rounded hover:bg-green-700 transition-colors text-sm">
                      Approuver
                    </button>
                    <button onClick={() => handleRejectGarage(garage.id)} className="flex-1 md:flex-none bg-red-100 text-red-600 font-bold py-2 px-4 rounded hover:bg-red-200 transition-colors text-sm">
                      Rejeter
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </section>

      {/* Fournisseurs (ligne suppliers non approuvée) */}
      <section>
        <h2 className="text-lg font-bold text-gray-800 mb-3 flex items-center gap-2">
          Profils fournisseur (validation)
          {pendingSuppliers.length > 0 && (
            <span className="text-sm font-bold bg-violet-100 text-violet-800 px-2 py-0.5 rounded-full">{pendingSuppliers.length}</span>
          )}
        </h2>
        {pendingSuppliers.length === 0 ? (
          <p className="text-gray-500 text-sm">Aucun fournisseur en attente de validation.</p>
        ) : (
          <div className="space-y-3 md:space-y-4">
            {pendingSuppliers.map((s) => (
              <div key={s.id} className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 md:p-6 flex flex-col md:flex-row md:justify-between md:items-center gap-4">
                <div>
                  <h3 className="font-bold text-gray-800">{s.company_name}</h3>
                  <p className="text-gray-400 text-xs mt-1">{new Date(s.created_at).toLocaleDateString('fr-FR')}</p>
                </div>
                <div className="flex gap-2">
                  <button type="button" onClick={() => handleApproveSupplierRow(s.id)} className="bg-green-600 text-white font-bold py-2 px-4 rounded-lg hover:bg-green-700 text-sm">
                    Approuver
                  </button>
                  <button type="button" onClick={() => handleRejectSupplierRow(s.id)} className="bg-red-100 text-red-600 font-bold py-2 px-4 rounded-lg hover:bg-red-200 text-sm">
                    Rejeter
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </section>
    </div>
  );
}

"use client";

import React, { useState, useEffect, useRef } from 'react';
import { AlertTriangle, Loader2, Grid, Trash2, Upload } from 'lucide-react';
import { createClient } from '@/lib/supabase';
import { normalizeAdminImageUrl } from './shared';

export default function BrandsSection() {
  const supabase = createClient();
  const [brands, setBrands] = useState<any[]>([]);
  const [missingBrands, setMissingBrands] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [syncing, setSyncing] = useState(false);
  const [newName, setNewName] = useState('');
  const [newLogo, setNewLogo] = useState('');
  const [editingBrand, setEditingBrand] = useState<any>(null);
  const [logoUploadBusy, setLogoUploadBusy] = useState(false);
  const newLogoFileRef = useRef<HTMLInputElement>(null);
  const editLogoFileRef = useRef<HTMLInputElement>(null);

  const uploadBrandLogo = async (file: File, brandFolderId: string) => {
    setLogoUploadBusy(true);
    try {
      const fd = new FormData();
      fd.append('file', file);
      fd.append('brandId', brandFolderId);
      const res = await fetch('/api/admin/brand-logo', { method: 'POST', body: fd });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(typeof data.error === 'string' ? data.error : 'Échec du téléversement');
      if (!data.url) throw new Error('Réponse invalide du serveur');
      return data.url as string;
    } finally {
      setLogoUploadBusy(false);
    }
  };

  const fetchBrands = async () => {
    const { data } = await supabase.from('brands').select('*').order('name');
    setBrands(data || []);
    setLoading(false);
  };

  const findMissingBrands = async () => {
    // Buscar todas as marcas dos produtos
    const { data: products } = await supabase.from('products').select('brand');
    const { data: existingBrands } = await supabase.from('brands').select('name');

    if (products && existingBrands) {
      // Criar um set de marcas existentes (normalizado para lowercase)
      const existingNames = new Set(existingBrands.map((b: any) => b.name?.toLowerCase().trim()));

      // Encontrar marcas únicas dos produtos que não existem
      const productBrands = new Set<string>();
      products.forEach((p: any) => {
        if (p.brand && p.brand.trim()) {
          const brandName = p.brand.trim();
          if (!existingNames.has(brandName.toLowerCase())) {
            productBrands.add(brandName);
          }
        }
      });

      setMissingBrands(Array.from(productBrands).sort());
    }
  };

  useEffect(() => { 
    fetchBrands();
    findMissingBrands();
  }, []);

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    let logo = newLogo.trim();
    if (logo) {
      try {
        logo = await normalizeAdminImageUrl(logo, { kind: 'brand', brandId: 'pending' });
      } catch (err) {
        alert(err instanceof Error ? err.message : "Échec de l'import d'image");
        return;
      }
    }
    const { error } = await supabase.from('brands').insert([{ name: newName, logo_url: logo }]);
    if (error) {
      alert('Erreur lors de l\'ajout de la marque');
    } else {
      setNewName('');
      setNewLogo('');
      fetchBrands();
      findMissingBrands();
    }
  };

  const handleAddMissingBrand = async (brandName: string) => {
    const { error } = await supabase.from('brands').insert([{ name: brandName, logo_url: '' }]);
    if (error) {
      alert('Erreur: ' + error.message);
    } else {
      fetchBrands();
      setMissingBrands(missingBrands.filter(b => b !== brandName));
    }
  };

  const handleAddAllMissingBrands = async () => {
    if (missingBrands.length === 0) return;
    if (!confirm(`Ajouter ${missingBrands.length} marque(s) manquante(s) ?`)) return;

    setSyncing(true);
    const brandsToInsert = missingBrands.map(name => ({ name, logo_url: '' }));
    const { error } = await supabase.from('brands').insert(brandsToInsert);

    if (error) {
      alert('Erreur: ' + error.message);
    } else {
      fetchBrands();
      setMissingBrands([]);
    }
    setSyncing(false);
  };

  const handleUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingBrand) return;
    let logoUrl = editingBrand.logo_url?.trim() || '';
    if (logoUrl) {
      try {
        logoUrl = await normalizeAdminImageUrl(logoUrl, { kind: 'brand', brandId: editingBrand.id });
      } catch (err) {
        alert(err instanceof Error ? err.message : "Échec de l'import d'image");
        return;
      }
    }
    const { error } = await supabase
      .from('brands')
      .update({ name: editingBrand.name, logo_url: logoUrl })
      .eq('id', editingBrand.id);
    if (error) {
      alert('Erreur lors de la mise à jour');
    } else {
      setEditingBrand(null);
      fetchBrands();
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Êtes-vous sûr de vouloir supprimer cette marque ?')) return;
    const { error } = await supabase.from('brands').delete().eq('id', id);
    if (error) alert('Erreur lors de la suppression');
    else {
      fetchBrands();
      findMissingBrands();
    }
  };

  if (loading) return <div className="p-8 flex justify-center"><Loader2 className="animate-spin" /></div>;

  return (
    <div>
      <h1 className="text-xl md:text-2xl font-bold mb-4 md:mb-6 text-gray-800">Gestion des Marques</h1>

      {/* Marques manquantes */}
      {missingBrands.length > 0 && (
        <div className="bg-yellow-50 border border-yellow-200 rounded-xl p-4 md:p-6 mb-6">
          <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-3 mb-4">
            <div>
              <h3 className="text-sm font-bold text-yellow-800 uppercase flex items-center gap-2">
                <AlertTriangle size={16} />
                Marques non cadastrées ({missingBrands.length})
              </h3>
              <p className="text-xs text-yellow-700 mt-1">
                Ces marques existent dans vos produits mais ne sont pas encore cadastrées
              </p>
            </div>
            <button 
              onClick={handleAddAllMissingBrands}
              disabled={syncing}
              className="bg-yellow-600 text-white font-bold py-2 px-4 rounded hover:bg-yellow-700 transition-colors text-sm disabled:opacity-50 whitespace-nowrap"
            >
              {syncing ? 'Ajout...' : `Ajouter toutes (${missingBrands.length})`}
            </button>
          </div>
          <div className="flex flex-wrap gap-2">
            {missingBrands.map(brandName => (
              <div key={brandName} className="bg-white border border-yellow-300 rounded-lg px-3 py-2 flex items-center gap-2 text-sm">
                <span className="font-medium text-gray-800">{brandName}</span>
                <button 
                  onClick={() => handleAddMissingBrand(brandName)}
                  className="text-yellow-600 hover:text-yellow-800 font-bold"
                  title="Ajouter cette marque"
                >
                  +
                </button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Add Form */}
      <div className="bg-white p-4 md:p-6 rounded-xl shadow-sm border border-gray-100 mb-6 md:mb-8">
        <h3 className="text-sm font-bold text-gray-500 uppercase mb-4">Ajouter une nouvelle marque</h3>
        <form onSubmit={handleAdd} className="flex flex-col md:flex-row gap-3 md:gap-4 md:items-end">
          <div className="flex-1">
            <label className="block text-xs font-bold text-gray-500 mb-1">Nom</label>
            <input 
              value={newName} 
              onChange={e => setNewName(e.target.value)} 
              placeholder="Nom de la marque" 
              className="w-full border border-gray-300 rounded px-3 py-2 bg-gray-50 focus:bg-white transition-colors" 
              required 
            />
          </div>
          <div className="flex-1 md:flex-[2] space-y-2">
            <label className="block text-xs font-bold text-gray-500 mb-1">Logo (URL ou fichier)</label>
            <input 
              value={newLogo} 
              onChange={e => setNewLogo(e.target.value)} 
              placeholder="https://..." 
              className="w-full border border-gray-300 rounded px-3 py-2 bg-gray-50 focus:bg-white transition-colors" 
            />
            <input
              ref={newLogoFileRef}
              type="file"
              accept="image/jpeg,image/png,image/webp,image/gif,image/svg+xml"
              className="hidden"
              onChange={async (e) => {
                const f = e.target.files?.[0];
                e.target.value = '';
                if (!f) return;
                try {
                  const url = await uploadBrandLogo(f, 'pending');
                  setNewLogo(url);
                } catch (err: unknown) {
                  alert(err instanceof Error ? err.message : 'Erreur');
                }
              }}
            />
            <button
              type="button"
              disabled={logoUploadBusy}
              onClick={() => newLogoFileRef.current?.click()}
              className="inline-flex items-center gap-2 text-xs font-bold text-blue-600 hover:text-blue-800 disabled:opacity-50"
            >
              {logoUploadBusy ? <Loader2 className="animate-spin" size={14} /> : <Upload size={14} />}
              Téléverser une image
            </button>
          </div>
          <button type="submit" className="bg-blue-600 text-white font-bold py-2 px-6 rounded hover:bg-blue-700 transition-colors h-[42px] w-full md:w-auto">
            Ajouter
          </button>
        </form>
      </div>

      {/* Stats */}
      <div className="flex items-center justify-between mb-4">
        <p className="text-sm text-gray-500">{brands.length} marque(s) cadastrée(s)</p>
        <button 
          onClick={() => findMissingBrands()}
          className="text-blue-600 text-sm font-medium hover:underline"
        >
          Actualiser
        </button>
      </div>

      {/* Brands Grid */}
      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3 md:gap-6">
        {brands.map(brand => (
          <div key={brand.id} className="bg-white rounded-xl shadow-sm border border-gray-100 p-3 md:p-4 flex flex-col items-center group hover:shadow-md transition-shadow relative">
            <div className="h-12 md:h-16 w-full flex items-center justify-center mb-2 md:mb-4 bg-gray-50 rounded p-2">
              {brand.logo_url ? (
                <img src={brand.logo_url} alt={brand.name} className="max-h-full max-w-full object-contain mix-blend-multiply" />
              ) : (
                <span className="text-gray-400 text-xs">Pas de logo</span>
              )}
            </div>
            <h4 className="font-bold text-gray-800 mb-2 md:mb-3 text-center text-sm md:text-base">{brand.name}</h4>
            <div className="flex gap-2 w-full mt-auto">
