"use client";

import React, { useState, useEffect } from 'react';
import { Settings, Loader2, Trash2 } from 'lucide-react';
import { createClient } from '@/lib/supabase';

export default function TaxesSection() {
  const supabase = createClient();
  const [taxes, setTaxes] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [editingTax, setEditingTax] = useState<any>(null);
  const [isAdding, setIsAdding] = useState(false);

  const fetchTaxes = async () => {
    setLoading(true);
    setErrorMsg(null);
    const { data, error } = await supabase.from('taxes').select('*').order('sort_order', { ascending: true });
    if (error) {
      console.error('Erro ao buscar taxas:', error);
      setErrorMsg('Tabela "taxes" não encontrada neste projeto Supabase. Execute as migrations SQL.');
      setTaxes([]);
      setLoading(false);
      return;
    }
    setTaxes(data || []);
    setLoading(false);
  };

  useEffect(() => {
    fetchTaxes();
  }, []);

  const handleSave = async (e: React.FormEvent, taxData: any) => {
    e.preventDefault();
    const data = {
      ...taxData,
      rate: parseFloat(taxData.rate) || 0,
      is_percentage: taxData.is_percentage === 'true' || taxData.is_percentage === true,
      is_active: taxData.is_active === 'true' || taxData.is_active === true,
      sort_order: parseInt(taxData.sort_order) || 0
    };

    if (taxData.id) {
      const { error } = await supabase.from('taxes').update(data).eq('id', taxData.id);
      if (error) {
        alert(`Erro ao guardar taxa: ${error.message}`);
        return;
      }
    } else {
      const { error } = await supabase.from('taxes').insert([data]);
      if (error) {
        alert(`Erro ao criar taxa: ${error.message}`);
        return;
      }
    }
    setEditingTax(null);
    setIsAdding(false);
    fetchTaxes();
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Supprimer cette taxe ?')) return;
    const { error } = await supabase.from('taxes').delete().eq('id', id);
    if (error) {
      alert(`Erro ao apagar taxa: ${error.message}`);
      return;
    }
    fetchTaxes();
  };

  if (loading) return <div className="p-8 flex justify-center"><Loader2 className="animate-spin" /></div>;

  return (
    <div>
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 md:mb-8 gap-3">
        <h1 className="text-xl md:text-2xl font-bold text-gray-800">Gestion des Taxes</h1>
        <button
          onClick={() => {
            setIsAdding(true);
            setEditingTax({ name: '', description: '', rate: 0, is_percentage: true, applies_to: 'all', sort_order: (taxes.length + 1) * 10, is_active: true });
          }}
          className="bg-blue-600 text-white px-3 py-2 md:px-4 md:py-2 rounded-lg font-bold text-sm md:text-base w-full sm:w-auto"
        >
          + Nouvelle Taxe
        </button>
      </header>
      {errorMsg && (
        <div className="mb-4 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
          {errorMsg}
        </div>
      )}

      {/* Mobile Cards View */}
      <div className="md:hidden space-y-3">
        {taxes.map((tax) => (
          <div key={tax.id} className="bg-white rounded-xl shadow-sm border border-gray-100 p-4">
            <div className="flex justify-between items-start">
              <div className="flex-1 pr-2">
                <p className="font-bold text-gray-800 text-sm mb-1">{tax.name}</p>
                <p className="text-gray-500 text-xs mb-1">{tax.description || 'Sans description'}</p>
                <p className="text-blue-600 font-bold text-sm">
                  {tax.is_percentage ? `${tax.rate}%` : `€${tax.rate}`}
                </p>
              </div>
              <div className="flex gap-2">
                <button
                  onClick={() => setEditingTax(tax)}
                  className="text-blue-600 p-1.5"
                >
                  <Settings size={16} />
                </button>
                <button
                  onClick={() => handleDelete(tax.id)}
                  className="text-red-600 p-1.5"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            </div>
          </div>
        ))}
        {taxes.length === 0 && (
          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-8 text-center text-gray-400">
            Aucune taxe configurée
          </div>
        )}
      </div>

      {/* Desktop Table View */}
      <div className="hidden md:block bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
        <table className="w-full text-left text-sm">
          <thead className="bg-gray-50 border-b border-gray-100">
            <tr>
              <th className="px-6 py-4">Nom</th>
              <th className="px-6 py-4">Description</th>
              <th className="px-6 py-4">Taux</th>
              <th className="px-6 py-4">Type</th>
              <th className="px-6 py-4">S'applique à</th>
              <th className="px-6 py-4">Statut</th>
              <th className="px-6 py-4">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {taxes.map((tax) => (
              <tr key={tax.id} className="hover:bg-gray-50">
                <td className="px-6 py-4 font-medium text-gray-800">{tax.name}</td>
                <td className="px-6 py-4 text-gray-600 max-w-xs truncate">{tax.description || '-'}</td>
                <td className="px-6 py-4 font-bold text-blue-600">{tax.is_percentage ? `${tax.rate}%` : `€${tax.rate}`}</td>
                <td className="px-6 py-4 text-gray-500">{tax.is_percentage ? 'Pourcentage' : 'Fixe'}</td>
                <td className="px-6 py-4 text-gray-500 capitalize">{tax.applies_to || 'all'}</td>
                <td className="px-6 py-4">
                  <span className={`px-2 py-1 rounded-full text-xs font-bold ${
                    tax.is_active ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-700'
                  }`}>
                    {tax.is_active ? 'Actif' : 'Inactif'}
                  </span>
                </td>
                <td className="px-6 py-4">
                  <div className="flex gap-2">
                    <button
                      onClick={() => setEditingTax(tax)}
                      className="text-blue-600 hover:text-blue-800 p-1"
                      title="Modifier"
                    >
                      <Settings size={16} />
                    </button>
                    <button
                      onClick={() => handleDelete(tax.id)}
                      className="text-red-600 hover:text-red-800 p-1"
                      title="Supprimer"
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>
                </td>
              </tr>
            ))}
            {taxes.length === 0 && (
              <tr>
                <td colSpan={7} className="px-6 py-8 text-center text-gray-400">
                  Aucune taxe configurée
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {(editingTax || isAdding) && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-2 md:p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl max-h-[95vh] overflow-y-auto">
            <div className="p-4 md:p-6 border-b sticky top-0 bg-white z-10 flex justify-between items-center">
              <h3 className="font-bold text-lg">{editingTax?.id ? 'Modifier' : 'Ajouter'} une taxe</h3>
              <button
                onClick={() => {
                  setEditingTax(null);
                  setIsAdding(false);
                }}
                className="text-gray-400 hover:text-gray-600 text-2xl"
              >
                &times;
              </button>
            </div>
            <form
              onSubmit={(e) => {
                e.preventDefault();
                const formData = new FormData(e.target as HTMLFormElement);
                const data = Object.fromEntries(formData.entries());
                handleSave(e, { ...editingTax, ...data });
              }}
              className="p-4 md:p-6 space-y-4"
            >
              <div>
                <label className="block text-xs font-bold text-gray-500 mb-1">Nom de la taxe *</label>
                <input
                  name="name"
                  type="text"
                  defaultValue={editingTax?.name || ''}
                  className="w-full border border-gray-300 rounded px-3 py-2"
                  required
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 mb-1">Description</label>
                <textarea
                  name="description"
                  defaultValue={editingTax?.description || ''}
                  className="w-full border border-gray-300 rounded px-3 py-2 h-20"
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-gray-500 mb-1">Taux/Valeur *</label>
                  <input
                    name="rate"
                    type="number"
                    step="0.01"
                    defaultValue={editingTax?.rate || 0}
                    className="w-full border border-gray-300 rounded px-3 py-2"
                    required
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-500 mb-1">Type</label>
                  <select
                    name="is_percentage"
                    defaultValue={editingTax?.is_percentage ? 'true' : 'false'}
                    className="w-full border border-gray-300 rounded px-3 py-2"
                  >
                    <option value="true">Pourcentage (%)</option>
                    <option value="false">Montant fixe (€)</option>
                  </select>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-gray-500 mb-1">S'applique à</label>
                  <select
                    name="applies_to"
                    defaultValue={editingTax?.applies_to || 'all'}
                    className="w-full border border-gray-300 rounded px-3 py-2"
                  >
                    <option value="all">Toutes les catégories</option>
                    <option value="auto">Auto</option>
                    <option value="moto">Moto</option>
                    <option value="camion">Camion</option>
                    <option value="tracteur">Tracteur</option>
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-500 mb-1">Ordre</label>
                  <input
                    name="sort_order"
                    type="number"
                    defaultValue={editingTax?.sort_order || 0}
                    className="w-full border border-gray-300 rounded px-3 py-2"
                  />
                </div>
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 mb-1">Statut</label>
                <select
                  name="is_active"
                  defaultValue={editingTax?.is_active ? 'true' : 'false'}
                  className="w-full border border-gray-300 rounded px-3 py-2"
                >
                  <option value="true">Actif</option>
                  <option value="false">Inactif</option>
                </select>
              </div>
              <div className="flex flex-col sm:flex-row justify-end gap-2 pt-4">
                <button
                  type="button"
                  onClick={() => {
                    setEditingTax(null);
                    setIsAdding(false);
                  }}
                  className="px-4 py-2 border rounded font-medium order-2 sm:order-1"
                >
                  Annuler
                </button>
                <button
                  type="submit"
                  className="bg-blue-600 text-white px-4 py-2 rounded font-bold order-1 sm:order-2"
                >
                  Sauvegarder
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useEffect, useState } from 'react';
import { Package, MapPin, LogOut, Loader2, User, ExternalLink, Truck, ShieldCheck } from 'lucide-react';
import { createClient } from '@/lib/supabase';
import { useRouter } from 'next/navigation';
import SecuritySettings from '@/components/account/SecuritySettings';

export default function ClientDashboard() {
  const [activeTab, setActiveTab] = useState('orders');
  const [user, setUser] = useState<any>(null);
  const [profile, setProfile] = useState<any>(null);
  const [orders, setOrders] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const supabase = createClient();
  const router = useRouter();

  // Profile Form State
  const [formData, setFormData] = useState({
    full_name: '',
    phone: '',
    address: '',
    city: '',
    zip_code: '',
    country: 'France'
  });

  useEffect(() => {
    const fetchData = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      
      if (!user) {
        router.push('/auth/login');
        return;
      }
      setUser(user);

      // Fetch Profile
      const { data: profileData } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', user.id)
        .single();
      
      if (profileData) {
        setProfile(profileData);
        setFormData({
          full_name: profileData.full_name || '',
          phone: profileData.phone || '',
          address: profileData.address || '',
          city: profileData.city || '',
          zip_code: profileData.zip_code || '',
          country: profileData.country || 'France'
        });
      }

      // Fetch Orders
      const { data: ordersData, error } = await supabase
        .from('orders')
        .select(`
          *,
          order_items (
            quantity,
            price,
            products (
              name,
              images
            )
          ),
          order_shipments (
            id,
            carrier_service,
            parcel_number,
            tracking_url,
            status_message,
            estimated_delivery_date,
            date_shipped
          ),
          supplier_orders (
            customer_order_id,
            supplier_order_ids,
            status,
            error_message
          )
        `)
        .eq('user_id', user.id)
        .order('created_at', { ascending: false });

      if (ordersData) {
        setOrders(ordersData);
      }
      
      setLoading(false);
    };

    fetchData();
  }, []);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    router.push('/auth/login');
  };

  const handleSaveProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    
    const { error } = await supabase
      .from('profiles')
      .update(formData)
      .eq('id', user.id);

    if (error) {
      alert('Erreur lors de la mise à jour du profil');
      console.error(error);
    } else {
      alert('Profil mis à jour avec succès');
      setProfile({ ...profile, ...formData });
    }
    setSaving(false);
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-[#F1F1F1] flex items-center justify-center">
        <Loader2 className="animate-spin text-blue-600" size={48} />
      </div>
    );
  }

  return (
    <div className="container mx-auto px-4 py-8 min-h-screen bg-[#F1F1F1]">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
        
        {/* Sidebar Navigation */}
        <aside className="md:col-span-1">
          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 sticky top-24">
            <div className="flex items-center gap-4 mb-6">
              <div className="w-12 h-12 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center font-bold text-lg uppercase">
                {profile?.full_name ? profile.full_name.charAt(0) : user?.email?.charAt(0)}
              </div>
              <div className="overflow-hidden">
                <p className="font-bold text-gray-800 truncate">{profile?.full_name || 'Client'}</p>
                <p className="text-xs text-gray-500 truncate">{user?.email}</p>
              </div>
            </div>
            <nav className="space-y-1">
              <button 
                onClick={() => setActiveTab('orders')}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-medium transition-colors ${activeTab === 'orders' ? 'bg-blue-50 text-blue-600' : 'text-gray-600 hover:bg-gray-50'}`}
              >
                <Package size={18} /> Mes Commandes
              </button>
              <button 
                onClick={() => setActiveTab('profile')}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-medium transition-colors ${activeTab === 'profile' ? 'bg-blue-50 text-blue-600' : 'text-gray-600 hover:bg-gray-50'}`}
              >
                <User size={18} /> Mon Profil & Adresses
              </button>
              <button
                onClick={() => setActiveTab('security')}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-medium transition-colors ${activeTab === 'security' ? 'bg-blue-50 text-blue-600' : 'text-gray-600 hover:bg-gray-50'}`}
              >
                <ShieldCheck size={18} /> Sécurité
              </button>
              <div className="border-t border-gray-100 my-2"></div>
              <button 
                onClick={handleLogout}
                className="w-full flex items-center gap-3 px-4 py-3 text-red-600 hover:bg-red-50 rounded-lg transition-colors text-left"
              >
                <LogOut size={18} /> Déconnexion
              </button>
            </nav>
          </div>
        </aside>

        {/* Main Content */}
        <main className="md:col-span-3 space-y-6">
          
          {activeTab === 'orders' && (
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6">
              <h1 className="text-2xl font-bold text-gray-800 mb-6">Historique des commandes</h1>
              
              {orders.length > 0 ? (
                <div className="space-y-6">
                  {orders.map((order) => (
                    <div key={order.id} className="border border-gray-200 rounded-lg overflow-hidden">
                      <div className="bg-gray-50 px-6 py-4 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                        <div className="flex gap-8 text-sm">
                          <div>
                            <span className="block text-gray-500 text-xs uppercase">Date de commande</span>
                            <span className="font-medium text-gray-800">{new Date(order.created_at).toLocaleDateString()}</span>
                          </div>
                          <div>
                            <span className="block text-gray-500 text-xs uppercase">Total</span>
                            <span className="font-medium text-gray-800">€{order.total_amount?.toFixed(2)}</span>
                          </div>
                          <div>
                            <span className="block text-gray-500 text-xs uppercase">N° de commande</span>
                            <span className="font-medium text-gray-800 text-xs">{order.id}</span>
                          </div>
                        </div>
                        <div className="flex items-center gap-4">
                          <span className={`px-3 py-1 rounded-full text-xs font-bold ${
                            order.status === 'delivered' ? 'bg-green-100 text-green-700' : 
                            order.status === 'shipped' ? 'bg-blue-100 text-blue-700' :
                            'bg-yellow-100 text-yellow-700'
                          }`}>
                            {order.status === 'pending' ? 'En traitement' : order.status}
                          </span>
                        </div>
                      </div>
                      <div className="p-6">
                        {order.order_items && order.order_items.length > 0 ? (
                          order.order_items.map((item: any, idx: number) => (
                            <div key={idx} className="flex items-center gap-4 mb-4 last:mb-0">
                              <div className="w-16 h-16 bg-gray-100 rounded flex items-center justify-center overflow-hidden">
                                {item.products?.images?.[0] ? (
                                  <img src={item.products.images[0]} alt={item.products.name} className="w-full h-full object-cover" />
                                ) : (
                                  <Package className="text-gray-400" />
                                )}
                              </div>
                              <div>
                                <p className="font-bold text-gray-800">{item.products?.name || 'Produit inconnu'}</p>
                                <p className="text-sm text-gray-500">Quantité: {item.quantity} x €{item.price}</p>
                              </div>
                            </div>
                          ))
                        ) : (
                          <p className="text-sm text-gray-500 italic">Détails des articles non disponibles.</p>
                        )}

                        {order.order_shipments?.length > 0 && (
                          <div className="mt-6 border-t border-gray-100 pt-4">
                            <h4 className="font-bold text-gray-800 mb-3 flex items-center gap-2">
                              <Truck size={16} /> Suivi de livraison
                            </h4>
                            <div className="space-y-3">
                              {order.order_shipments.map((shipment: any) => (
                                <div key={shipment.id} className="rounded-lg border border-gray-200 p-3 text-sm text-gray-600">
                                  <div className="flex flex-wrap gap-x-4 gap-y-1">
                                    {shipment.carrier_service && (
                                      <span><span className="text-gray-500">Transporteur:</span> {shipment.carrier_service}</span>
                                    )}
                                    {shipment.parcel_number && (
                                      <span><span className="text-gray-500">Colis:</span> {shipment.parcel_number}</span>
                                    )}
                                    {shipment.status_message && (
                                      <span><span className="text-gray-500">Statut:</span> {shipment.status_message}</span>
                                    )}
                                  </div>
                                  {shipment.tracking_url && (
                                    <a
                                      href={shipment.tracking_url}
                                      target="_blank"
                                      rel="noopener noreferrer"
                                      className="inline-flex items-center gap-1 text-blue-600 hover:underline mt-2"
                                    >
                                      Suivre le colis <ExternalLink size={14} />
                                    </a>
                                  )}
                                </div>
                              ))}
                            </div>
                          </div>
                        )}

                        {order.estimated_delivery_date && (
                          <p className="text-sm text-gray-500 mt-4">
                            Livraison estimée : {new Date(order.estimated_delivery_date).toLocaleDateString()}
                          </p>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
