                      </div>
                      <div>
                        <label className="block text-sm font-bold text-gray-700 mb-2">Code Postal</label>
                        <input 
                          type="text" 
                          value={formData.zip_code} 
                          onChange={(e) => setFormData({...formData, zip_code: e.target.value})}
