                </div>

                <div className="pt-4">
                  <button 
                    type="submit" 
                    disabled={saving}
                    className="bg-blue-600 text-white font-bold py-3 px-8 rounded-lg hover:bg-blue-700 transition-colors flex items-center gap-2 disabled:opacity-70"
                  >
                    {saving && <Loader2 className="animate-spin" size={18} />}
                    Enregistrer les modifications
                  </button>
                </div>
              </form>
            </div>
          )}
        </main>
      </div>
    </div>
  );
}

"use client";

import React, { useEffect, useState } from 'react';
import { Building2, ShoppingCart, Percent, Loader2 } from 'lucide-react';
import { createClient } from '@/lib/supabase';
import { useRouter } from 'next/navigation';
import DashboardShell from '@/components/dashboard/DashboardShell';

export default function EnterpriseDashboard() {
  const [activeTab, setActiveTab] = useState('orders');
  const [user, setUser] = useState<any>(null);
  const [profile, setProfile] = useState<any>(null);
  const [company, setCompany] = useState<any>(null);
  const [orders, setOrders] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const supabase = createClient();
  const router = useRouter();

  // Profile Form State
  const [formData, setFormData] = useState({
    full_name: '',
    phone: '',
    address: '',
    city: '',
    zip_code: '',
    country: 'France',
    // Company specifics
    company_name: '',
    vat_number: ''
  });

  useEffect(() => {
    const fetchData = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      
      if (!user) {
        router.push('/auth/login');
        return;
      }
      setUser(user);

      // Fetch Profile
      const { data: profileData } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', user.id)
        .single();
      
      setProfile(profileData);

      // Fetch Company Details
      const { data: companyData } = await supabase
        .from('companies')
        .select('*')
        .eq('profile_id', user.id)
        .single();
      
      setCompany(companyData);

      if (profileData) {
        setFormData(prev => ({
          ...prev,
          full_name: profileData.full_name || '',
          phone: profileData.phone || '',
          address: profileData.address || '',
          city: profileData.city || '',
          zip_code: profileData.zip_code || '',
          country: profileData.country || 'France',
          company_name: companyData?.company_name || '',
          vat_number: companyData?.vat_number || ''
        }));
      }

      // Fetch Orders
      const { data: ordersData } = await supabase
        .from('orders')
        .select(`
          *,
          order_items (
            quantity,
            price,
            products (
              name,
              images
            )
          )
        `)
        .eq('user_id', user.id)
        .order('created_at', { ascending: false });

      if (ordersData) {
        setOrders(ordersData);
      }
      
      setLoading(false);
    };

    fetchData();
  }, []);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    router.push('/auth/login');
  };

  const handleSaveProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    
    // Update Profile
    const { error: profileError } = await supabase
      .from('profiles')
      .update({
        full_name: formData.full_name,
        phone: formData.phone,
        address: formData.address,
        city: formData.city,
        zip_code: formData.zip_code,
        country: formData.country
      })
      .eq('id', user.id);

    // Update Company
    let companyError = null;
    if (company) {
      const { error } = await supabase
        .from('companies')
        .update({
          company_name: formData.company_name,
          vat_number: formData.vat_number
        })
        .eq('id', company.id);
      companyError = error;
    } else {
        // Create company record if missing (unlikely for pro role, but safe fallback)
        const { error } = await supabase
        .from('companies')
        .insert({
          profile_id: user.id,
          company_name: formData.company_name,
          vat_number: formData.vat_number,
          discount_tier: 5.0 // Default
        });
        companyError = error;
    }

    if (profileError || companyError) {
      alert('Erreur lors de la mise à jour: ' + (profileError?.message || companyError?.message));
    } else {
      alert('Profil entreprise mis à jour avec succès');
      // Refresh local state if needed
    }
    setSaving(false);
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-[#F1F1F1] flex items-center justify-center">
        <Loader2 className="animate-spin text-blue-600" size={48} />
      </div>
    );
  }

  return (
    <DashboardShell
      title="Espace Pro"
      subtitle={company?.company_name || 'Entreprise'}
      items={[
        { key: 'orders', label: 'Commandes', icon: ShoppingCart },
        { key: 'discounts', label: 'Mes Remises', icon: Percent },
        { key: 'profile', label: 'Profil Entreprise', icon: Building2 },
      ]}
      activeKey={activeTab}
      onSelect={setActiveTab}
      onSignOut={handleLogout}
    >
        
        {activeTab === 'orders' && (
