"use client";

import React, { Fragment, useEffect, useState } from 'react';
import { 
  Package, TrendingUp, DollarSign, LogOut, User, Loader2, Save, Edit, Trash2, Upload,
  ChevronDown, ChevronRight, KeyRound
} from 'lucide-react';
import { createClient } from '@/lib/supabase';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import OrderPurchaseDetails from '@/components/OrderPurchaseDetails';
import SupplierApiKeysSection from './SupplierApiKeysSection';

export default function SupplierDashboard() {
  const [activeTab, setActiveTab] = useState('overview');
  const [user, setUser] = useState<any>(null);
  const [supplier, setSupplier] = useState<any>(null);
  const [profile, setProfile] = useState<any>(null);
  const [products, setProducts] = useState<any[]>([]);
  const [stats, setStats] = useState({
    totalRevenue: 0,
    activeProducts: 0,
    lowStock: 0,
    totalSales: 0
  });
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [editingProduct, setEditingProduct] = useState<any>(null);
  const [supplierOrders, setSupplierOrders] = useState<any[]>([]);
  const [ordersLoading, setOrdersLoading] = useState(false);
  const [expandedOrderId, setExpandedOrderId] = useState<string | null>(null);
  const supabase = createClient();
  const router = useRouter();

  // Profile Form State
  const [formData, setFormData] = useState({
    full_name: '',
    phone: '',
    address: '',
    city: '',
    zip_code: '',
    country: 'France'
  });

  useEffect(() => {
    const fetchData = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      
      if (!user) {
        router.push('/auth/login');
        return;
      }
      setUser(user);

      // Fetch Profile
      const { data: profileData } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', user.id)
        .single();
      
      if (profileData) {
        setProfile(profileData);
        setFormData({
          full_name: profileData.full_name || '',
          phone: profileData.phone || '',
          address: profileData.address || '',
          city: profileData.city || '',
          zip_code: profileData.zip_code || '',
          country: profileData.country || 'France'
        });
      }

      // Fetch Supplier
      const { data: supplierData } = await supabase
        .from('suppliers')
        .select('*')
        .eq('profile_id', user.id)
        .single();
      
      setSupplier(supplierData);

      // Fetch Products
      const { data: productsData } = await supabase
        .from('products')
        .select('*, brands(id, name, logo_url)')
        .eq('supplier_user_id', user.id)
        .order('created_at', { ascending: false });
      
      setProducts(productsData || []);

      // Fetch Sales/Revenue (through order_items)
      const { data: salesData } = await supabase
        .from('order_items')
        .select('*, orders(total_amount, created_at, status, payment_status)')
        .in('product_id', productsData?.map((p: any) => p.id) || []);
      
      // Calculate Stats
      const activeProducts = (productsData || []).filter((p: any) => p.is_active).length;
      const lowStock = (productsData || []).filter((p: any) => (p.stock_quantity || 0) < 10 && (p.stock_quantity || 0) > 0).length;
      const totalRevenue = (salesData || []).reduce((sum: number, item: any) => {
        const ord = item.orders;
        const paid =
          ord?.payment_status === 'paid' ||
          ord?.status === 'completed' ||
          ord?.status === 'delivered';
        if (paid) {
          return sum + (Number(item.price) * Number(item.quantity) || 0);
        }
        return sum;
      }, 0);
      const paidLineIds = new Set(
        (salesData || [])
          .filter((item: any) => {
            const ord = item.orders;
            return (
              ord?.payment_status === 'paid' ||
              ord?.status === 'completed' ||
              ord?.status === 'delivered'
            );
          })
          .map((item: any) => item.order_id)
      );
      const totalSales = paidLineIds.size;

      setStats({
        totalRevenue,
        activeProducts,
        lowStock,
        totalSales
      });
      
      setLoading(false);
    };

    fetchData();
  }, []);

  useEffect(() => {
    if (activeTab !== 'sales' || !user) return;
    let cancelled = false;
    (async () => {
      setOrdersLoading(true);
      const { data, error } = await supabase
        .from('orders')
        .select(`
          *,
          order_items (
            *,
            products ( id, name, base_price, category ),
            garages ( id, name, address, city, zip_code )
          )
        `)
        .order('created_at', { ascending: false });
      if (cancelled) return;
      if (error) {
        console.error('Supplier orders:', error);
        setSupplierOrders([]);
      } else {
        setSupplierOrders(data || []);
      }
      setOrdersLoading(false);
    })();
    return () => {
      cancelled = true;
    };
  }, [activeTab, user]);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    router.push('/auth/login');
  };

  const handleSaveProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    
    const { error } = await supabase
      .from('profiles')
      .update(formData)
      .eq('id', user.id);

    if (error) {
      alert('Erreur: ' + error.message);
    } else {
      alert('Profil mis à jour !');
      setProfile({ ...profile, ...formData });
    }
    setSaving(false);
  };

  const handleSaveProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingProduct) return;
    setSaving(true);
    
    const updates = {
      ...editingProduct,
      base_price: parseFloat(editingProduct.base_price) || 0,
      stock_quantity: parseInt(editingProduct.stock_quantity) || 0,
    };
    
    const { error } = await supabase
      .from('products')
      .update(updates)
      .eq('id', editingProduct.id);

    if (error) {
      alert('Erreur: ' + error.message);
    } else {
      setProducts(products.map(p => p.id === editingProduct.id ? updates : p));
      setEditingProduct(null);
      alert('Produit mis à jour !');
    }
    setSaving(false);
  };

  const handleDeleteProduct = async (id: string) => {
    if (!confirm('Êtes-vous sûr de vouloir supprimer ce produit ?')) return;
    const { error } = await supabase.from('products').delete().eq('id', id);
    if (error) {
      alert('Erreur: ' + error.message);
    } else {
      setProducts(products.filter(p => p.id !== id));
    }
  };

  if (loading) {
    return (
      <div className="flex h-screen items-center justify-center">
        <Loader2 className="animate-spin text-gray-400" size={48} />
      </div>
    );
  }

  const menuItems = [
    { id: 'overview', label: 'Tableau de bord', icon: TrendingUp },
    { id: 'products', label: 'Mes Produits', icon: Package },
    { id: 'sales', label: 'Ventes & Revenus', icon: DollarSign },
    { id: 'api', label: 'API Produtos', icon: KeyRound },
    { id: 'profile', label: 'Mon Profil', icon: User },
  ];

  return (
    <div className="flex h-screen bg-[#F1F1F1]">
      {/* Mobile Header */}
      <div className="md:hidden fixed top-0 left-0 right-0 bg-white shadow-sm z-50 h-16 flex items-center justify-between px-4">
        <span className="text-lg font-bold text-gray-800">Fournisseur</span>
        <button
          onClick={() => setActiveTab(activeTab === 'menu' ? 'overview' : 'menu')}
          className="text-gray-600"
        >
          {activeTab === 'menu' ? '✕' : '☰'}
        </button>
      </div>

      {/* Sidebar */}
      <aside className={`${activeTab === 'menu' ? 'translate-x-0' : '-translate-x-full md:translate-x-0'} fixed md:static inset-y-0 left-0 w-64 bg-white shadow-lg z-40 flex flex-col transition-transform duration-300`}>
        <div className="p-6 border-b">
          <span className="text-xl font-bold text-gray-800">Fournisseur</span>
          <span className="text-xs block text-gray-400 mt-1">Espace Partenaire</span>
        </div>
        <nav className="flex-1 overflow-y-auto p-4 space-y-1">
          {menuItems.map(item => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-medium transition-colors ${
                activeTab === item.id ? 'bg-blue-50 text-[#0066CC]' : 'text-gray-600 hover:bg-gray-50'
              }`}
            >
              <item.icon size={20} /> {item.label}
            </button>
          ))}
        </nav>
        <div className="p-4 border-t space-y-1">
          <button onClick={handleLogout} className="w-full flex items-center gap-3 px-4 py-3 rounded-lg text-red-600 hover:bg-red-50 transition-colors">
            <LogOut size={20} /> Déconnexion
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto p-4 md:p-8 pt-20 md:pt-8">
        {activeTab === 'overview' && (
          <div>
            <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 md:mb-8 gap-3">
              <h1 className="text-xl md:text-2xl font-bold text-gray-800">Vue d'ensemble</h1>
              <Link 
                href="/dashboard/products"
                className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-bold w-full sm:w-auto justify-center"
              >
                <Upload size={16} /> Importer CSV
              </Link>
            </header>

            {/* Stats Cards */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3 md:gap-6 mb-6 md:mb-8">
              <div className="bg-white p-4 md:p-6 rounded-xl shadow-sm border border-gray-100">
                <h3 className="text-gray-500 text-xs md:text-sm font-medium mb-2">Revenus Total</h3>
                <p className="text-lg md:text-3xl font-bold text-gray-800">€{stats.totalRevenue.toFixed(2)}</p>
              </div>
              <div className="bg-white p-4 md:p-6 rounded-xl shadow-sm border border-gray-100">
                <h3 className="text-gray-500 text-xs md:text-sm font-medium mb-2">Produits Actifs</h3>
                <p className="text-lg md:text-3xl font-bold text-gray-800">{stats.activeProducts}</p>
              </div>
              <div className="bg-white p-4 md:p-6 rounded-xl shadow-sm border border-gray-100">
                <h3 className="text-gray-500 text-xs md:text-sm font-medium mb-2">Stock Faible</h3>
                <p className="text-lg md:text-3xl font-bold text-orange-500">{stats.lowStock}</p>
                <span className="text-xs text-gray-400">Articles à réapprovisionner</span>
              </div>
              <div className="bg-white p-4 md:p-6 rounded-xl shadow-sm border border-gray-100">
                <h3 className="text-gray-500 text-xs md:text-sm font-medium mb-2">Ventes</h3>
                <p className="text-lg md:text-3xl font-bold text-gray-800">{stats.totalSales}</p>
                <span className="text-xs text-gray-400">Commandes</span>
              </div>
            </div>

            {/* Recent Products */}
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
              <div className="p-4 md:p-6 border-b border-gray-100 flex justify-between items-center">
                <h2 className="font-bold text-lg text-gray-800">Produits Récents</h2>
                <button 
                  onClick={() => setActiveTab('products')}
                  className="text-blue-600 text-sm font-medium hover:underline"
                >
                  Voir tout
                </button>
              </div>
              <div className="overflow-x-auto">
                <table className="w-full text-left text-sm text-gray-600">
                  <thead className="bg-gray-50 text-gray-500 font-medium uppercase text-xs">
                    <tr>
                      <th className="px-4 md:px-6 py-3">Produit</th>
                      <th className="px-4 md:px-6 py-3 hidden md:table-cell">Catégorie</th>
                      <th className="px-4 md:px-6 py-3">Prix</th>
                      <th className="px-4 md:px-6 py-3">Stock</th>
                      <th className="px-4 md:px-6 py-3">Statut</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100">
                    {products.slice(0, 5).map((product) => (
                      <tr key={product.id} className="hover:bg-gray-50">
                        <td className="px-4 md:px-6 py-4 font-medium text-gray-800">{product.name}</td>
                        <td className="px-4 md:px-6 py-4 hidden md:table-cell">{product.category || '-'}</td>
                        <td className="px-4 md:px-6 py-4">€{product.base_price?.toFixed(2) || '0.00'}</td>
                        <td className="px-4 md:px-6 py-4">{product.stock_quantity || 0}</td>
                        <td className="px-4 md:px-6 py-4">
                          <span className={`px-2 py-1 rounded-full text-xs font-bold ${
                            (product.stock_quantity || 0) > 10 ? 'bg-green-100 text-green-700' :
                            (product.stock_quantity || 0) > 0 ? 'bg-orange-100 text-orange-700' :
                            'bg-red-100 text-red-700'
                          }`}>
                            {(product.stock_quantity || 0) > 10 ? 'En stock' :
                             (product.stock_quantity || 0) > 0 ? 'Faible' : 'Rupture'}
                          </span>
                        </td>
                      </tr>
                    ))}
                    {products.length === 0 && (
                      <tr>
                        <td colSpan={5} className="px-6 py-8 text-center text-gray-400">
                          Aucun produit trouvé. <Link href="/dashboard/products" className="text-blue-600 hover:underline">Importer des produits</Link>
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'products' && (
          <div>
            <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 md:mb-8 gap-3">
              <h1 className="text-xl md:text-2xl font-bold text-gray-800">Mes Produits</h1>
              <Link 
                href="/dashboard/products"
                className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-bold w-full sm:w-auto justify-center"
              >
                <Upload size={16} /> Importer CSV
              </Link>
            </header>

            {/* Products List */}
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
              {/* Mobile Cards */}
              <div className="md:hidden divide-y divide-gray-100">
                {products.map((product) => (
                  <div key={product.id} className="p-4">
                    <div className="flex justify-between items-start mb-2">
                      <div className="flex-1">
                        <h3 className="font-bold text-gray-800">{product.name}</h3>
                        <p className="text-sm text-gray-500">{product.category || '-'}</p>
                      </div>
                      <div className="flex gap-2">
                        <button
                          onClick={() => setEditingProduct(product)}
                          className="text-blue-600 p-2 hover:bg-blue-50 rounded"
                        >
                          <Edit size={16} />
                        </button>
                        <button
                          onClick={() => handleDeleteProduct(product.id)}
                          className="text-red-600 p-2 hover:bg-red-50 rounded"
                        >
                          <Trash2 size={16} />
                        </button>
                      </div>
                    </div>
                    <div className="grid grid-cols-2 gap-2 text-sm">
                      <div>
                        <span className="text-gray-500">Prix:</span>
                        <span className="font-bold ml-2">€{product.base_price?.toFixed(2) || '0.00'}</span>
                      </div>
                      <div>
                        <span className="text-gray-500">Stock:</span>
                        <span className={`font-bold ml-2 ${
                          (product.stock_quantity || 0) > 10 ? 'text-green-600' :
                          (product.stock_quantity || 0) > 0 ? 'text-orange-600' : 'text-red-600'
                        }`}>
                          {product.stock_quantity || 0}
                        </span>
                      </div>
                    </div>
                  </div>
                ))}
                {products.length === 0 && (
                  <div className="p-8 text-center text-gray-400">
                    Aucun produit. <Link href="/dashboard/products" className="text-blue-600 hover:underline">Importer des produits</Link>
                  </div>
                )}
              </div>

              {/* Desktop Table */}
              <div className="hidden md:block overflow-x-auto">
                <table className="w-full text-left text-sm text-gray-600">
                  <thead className="bg-gray-50 text-gray-500 font-medium uppercase text-xs">
                    <tr>
                      <th className="px-6 py-3">Produit</th>
                      <th className="px-6 py-3">Catégorie</th>
                      <th className="px-6 py-3">Prix</th>
                      <th className="px-6 py-3">Stock</th>
                      <th className="px-6 py-3">Statut</th>
                      <th className="px-6 py-3">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100">
                    {products.map((product) => (
                      <tr key={product.id} className="hover:bg-gray-50">
                        <td className="px-6 py-4 font-medium text-gray-800">{product.name}</td>
                        <td className="px-6 py-4">{product.category || '-'}</td>
                        <td className="px-6 py-4">€{product.base_price?.toFixed(2) || '0.00'}</td>
                        <td className="px-6 py-4">{product.stock_quantity || 0}</td>
                        <td className="px-6 py-4">
                          <span className={`px-2 py-1 rounded-full text-xs font-bold ${
                            (product.stock_quantity || 0) > 10 ? 'bg-green-100 text-green-700' :
                            (product.stock_quantity || 0) > 0 ? 'bg-orange-100 text-orange-700' :
                            'bg-red-100 text-red-700'
                          }`}>
                            {(product.stock_quantity || 0) > 10 ? 'En stock' :
                             (product.stock_quantity || 0) > 0 ? 'Faible' : 'Rupture'}
                          </span>
                        </td>
                        <td className="px-6 py-4">
                          <div className="flex gap-2">
                            <button
                              onClick={() => setEditingProduct(product)}
                              className="text-blue-600 hover:text-blue-800 p-1"
                              title="Modifier"
                            >
                              <Edit size={16} />
                            </button>
                            <button
                              onClick={() => handleDeleteProduct(product.id)}
                              className="text-red-600 hover:text-red-800 p-1"
                              title="Supprimer"
                            >
                              <Trash2 size={16} />
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                    {products.length === 0 && (
                      <tr>
                        <td colSpan={6} className="px-6 py-8 text-center text-gray-400">
                          Aucun produit trouvé. <Link href="/dashboard/products" className="text-blue-600 hover:underline">Importer des produits</Link>
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'sales' && (
          <div>
            <h1 className="text-xl md:text-2xl font-bold text-gray-800 mb-6 md:mb-8">Ventes & Revenus</h1>
            
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6 mb-6 md:mb-8">
              <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                <h3 className="text-gray-500 text-sm font-medium mb-2">Revenus (vos pneus, payées)</h3>
                <p className="text-3xl font-bold text-gray-800">€{stats.totalRevenue.toFixed(2)}</p>
                <span className="text-green-500 text-xs font-bold">Lignes de commande payées</span>
              </div>
              <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                <h3 className="text-gray-500 text-sm font-medium mb-2">Commandes concernées</h3>
                <p className="text-3xl font-bold text-gray-800">{stats.totalSales}</p>
                <span className="text-gray-400 text-xs">Commandes distinctes avec au moins une ligne payée</span>
              </div>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
              <div className="p-4 md:p-6 border-b border-gray-100">
                <h2 className="font-bold text-lg text-gray-800">Commandes (détail)</h2>
                <p className="text-sm text-gray-500 mt-1">
                  Vous voyez les commandes contenant au moins un de vos produits. Les lignes d’autres vendeurs sur la même commande n’apparaissent pas.
                </p>
              </div>
              {ordersLoading ? (
                <div className="p-12 flex justify-center">
                  <Loader2 className="animate-spin text-gray-400" size={36} />
                </div>
              ) : supplierOrders.length === 0 ? (
                <p className="p-8 text-center text-gray-500">Aucune commande pour le moment.</p>
              ) : (
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead className="bg-gray-50 text-gray-600 text-xs uppercase">
                      <tr>
                        <th className="px-4 py-3 text-left">Commande</th>
                        <th className="px-4 py-3 text-left">Date</th>
                        <th className="px-4 py-3 text-left">Total</th>
                        <th className="px-4 py-3 text-left">Paiement</th>
                        <th className="px-4 py-3 text-left">Lignes</th>
                        <th className="w-12 px-4 py-3"></th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                      {supplierOrders.map((ord) => (
                        <Fragment key={ord.id}>
                          <tr className="hover:bg-gray-50">
                            <td className="px-4 py-3 font-mono text-xs">#{ord.id.slice(0, 8)}</td>
                            <td className="px-4 py-3 text-gray-600">
                              {new Date(ord.created_at).toLocaleString('fr-FR')}
                            </td>
                            <td className="px-4 py-3 font-bold">€{Number(ord.total_amount).toFixed(2)}</td>
                            <td className="px-4 py-3">{ord.payment_status || ord.status}</td>
                            <td className="px-4 py-3">{ord.order_items?.length ?? 0}</td>
                            <td className="px-4 py-3">
                              <button
                                type="button"
                                onClick={() =>
                                  setExpandedOrderId(expandedOrderId === ord.id ? null : ord.id)
                                }
                                className="p-2 rounded-lg text-gray-500 hover:bg-gray-100"
                                aria-expanded={expandedOrderId === ord.id}
                              >
                                {expandedOrderId === ord.id ? (
                                  <ChevronDown size={18} />
                                ) : (
                                  <ChevronRight size={18} />
                                )}
                              </button>
                            </td>
                          </tr>
                          {expandedOrderId === ord.id && (
                            <tr>
                              <td colSpan={6} className="p-0">
                                <OrderPurchaseDetails order={ord} supplierView />
                              </td>
                            </tr>
                          )}
                        </Fragment>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          </div>
        )}

        {activeTab === 'api' && <SupplierApiKeysSection />}

        {activeTab === 'profile' && (
          <div>
            <h1 className="text-xl md:text-2xl font-bold text-gray-800 mb-6 md:mb-8">Mon Profil</h1>
            
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 md:p-6">
              <form onSubmit={handleSaveProfile} className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs font-bold text-gray-500 mb-1">Nom complet</label>
                    <input
                      type="text"
                      value={formData.full_name}
                      onChange={(e) => setFormData({...formData, full_name: e.target.value})}
                      className="w-full border border-gray-300 rounded px-3 py-2"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-gray-500 mb-1">Téléphone</label>
                    <input
                      type="tel"
                      value={formData.phone}
                      onChange={(e) => setFormData({...formData, phone: e.target.value})}
                      className="w-full border border-gray-300 rounded px-3 py-2"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-gray-500 mb-1">Email</label>
                    <input
                      type="email"
                      value={user?.email || ''}
                      disabled
                      className="w-full border border-gray-300 rounded px-3 py-2 bg-gray-50"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-gray-500 mb-1">Adresse</label>
                    <input
                      type="text"
                      value={formData.address}
                      onChange={(e) => setFormData({...formData, address: e.target.value})}
                      className="w-full border border-gray-300 rounded px-3 py-2"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-gray-500 mb-1">Ville</label>
                    <input
                      type="text"
                      value={formData.city}
                      onChange={(e) => setFormData({...formData, city: e.target.value})}
                      className="w-full border border-gray-300 rounded px-3 py-2"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-gray-500 mb-1">Code postal</label>
                    <input
                      type="text"
                      value={formData.zip_code}
                      onChange={(e) => setFormData({...formData, zip_code: e.target.value})}
                      className="w-full border border-gray-300 rounded px-3 py-2"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-gray-500 mb-1">Pays</label>
                    <input
                      type="text"
                      value={formData.country}
                      onChange={(e) => setFormData({...formData, country: e.target.value})}
                      className="w-full border border-gray-300 rounded px-3 py-2"
                    />
                  </div>
                </div>
                <div className="pt-4">
                  <button
                    type="submit"
                    disabled={saving}
                    className="bg-blue-600 text-white px-6 py-2 rounded-lg font-bold hover:bg-blue-700 disabled:opacity-50 flex items-center gap-2"
                  >
                    {saving ? <Loader2 className="animate-spin" size={16} /> : <Save size={16} />}
                    Sauvegarder
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}
      </main>

      {/* Edit Product Modal */}
      {editingProduct && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4 backdrop-blur-sm">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto">
            <div className="p-4 md:p-6 border-b flex justify-between items-center bg-gray-50">
              <h3 className="font-bold text-lg text-gray-800">Modifier le produit</h3>
              <button 
                onClick={() => setEditingProduct(null)} 
                className="text-gray-400 hover:text-gray-600 transition-colors text-2xl"
              >
                &times;
              </button>
            </div>
            <form onSubmit={handleSaveProduct} className="p-4 md:p-6 space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-gray-500 mb-1">Nom</label>
                  <input
                    type="text"
                    value={editingProduct.name || ''}
                    onChange={(e) => setEditingProduct({...editingProduct, name: e.target.value})}
                    className="w-full border border-gray-300 rounded px-3 py-2"
                    required
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-500 mb-1">Prix</label>
                  <input
                    type="number"
                    step="0.01"
                    value={editingProduct.base_price || ''}
                    onChange={(e) => setEditingProduct({...editingProduct, base_price: e.target.value})}
                    className="w-full border border-gray-300 rounded px-3 py-2"
                    required
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-500 mb-1">Stock</label>
                  <input
                    type="number"
                    value={editingProduct.stock_quantity || ''}
                    onChange={(e) => setEditingProduct({...editingProduct, stock_quantity: e.target.value})}
                    className="w-full border border-gray-300 rounded px-3 py-2"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-500 mb-1">Catégorie</label>
                  <select
                    value={editingProduct.category || ''}
                    onChange={(e) => setEditingProduct({...editingProduct, category: e.target.value})}
                    className="w-full border border-gray-300 rounded px-3 py-2"
                  >
                    <option value="">Sélectionner</option>
                    <option value="Auto">Auto</option>
                    <option value="Moto">Moto</option>
                    <option value="Camion">Camion</option>
                    <option value="Tracteur">Tracteur</option>
                  </select>
                </div>
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 mb-1">Description</label>
                <textarea
                  value={editingProduct.description || ''}
                  onChange={(e) => setEditingProduct({...editingProduct, description: e.target.value})}
                  className="w-full border border-gray-300 rounded px-3 py-2"
                  rows={3}
                />
              </div>
              <div className="pt-4 flex gap-3">
                <button
                  type="button"
                  onClick={() => setEditingProduct(null)}
                  className="flex-1 text-gray-600 font-bold py-2 border border-gray-300 rounded hover:bg-gray-50"
                >
                  Annuler
                </button>
                <button
                  type="submit"
                  disabled={saving}
                  className="flex-1 bg-blue-600 text-white font-bold py-2 rounded hover:bg-blue-700 disabled:opacity-50 flex items-center justify-center gap-2"
                >
                  {saving ? <Loader2 className="animate-spin" size={16} /> : <Save size={16} />}
                  Sauvegarder
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useEffect, useState } from 'react';
import { Wrench, MapPin, Calendar, DollarSign, Loader2 } from 'lucide-react';
import { createClient } from '@/lib/supabase';
import { useRouter } from 'next/navigation';
import DashboardShell from '@/components/dashboard/DashboardShell';

export default function GarageDashboard() {
  const [activeTab, setActiveTab] = useState('appointments');
  const [garage, setGarage] = useState<any>(null);
  const [appointments, setAppointments] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const supabase = createClient();
  const router = useRouter();

  // Profile Form State
  const [formData, setFormData] = useState({
    name: '',
    address: '',
    city: '',
    zip_code: '',
    phone_primary: '',
    email: '',
    hourly_rate: ''
  });

  useEffect(() => {
    const fetchData = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        router.push('/auth/login');
        return;
      }

      // Fetch Garage
      const { data: garageData } = await supabase.from('garages').select('*').eq('profile_id', user.id).single();
      
      if (garageData) {
        setGarage(garageData);
        setFormData({
          name: garageData.name || '',
          address: garageData.address || '',
          city: garageData.city || '',
          zip_code: garageData.zip_code || '',
          phone_primary: garageData.phone_primary || '',
          email: user.email || '',
          hourly_rate: garageData.hourly_rate || ''
        });

        // Fetch Appointments
        const { data: items } = await supabase
          .from('order_items')
          .select('*, products(name, brand), orders(created_at, status, user_id, contact_name, contact_phone)')
          .eq('garage_id', garageData.id)
          .order('created_at', { ascending: false });
        
        setAppointments(items || []);
      }
      setLoading(false);
    };
    fetchData();
  }, []);

  const handleSaveProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    const { error } = await supabase.from('garages').update({
      name: formData.name,
      address: formData.address,
      city: formData.city,
      zip_code: formData.zip_code,
      phone_primary: formData.phone_primary
    }).eq('id', garage.id);

    if (error) alert('Erreur lors de la sauvegarde: ' + error.message);
    else alert('Profil mis à jour !');
    setSaving(false);
  };

  const handleSignOut = async () => {
    await supabase.auth.signOut();
    router.push('/auth/login');
  };

  if (loading) return <div className="flex h-screen items-center justify-center bg-[#F1F1F1]"><Loader2 className="animate-spin text-blue-600" size={48} /></div>;

  return (
    <DashboardShell
      title="Mon Garage"
      subtitle="Espace Partenaire"
      items={[
        { key: 'appointments', label: 'Rendez-vous', icon: Calendar },
        { key: 'profile', label: 'Profil Garage', icon: MapPin },
        { key: 'credits', label: 'Mes Crédits', icon: DollarSign },
      ]}
      activeKey={activeTab}
      onSelect={setActiveTab}
      onSignOut={handleSignOut}
    >
        {activeTab === 'appointments' && (
          <>
            <header className="mb-8">
              <h1 className="text-2xl font-bold text-gray-800">Planning des Montages</h1>
              <p className="text-gray-500 text-sm">Gérez les commandes à livrer et monter dans votre garage.</p>
            </header>
            
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
              {appointments.length > 0 ? (
                <div className="divide-y divide-gray-100">
                  {appointments.map((apt) => (
                    <div key={apt.id} className="p-6 flex items-center justify-between hover:bg-gray-50 transition-colors">
                      <div className="flex items-center gap-4">
                        <div className="p-3 bg-blue-100 text-blue-600 rounded-lg">
                          <Wrench size={24} />
                        </div>
                        <div>
                          <p className="font-bold text-gray-800">{apt.products?.name}</p>
                          {apt.orders?.contact_name && (
                             <p className="text-sm font-semibold text-gray-700 mt-1">Client: {apt.orders.contact_name} {apt.orders.contact_phone ? `(${apt.orders.contact_phone})` : ''}</p>
                          )}
                          <p className="text-sm text-gray-500">Qté: {apt.quantity} • {new Date(apt.created_at).toLocaleDateString()}</p>
                          <p className="text-xs text-blue-600 mt-1">Commande du {new Date(apt.orders?.created_at).toLocaleDateString()}</p>
                        </div>
                      </div>
                      <div className="text-right">
                        <span className={`inline-block px-3 py-1 rounded-full text-xs font-bold ${apt.orders?.status === 'pending' ? 'bg-yellow-100 text-yellow-700' : 'bg-green-100 text-green-700'}`}>
                          {apt.orders?.status === 'pending' ? 'En attente' : 'Confirmé'}
                        </span>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="p-12 text-center text-gray-500">
                  <Calendar size={48} className="mx-auto mb-4 opacity-20" />
                  <p>Aucun rendez-vous planifié pour le moment.</p>
                </div>
              )}
            </div>
          </>
        )}

        {activeTab === 'profile' && (
          <>
            <header className="mb-8">
              <h1 className="text-2xl font-bold text-gray-800">Mon Profil Garage</h1>
              <p className="text-gray-500 text-sm">Mettez à jour vos informations publiques.</p>
            </header>

            <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-8 max-w-2xl">
              <form onSubmit={handleSaveProfile} className="space-y-6">
                <div className="grid grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2">Nom du Garage</label>
                    <input type="text" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full border rounded-lg px-4 py-2" />
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2">Téléphone</label>
                    <input type="text" value={formData.phone_primary} onChange={e => setFormData({...formData, phone_primary: e.target.value})} className="w-full border rounded-lg px-4 py-2" />
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-bold text-gray-700 mb-2">Adresse</label>
                  <input type="text" value={formData.address} onChange={e => setFormData({...formData, address: e.target.value})} className="w-full border rounded-lg px-4 py-2" />
                </div>
                <div className="grid grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2">Ville</label>
                    <input type="text" value={formData.city} onChange={e => setFormData({...formData, city: e.target.value})} className="w-full border rounded-lg px-4 py-2" />
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2">Code Postal</label>
                    <input type="text" value={formData.zip_code} onChange={e => setFormData({...formData, zip_code: e.target.value})} className="w-full border rounded-lg px-4 py-2" />
                  </div>
                </div>
                <button type="submit" disabled={saving} className="bg-blue-600 text-white px-6 py-3 rounded-lg font-bold hover:bg-blue-700 transition-colors flex items-center gap-2">
                  {saving && <Loader2 className="animate-spin" size={18} />}
                  Sauvegarder les modifications
                </button>
              </form>
            </div>
          </>
        )}

        {activeTab === 'credits' && (
           <>
            <header className="mb-8">
              <h1 className="text-2xl font-bold text-gray-800">Mes Crédits</h1>
              <p className="text-gray-500 text-sm">Historique de vos gains d'installation.</p>
            </header>
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-8 text-center">
               <p className="text-gray-500 mb-2">Total accumulé</p>
               <p className="text-4xl font-bold text-green-600">€0.00</p>
               <p className="text-xs text-gray-400 mt-4">Le système de calcul de commission est en cours de configuration.</p>
            </div>
           </>
        )}
    </DashboardShell>
  );
}

"use client";

import React, { useState } from 'react';
import Papa from 'papaparse';
import { createClient } from '@/lib/supabase';
import { Upload, FileText, CheckCircle, AlertCircle, Loader2 } from 'lucide-react';

export default function ProductUploadPage() {
  const supabase = createClient();
  const [file, setFile] = useState<File | null>(null);
  const [loading, setLoading] = useState(false);
  const [sftpLoading, setSftpLoading] = useState(false);
  const [urlLoading, setUrlLoading] = useState(false);
  const [storageLoading, setStorageLoading] = useState(false);
  const [importUrl, setImportUrl] = useState('');
  const [storagePath, setStoragePath] = useState('');
  const [storageBucket, setStorageBucket] = useState('product-imports');
  const [logs, setLogs] = useState<string[]>([]);
  const [successCount, setSuccessCount] = useState(0);
  const [errorCount, setErrorCount] = useState(0);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      setFile(e.target.files[0]);
      setLogs([]);
      setSuccessCount(0);
      setErrorCount(0);
    }
  };

  const processCSV = async () => {
    if (!file) return;
    setLoading(true);
    setLogs(prev => [...prev, "Début du traitement du fichier..."]);

    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
      setLogs(prev => [...prev, "Erreur: Utilisateur non connecté."]);
      setLoading(false);
      return;
    }

    // Try to get supplier_id if user is a supplier (optional linking)
    const { data: supplier } = await supabase
      .from('suppliers')
      .select('id')
      .eq('profile_id', user.id)
      .single();

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      delimiter: "", // Auto-detect delimiter
      complete: async (results) => {
        setLogs(prev => [...prev, `${results.data.length} lignes trouvées.`]);
        console.log("Headers detected:", results.meta.fields); // Debug headers
        
        let success = 0;
        let errors = 0;
        
        // Coletar valores únicos de pa_tipo agrupados por categoria
        const subcategoriesMap = new Map<string, Set<string>>(); // Map<parentCategory, Set<pa_tipo>>

        for (const row of results.data as any[]) {
          try {
            // 1. Handle Brand (Auto-create if not exists)
            const brandName = row['pa_marca'] || row['Brand'] || row['Marque'];
            let brandId = null;

            if (brandName) {
              // Check if brand exists
              const { data: existingBrand } = await supabase
                .from('brands')
                .select('id')
                .eq('name', brandName)
                .single();

              if (existingBrand) {
                brandId = existingBrand.id;
              } else {
                // Create new brand
                const { data: newBrand, error: brandError } = await supabase
                  .from('brands')
                  .insert([{ name: brandName, is_active: true }])
                  .select('id')
                  .single();
                
                if (brandError) {
                   console.error("Error creating brand:", brandError);
                   setLogs(prev => [...prev, `Warning: Could not create brand ${brandName}`]);
                } else {
                   brandId = newBrand.id;
                   setLogs(prev => [...prev, `New brand created: ${brandName}`]);
                }
              }
            }

            // Map CSV columns to Database Schema
            const productData = {
              name: row['name'] || row['Nom'] || row['Titre'], // Fallbacks
              base_price: parseFloat((row['regular_price'] || row['Prix régulier'] || '0').replace(',', '.')),
              sale_price: row['sale_price'] ? parseFloat(row['sale_price']?.replace(',', '.')) : null,
              description: row['description'] || row['Description'],
              images: [
                row['image de couverture'], 
                row['images'], 
                row['imagem_secundaria']
              ].filter(url => url && url.length > 0),
              
              // New fields mapping
              brand: brandName, // Keep text for backward compatibility
              brand_id: brandId, // Link to brands table
              ean: row['EAN'],
              shipping_cost: parseFloat(row['prix d\'expédition']?.replace(',', '.') || '0'),
              category: row['pa_categoria'] || row['pa_tipo'], // Fallback
              
              // Armazenar pa_tipo para criar subcategorias do menu
              pa_tipo: row['pa_tipo'] || null,
              
              // Specs JSON
              specs: {
                width: row['pa_largeur'],
                height: row['pa_hauteur'],
                diameter: row['pa_diametre'],
                load_index: row['pa_charge'],
                speed_index: row['pa_vitesse'],
                season: row['pa_clima'],
                runflat: row['autres catégories']?.includes('Runflat') || false,
                extra_load: row['autres catégories']?.includes('XL') || false,
                // Armazenar outras categorias como array (ex: ["M+S", "XL", "Runflat"])
                autres_categories: (() => {
                  const autresCat = row['autres catégories'] || row['autres categories'] || row['autres_categories'] || '';
                  if (!autresCat || autresCat.trim() === '') return [];
                  // Suporta separação por vírgula, ponto e vírgula, ou pipe
                  return autresCat
                    .split(/[,;|]/)
                    .map((cat: string) => cat.trim())
                    .filter((cat: string) => cat.length > 0);
                })(),
              },

              // Labels JSON
              labels: {
                fuel: row['consommation de carburant'],
                wet: row['adhérence au sol'],
                noise: row['niveau sonore extreme'],
                noise_class: row['Class'],
                label_url: row['étiquette'] // URL to PDF/Image of label
              },

              // Linking
              supplier_user_id: user.id, // Direct link to uploader
              supplier_id: supplier?.id || null, // Link to supplier profile if exists
              is_active: true
            };

            // Basic Validation
            if (!productData.name || !productData.base_price) {
              throw new Error(`Nom ou prix manquant pour ${productData.name || 'Produit inconnu'}`);
            }

            const { error } = await supabase.from('products').insert(productData);

            if (error) throw error;
            success++;
            
            // Coletar pa_tipo para criar subcategorias do menu
            const paTipo = row['pa_tipo'];
            const productCategory = productData.category;
            
            if (paTipo && productCategory) {
              // Mapear categoria do produto para categoria pai do menu
              let parentCategory = 'Auto'; // Default
              const catLower = productCategory.toLowerCase();
              if (catLower.includes('moto')) parentCategory = 'Moto';
              else if (catLower.includes('camion') || catLower.includes('poids lourd')) parentCategory = 'Camion';
              else if (catLower.includes('tracteur') || catLower.includes('agricol')) parentCategory = 'Tracteur';
              
              if (!subcategoriesMap.has(parentCategory)) {
                subcategoriesMap.set(parentCategory, new Set());
              }
              subcategoriesMap.get(parentCategory)!.add(paTipo);
            }

          } catch (err: any) {
            console.error(err);
            errors++;
            setLogs(prev => [...prev, `Erreur ligne: ${row['name']} - ${err.message}`]);
          }
        }

        // Criar/atualizar subcategorias do menu baseadas em pa_tipo
        if (subcategoriesMap.size > 0) {
          setLogs(prev => [...prev, `Création des sous-catégories du menu...`]);
          let subcategoriesCreated = 0;
          
          for (const [parentCategory, paTipos] of subcategoriesMap.entries()) {
            for (const paTipo of paTipos) {
              if (!paTipo || paTipo.trim() === '') continue;
              
              try {
                // Gerar slug a partir do nome
                const slug = paTipo
                  .toLowerCase()
                  .normalize('NFD')
                  .replace(/[\u0300-\u036f]/g, '')
                  .replace(/[^a-z0-9\s]/g, '')
                  .replace(/\s+/g, '-')
                  .trim();
                
                // Verificar se já existe
                const { data: existing } = await supabase
                  .from('menu_subcategories')
                  .select('id')
                  .eq('parent_category', parentCategory)
                  .eq('slug', slug)
                  .single();
                
                if (!existing) {
                  // Criar nova subcategoria
                  const { error: subError } = await supabase
                    .from('menu_subcategories')
                    .insert([{
                      parent_category: parentCategory,
                      name: paTipo,
                      slug: slug,
                      is_active: true,
                      sort_order: 0
                    }]);
                  
                  if (subError) {
                    console.error('Error creating subcategory:', subError);
                  } else {
                    subcategoriesCreated++;
                  }
                }
              } catch (err: any) {
                console.error('Error processing subcategory:', err);
              }
            }
          }
          
          if (subcategoriesCreated > 0) {
            setLogs(prev => [...prev, `${subcategoriesCreated} sous-catégories créées dans le menu.`]);
          }
        }

        setSuccessCount(success);
        setErrorCount(errors);
        setLoading(false);
        setLogs(prev => [...prev, `Terminé. ${success} succès, ${errors} échecs.`]);
      }
    });
  };

  const importFromSftp = async () => {
    setSftpLoading(true);
    setLogs((prev) => [...prev, "Début de l'importation SFTP..."]);
    setSuccessCount(0);
    setErrorCount(0);

    try {
      const response = await fetch('/api/admin/import-products-sftp', {
        method: 'POST',
        headers: {
          Accept: 'application/json',
        },
      });

      const data = await response.json().catch(() => ({}));
      if (!response.ok || !data.ok) {
        throw new Error(data.error || `Erreur serveur (${response.status})`);
      }

      setSuccessCount(data.success || 0);
      setErrorCount(data.errors || 0);
      const apiLogs: string[] = Array.isArray(data.logs) ? data.logs : [];
      setLogs((prev) => [...prev, ...apiLogs, "Importation SFTP terminée."]);
    } catch (error: any) {
      setLogs((prev) => [...prev, `Erreur SFTP: ${error?.message || 'inconnue'}`]);
    } finally {
      setSftpLoading(false);
    }
  };

  const importFromUrl = async () => {
    const url = importUrl.trim();
    if (!url) {
      setLogs((prev) => [...prev, 'Erreur: URL vide.']);
      return;
    }
    setUrlLoading(true);
    setLogs((prev) => [...prev, "Début de l'importation depuis URL HTTPS..."]);
    setSuccessCount(0);
    setErrorCount(0);
    try {
      const response = await fetch('/api/admin/import-products-url', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
        body: JSON.stringify({ url }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || !data.ok) {
        throw new Error(data.error || `Erreur serveur (${response.status})`);
      }
      setSuccessCount(data.success || 0);
      setErrorCount(data.errors || 0);
      const apiLogs: string[] = Array.isArray(data.logs) ? data.logs : [];
      setLogs((prev) => [...prev, ...apiLogs, 'Importation URL terminée.']);
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : 'inconnue';
      setLogs((prev) => [...prev, `Erreur URL: ${msg}`]);
    } finally {
      setUrlLoading(false);
    }
  };

  const importFromStorage = async () => {
    const path = storagePath.trim();
    if (!path) {
      setLogs((prev) => [...prev, 'Erreur: chemin Storage vide (ex: imports/produits.csv).']);
      return;
    }
    setStorageLoading(true);
    setLogs((prev) => [...prev, "Début de l'importation depuis Supabase Storage..."]);
    setSuccessCount(0);
    setErrorCount(0);
    try {
      const bucket = storageBucket.trim() || 'product-imports';
      const response = await fetch('/api/admin/import-products-storage', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
        body: JSON.stringify({ path, bucket }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || !data.ok) {
        throw new Error(data.error || `Erreur serveur (${response.status})`);
      }
      setSuccessCount(data.success || 0);
      setErrorCount(data.errors || 0);
      const apiLogs: string[] = Array.isArray(data.logs) ? data.logs : [];
      setLogs((prev) => [...prev, ...apiLogs, 'Importation Storage terminée.']);
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : 'inconnue';
      setLogs((prev) => [...prev, `Erreur Storage: ${msg}`]);
    } finally {
      setStorageLoading(false);
    }
  };

  const remoteBusy = loading || sftpLoading || urlLoading || storageLoading;

  return (
    <div className="p-8 max-w-4xl mx-auto">
      <h1 className="text-2xl font-bold text-gray-800 mb-6">Importer des Produits</h1>
      
      <div className="bg-white p-8 rounded-xl shadow-sm border border-gray-100 mb-8">
        <div className="mb-4 p-4 rounded-lg bg-indigo-50 border border-indigo-100 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
          <div>
            <p className="text-sm font-bold text-indigo-900">Importation via SFTP</p>
            <p className="text-xs text-indigo-700">
              Télécharge le CSV distant défini dans les variables d&apos;environnement (Vercel / .env).
            </p>
          </div>
          <button
            onClick={importFromSftp}
            disabled={remoteBusy}
            className="bg-indigo-600 text-white px-4 py-2 rounded-lg font-bold hover:bg-indigo-700 disabled:opacity-50 flex items-center gap-2"
          >
            {sftpLoading && <Loader2 className="animate-spin" size={16} />}
            Importer via SFTP
          </button>
        </div>

        <div className="mb-4 p-4 rounded-lg bg-emerald-50 border border-emerald-100 space-y-3">
          <p className="text-sm font-bold text-emerald-900">Importation via URL HTTPS</p>
          <p className="text-xs text-emerald-800">
            Lien direct vers un fichier CSV (éviter Google Drive/Dropbox sans lien de téléchargement direct). Max ~15 Mo.
          </p>
          <div className="flex flex-col sm:flex-row gap-2">
            <input
              type="url"
              value={importUrl}
              onChange={(e) => setImportUrl(e.target.value)}
              placeholder="https://exemple.com/export/produits.csv"
              className="flex-1 border border-emerald-200 rounded px-3 py-2 text-sm"
            />
            <button
              type="button"
              onClick={importFromUrl}
              disabled={remoteBusy}
              className="bg-emerald-600 text-white px-4 py-2 rounded-lg font-bold hover:bg-emerald-700 disabled:opacity-50 flex items-center justify-center gap-2"
            >
              {urlLoading && <Loader2 className="animate-spin" size={16} />}
              Importer depuis URL
            </button>
          </div>
        </div>

        <div className="mb-4 p-4 rounded-lg bg-sky-50 border border-sky-100 space-y-3">
          <p className="text-sm font-bold text-sky-900">Importation via Supabase Storage</p>
          <p className="text-xs text-sky-800">
            Créez le bucket <code className="bg-sky-100 px-1 rounded">product-imports</code> (script SQL), uploadez le CSV
            depuis le dashboard Supabase, puis indiquez le chemin du fichier.
          </p>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
            <input
              type="text"
              value={storageBucket}
              onChange={(e) => setStorageBucket(e.target.value)}
              placeholder="Bucket (défaut: product-imports)"
              className="border border-sky-200 rounded px-3 py-2 text-sm"
            />
            <input
              type="text"
              value={storagePath}
              onChange={(e) => setStoragePath(e.target.value)}
              placeholder="Chemin: imports/produits.csv"
              className="border border-sky-200 rounded px-3 py-2 text-sm"
            />
          </div>
          <button
            type="button"
            onClick={importFromStorage}
            disabled={remoteBusy}
            className="bg-sky-600 text-white px-4 py-2 rounded-lg font-bold hover:bg-sky-700 disabled:opacity-50 flex items-center gap-2"
          >
            {storageLoading && <Loader2 className="animate-spin" size={16} />}
            Importer depuis Storage
          </button>
        </div>

        <div className="border-2 border-dashed border-gray-300 rounded-lg p-12 text-center hover:bg-gray-50 transition-colors">
          <Upload className="mx-auto h-12 w-12 text-gray-400 mb-4" />
          <p className="text-gray-600 mb-2">Glissez votre fichier CSV ici ou cliquez pour parcourir</p>
          <p className="text-xs text-gray-400 mb-4">Format supporté: CSV (Tabulation ou Virgule)</p>
          <input 
            type="file" 
            accept=".csv" 
            onChange={handleFileChange} 
            className="block w-full text-sm text-gray-500
              file:mr-4 file:py-2 file:px-4
              file:rounded-full file:border-0
              file:text-sm file:font-semibold
              file:bg-blue-50 file:text-blue-700
              hover:file:bg-blue-100"
          />
        </div>

        {file && (
          <div className="mt-6 flex justify-between items-center bg-blue-50 p-4 rounded-lg">
            <div className="flex items-center gap-3">
              <FileText className="text-blue-600" />
              <span className="font-medium text-blue-900">{file.name}</span>
              <span className="text-xs text-blue-500">({(file.size / 1024).toFixed(2)} KB)</span>
            </div>
            <button 
              onClick={processCSV} 
              disabled={remoteBusy}
              className="bg-blue-600 text-white px-6 py-2 rounded-lg font-bold hover:bg-blue-700 disabled:opacity-50 flex items-center gap-2"
            >
              {loading && <Loader2 className="animate-spin" size={16} />}
              Lancer l'importation
            </button>
          </div>
        )}
      </div>

      {(successCount > 0 || errorCount > 0) && (
        <div className="grid grid-cols-2 gap-4 mb-8">
          <div className="bg-green-50 p-4 rounded-lg flex items-center gap-3 text-green-700 border border-green-100">
            <CheckCircle />
            <div>
              <p className="font-bold text-lg">{successCount}</p>
              <p className="text-sm">Produits importés</p>
            </div>
          </div>
          <div className="bg-red-50 p-4 rounded-lg flex items-center gap-3 text-red-700 border border-red-100">
            <AlertCircle />
            <div>
              <p className="font-bold text-lg">{errorCount}</p>
              <p className="text-sm">Erreurs</p>
            </div>
          </div>
        </div>
      )}

      <div className="bg-gray-900 text-gray-300 p-6 rounded-lg font-mono text-xs h-64 overflow-y-auto">
        <p className="text-gray-500 mb-2">// Logs d'importation</p>
        {logs.length === 0 && <p className="opacity-50">En attente...</p>}
        {logs.map((log, i) => (
          <p key={i} className="mb-1 border-b border-gray-800 pb-1">{`> ${log}`}</p>
        ))}
      </div>
    </div>
  );
}

