"use client";

import React, { useState, useEffect, useRef } from 'react';
import { 
  ShoppingCart, User, ChevronDown, Menu, X,
  CloudSun, Mountain, Truck, Tent, Sun, Snowflake, Car, Zap, Disc,
  Bike, Flag, Star, Map, Box, Navigation,
  Bus, Hammer, MapPin,
  Tractor, Leaf, Factory, Search, CircleDot, Warehouse
} from 'lucide-react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useCart } from '@/context/CartContext';
import { Loader2 } from 'lucide-react';
import PromoBanner from './PromoBanner';

// Mapeamento de ícones (fallback se não houver ícone definido)
const iconMap: { [key: string]: any } = {
  'CloudSun': CloudSun,
  'Mountain': Mountain,
  'Truck': Truck,
  'Tent': Tent,
  'Sun': Sun,
  'Snowflake': Snowflake,
  'Car': Car,
  'Zap': Zap,
  'Disc': Disc,
  'Bike': Bike,
  'Flag': Flag,
  'Star': Star,
  'Map': Map,
  'Box': Box,
  'Navigation': Navigation,
  'Bus': Bus,
  'Hammer': Hammer,
  'MapPin': MapPin,
  'Tractor': Tractor,
  'Leaf': Leaf,
  'Factory': Factory,
  'Search': Search,
  'CircleDot': CircleDot,
  'Warehouse': Warehouse,
};

type StaticMenuItem = {
  label: string;
  slug: string;
  iconKey: keyof typeof iconMap;
  /** Se definido, não usa /categorie/[slug] (ex. landing tracteurs). */
  href?: string;
};

function chunkColumns<T>(items: T[], perColumn: number): T[][] {
  const cols: T[][] = [];
  for (let i = 0; i < items.length; i += perColumn) {
    cols.push(items.slice(i, i + perColumn));
  }
  return cols;
}

/** Slug alinhado à função SQL generate_slug (remove não alfanuméricos, hífens). */
function slugFromMenuLabel(label: string): string {
  return label
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, '')
    .trim()
    .replace(/\s+/g, '-');
}

const STATIC_SUBMENU: Record<string, StaticMenuItem[]> = {
  Auto: [
    { label: 'Pneus 4 Saisons', slug: slugFromMenuLabel('Pneus 4 Saisons'), iconKey: 'CloudSun' },
    { label: 'Pneus 4x4/SUV', slug: slugFromMenuLabel('Pneus 4x4/SUV'), iconKey: 'Mountain' },
    { label: 'Pneus camionnette', slug: slugFromMenuLabel('Pneus camionnette'), iconKey: 'Truck' },
    { label: 'Pneus camping', slug: slugFromMenuLabel('Pneus camping'), iconKey: 'Tent' },
    { label: 'Pneus été Auto', slug: slugFromMenuLabel('Pneus été Auto'), iconKey: 'Sun' },
    { label: 'Pneus Hiver', slug: slugFromMenuLabel('Pneus Hiver'), iconKey: 'Snowflake' },
    { label: 'Pneus Voiture', slug: slugFromMenuLabel('Pneus Voiture'), iconKey: 'Car' },
    { label: 'Pneus voiture électrique', slug: slugFromMenuLabel('Pneus voiture électrique'), iconKey: 'Zap' },
    { label: 'Type-c', slug: slugFromMenuLabel('Type-c'), iconKey: 'Disc' },
  ],
  Moto: [
    { label: 'Chopper / Cruiser', slug: slugFromMenuLabel('Chopper / Cruiser'), iconKey: 'Bike' },
    { label: 'Pneus circuit et piste', slug: slugFromMenuLabel('Pneus circuit et piste'), iconKey: 'Flag' },
    { label: 'Pneus cross / enduro / trial', slug: slugFromMenuLabel('Pneus cross / enduro / trial'), iconKey: 'Mountain' },
    { label: 'Pneus custom et collection', slug: slugFromMenuLabel('Pneus custom et collection'), iconKey: 'Star' },
    { label: 'Pneus moto sport et route', slug: slugFromMenuLabel('Pneus moto sport et route'), iconKey: 'Navigation' },
    { label: 'Pneus scooter', slug: slugFromMenuLabel('Pneus scooter'), iconKey: 'Box' },
    { label: 'Pneus trail', slug: slugFromMenuLabel('Pneus trail'), iconKey: 'Map' },
    { label: 'Quad / Véhicule tout terrain', slug: slugFromMenuLabel('Quad / Véhicule tout terrain'), iconKey: 'Mountain' },
    { label: 'Sport Tourisme diagonal', slug: slugFromMenuLabel('Sport Tourisme diagonal'), iconKey: 'Disc' },
    { label: 'Sport Tourisme radial', slug: slugFromMenuLabel('Sport Tourisme radial'), iconKey: 'Disc' },
  ],
  Camion: [
    { label: 'Pneus autocar - autobus', slug: slugFromMenuLabel('Pneus autocar - autobus'), iconKey: 'Bus' },
    { label: 'Pneus chantier', slug: slugFromMenuLabel('Pneus chantier'), iconKey: 'Hammer' },
    { label: 'Pneus longue distance', slug: slugFromMenuLabel('Pneus longue distance'), iconKey: 'Truck' },
    { label: 'Pneus régionaux', slug: slugFromMenuLabel('Pneus régionaux'), iconKey: 'MapPin' },
  ],
  Tracteur: [
    { label: 'Pneus avant tracteur', slug: slugFromMenuLabel('Pneus avant tracteur'), iconKey: 'Tractor' },
    { label: 'Pneus espaces verts', slug: slugFromMenuLabel('Pneus espaces verts'), iconKey: 'Leaf' },
    { label: 'Pneus industriel et manutention', slug: slugFromMenuLabel('Pneus industriel et manutention'), iconKey: 'Factory' },
    { label: 'Pneus remorque agricole', slug: slugFromMenuLabel('Pneus remorque agricole'), iconKey: 'Warehouse' },
    { label: 'Pneus roue motrice', slug: slugFromMenuLabel('Pneus roue motrice'), iconKey: 'CircleDot' },
    { label: 'Recherche par dimension', slug: 'tracteurs', iconKey: 'Search', href: '/tracteurs' },
  ],
};

const NAV_ENTRIES: Array<{
  title: string;
  key: keyof typeof STATIC_SUBMENU;
  mainHref: string;
  columnsPerChunk: number;
}> = [
  { title: 'Pneus Auto', key: 'Auto', mainHref: '/', columnsPerChunk: 3 },
  { title: 'Pneu Moto', key: 'Moto', mainHref: '/moto', columnsPerChunk: 3 },
  { title: 'Pneus Camion', key: 'Camion', mainHref: '/camion', columnsPerChunk: 2 },
  { title: 'Pneus Agricoles', key: 'Tracteur', mainHref: '/tracteurs', columnsPerChunk: 3 },
];

function buildNavigationData() {
  return NAV_ENTRIES.map((entry) => {
    const raw = STATIC_SUBMENU[entry.key];
    const items = raw.map((s) => ({
      label: s.label,
      slug: s.slug,
      href: s.href,
      icon: iconMap[s.iconKey] || Car,
    }));
    return {
      title: entry.title,
      key: entry.key,
      mainHref: entry.mainHref,
      columns: chunkColumns(items, entry.columnsPerChunk),
    };
  });
}

const navigationDataStatic = buildNavigationData();

export default function Header() {
  const { cartCount } = useCart();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [activeMobileCategory, setActiveMobileCategory] = useState<string | null>(null);
  const [searchOpen, setSearchOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<any[]>([]);
  const [searchLoading, setSearchLoading] = useState(false);
  const searchInputRef = React.useRef<HTMLInputElement>(null);

  // Busca de produtos
  useEffect(() => {
    if (!searchQuery.trim() || searchQuery.length < 2) {
      setSearchResults([]);
      return;
    }

    const controller = new AbortController();

    const searchProducts = async () => {
      setSearchLoading(true);
      try {
        // Uma única consulta no servidor (nome, marca, categoria, tipo e specs).
        const res = await fetch(`/api/products/suggest?q=${encodeURIComponent(searchQuery.trim())}`, {
          signal: controller.signal,
        });
        const json = res.ok ? await res.json() : { data: [] };
        setSearchResults(Array.isArray(json.data) ? json.data : []);
      } catch (error) {
        if ((error as Error)?.name === 'AbortError') return;
        console.error('Error searching products:', error);
        setSearchResults([]);
      } finally {
        if (!controller.signal.aborted) setSearchLoading(false);
      }
    };

    const debounceTimer = setTimeout(() => {
      searchProducts();
    }, 300);

    return () => {
      clearTimeout(debounceTimer);
      controller.abort();
    };
  }, [searchQuery]);

  // Focar no input quando o modal abrir
  useEffect(() => {
    if (searchOpen && searchInputRef.current) {
      searchInputRef.current.focus();
    }
  }, [searchOpen]);

  const router = useRouter();

  const handleProductClick = (productId: string) => {
    setSearchOpen(false);
    setSearchQuery('');
    router.push(`/product/${productId}`);
  };

  return (
    <>
    <header className="sticky top-0 z-50 w-full">
      <div className="layout-container pt-2 md:pt-3">
        <div className="relative">
          <div className="relative bg-white shadow-sm h-16 md:h-20 grid grid-cols-[auto_1fr_auto] md:grid-cols-[minmax(0,1fr)_auto_minmax(0,1fr)] items-center gap-x-2 md:gap-x-3 px-3 sm:px-4 md:px-5">
        <div className="flex items-center gap-1 min-w-0 justify-self-start">
          <button 
            className="md:hidden text-gray-700 p-2 shrink-0"
            type="button"
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          >
            {mobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
          <Link href="/" className="flex items-center gap-2 shrink-0 min-w-0">
            <img 
              src="/logo.png" 
              alt="MecaniDoc Logo" 
              className="object-contain h-8 w-auto max-h-8 md:max-h-9 max-w-[min(160px,42vw)]" 
            />
          </Link>
        </div>

        {/* Desktop Navigation — coluna central para alinhar ao centro da barra */}
        <nav className="hidden md:flex items-center justify-center gap-2 lg:gap-3 text-sm font-medium text-gray-700 h-full min-w-0 justify-self-center">
          {navigationDataStatic.map((item) => (
            <div key={item.title} className="group h-full flex items-center">
              <Link
                href={item.mainHref}
                className="flex items-center gap-1 hover:text-blue-600 h-full border-b-2 border-transparent hover:border-blue-600 transition-colors whitespace-nowrap"
              >
                {item.title} <ChevronDown size={14} className="opacity-60 shrink-0" aria-hidden />
              </Link>
              
              <div className="absolute left-0 right-0 top-full z-[60] hidden w-full group-hover:block group-focus-within:block pointer-events-none group-hover:pointer-events-auto group-focus-within:pointer-events-auto">
                <div className="w-full bg-white border border-gray-200 border-t-0 shadow-xl rounded-b-lg animate-in fade-in slide-in-from-top-1 duration-200">
                  <div className="flex w-full">
                    {item.columns.map((column, colIndex) => (
                      <div key={colIndex} className={`flex-1 min-w-0 py-4 px-3 sm:px-4 md:px-5 ${colIndex !== item.columns.length - 1 ? 'border-r border-gray-100' : ''}`}>
                        <ul className="space-y-2">
                        {column.map((subItem) => {
                          const href = subItem.href ?? `/categorie/${subItem.slug}`;
                          return (
                          <li key={`${subItem.slug}-${subItem.label}`}>
                            <Link href={href} className="flex items-center gap-3 text-gray-600 hover:text-blue-600 transition-colors group/item">
                              <subItem.icon size={20} className="text-gray-500 group-hover/item:text-blue-600 shrink-0" />
                              <span className="text-sm font-medium">{subItem.label}</span>
                            </Link>
                          </li>
                          );
                        })}
                        </ul>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          ))}
        </nav>

        <div className="flex items-center justify-end gap-1.5 md:gap-2 shrink-0 min-w-0 justify-self-end">
          <button 
            onClick={() => setSearchOpen(true)}
            className="text-gray-600 hover:text-blue-600 transition-colors p-1"
            aria-label="Rechercher"
          >
            <Search size={20} className="w-5 h-5" />
          </button>
          <Link href="/auth/login" className="text-gray-600 hover:text-blue-600 p-1">
            <User size={20} className="w-5 h-5" />
          </Link>
          <Link href="/checkout" className="text-gray-600 hover:text-blue-600 relative p-1">
            <ShoppingCart size={20} className="w-5 h-5" />
            {cartCount > 0 && (
              <span className="absolute -top-1 -right-1 bg-red-500 text-white text-xs font-bold rounded-full min-w-[1.125rem] h-[1.125rem] px-0.5 flex items-center justify-center">
                {cartCount}
              </span>
            )}
          </Link>
        </div>
          </div>

      {/* Mobile Dropdown Menu */}
      {mobileMenuOpen && (
        <div className="md:hidden absolute top-full left-0 right-0 z-40 mt-0 w-full bg-white border border-gray-200 border-t-0 shadow-lg max-h-[calc(100vh-5rem)] overflow-y-auto">
          <div className="p-4 space-y-2">
            {navigationDataStatic.map((item) => (
              <div key={item.title} className="border-b border-gray-100 last:border-0">
                <div className="flex items-center gap-2 py-2">
                  <Link
                    href={item.mainHref}
                    className="flex-1 py-2 text-left font-bold text-gray-800 hover:text-blue-600"
                    onClick={() => setMobileMenuOpen(false)}
                  >
                    {item.title}
                  </Link>
                  <button 
                    type="button"
                    onClick={() => setActiveMobileCategory(activeMobileCategory === item.title ? null : item.title)}
                    className="p-2 text-gray-600"
                    aria-expanded={activeMobileCategory === item.title}
                    aria-label={`Sous-menu ${item.title}`}
                  >
                    <ChevronDown size={16} className={`transform transition-transform ${activeMobileCategory === item.title ? 'rotate-180' : ''}`} />
                  </button>
                </div>
                
                {activeMobileCategory === item.title && (
                  <div className="bg-gray-50 p-4 rounded-lg mb-2">
                    {item.columns.flat().map((subItem) => {
                      const href = subItem.href ?? `/categorie/${subItem.slug}`;
                      return (
                      <Link 
                        key={`${subItem.slug}-${subItem.label}`}
                        href={href}
                        className="flex items-center gap-3 py-2 text-sm text-gray-600 hover:text-blue-600"
                        onClick={() => setMobileMenuOpen(false)}
                      >
                        <subItem.icon size={16} className="shrink-0" />
                        {subItem.label}
                      </Link>
                      );
                    })}
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      )}
        </div>
      </div>

      {/* Search Modal */}
      {searchOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-[100] flex items-start justify-center pt-20 md:pt-32"
          onClick={(e) => {
            if (e.target === e.currentTarget) {
              setSearchOpen(false);
              setSearchQuery('');
            }
          }}
        >
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl mx-4 max-h-[80vh] flex flex-col">
            {/* Search Input */}
            <div className="p-4 border-b flex items-center gap-3">
              <Search className="text-gray-400" size={20} />
              <input
                ref={searchInputRef}
                type="text"
                placeholder="Rechercher par nom, marque, catégorie, dimensions..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="flex-1 outline-none text-gray-800 placeholder-gray-400"
                onKeyDown={(e) => {
                  if (e.key === 'Escape') {
                    setSearchOpen(false);
                    setSearchQuery('');
                  }
                }}
              />
              {searchLoading && <Loader2 className="animate-spin text-gray-400" size={20} />}
              <button
                onClick={() => {
                  setSearchOpen(false);
                  setSearchQuery('');
                }}
                className="text-gray-400 hover:text-gray-600"
              >
                <X size={20} />
              </button>
            </div>

            {/* Search Results */}
            <div className="flex-1 overflow-y-auto p-4">
              {searchQuery.length < 2 ? (
                <p className="text-gray-400 text-sm text-center py-8">
                  Tapez au moins 2 caractères pour rechercher
                </p>
              ) : searchLoading ? (
                <div className="flex justify-center py-8">
                  <Loader2 className="animate-spin text-gray-400" size={24} />
                </div>
              ) : searchResults.length === 0 ? (
                <p className="text-gray-400 text-sm text-center py-8">
                  Aucun produit trouvé pour "{searchQuery}"
                </p>
              ) : (
                <div className="space-y-2">
                  <p className="text-xs text-gray-500 mb-3">
                    {searchResults.length} résultat{searchResults.length > 1 ? 's' : ''} trouvé{searchResults.length > 1 ? 's' : ''}
                  </p>
                  {searchResults.map((product) => {
                    const specs = product.specs || {};
                    return (
                      <button
                        key={product.id}
                        onClick={() => handleProductClick(product.id)}
                        className="w-full text-left p-3 rounded-lg hover:bg-gray-50 border border-gray-100 transition-colors group"
                      >
                        <div className="flex items-center gap-4">
                          {/* Product Image */}
                          <div className="w-16 h-16 flex-shrink-0 bg-gray-100 rounded-lg overflow-hidden">
                            <img
                              src={product.images?.[0] || 'https://placehold.co/200x200/f3f4f6/d1d5db?text=Pneu'}
                              alt={product.name}
                              className="w-full h-full object-cover"
                            />
                          </div>
                          
                          {/* Product Info */}
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 mb-1">
                              {product.brands?.logo_url ? (
                                <img
                                  src={product.brands.logo_url}
                                  alt={product.brands.name}
                                  className="h-4 w-auto object-contain"
                                />
                              ) : (
                                <span className="text-xs font-bold text-gray-600 uppercase">
                                  {product.brands?.name || product.brand || 'Marque'}
                                </span>
                              )}
                            </div>
                            <h4 className="font-bold text-gray-800 text-sm mb-1 truncate group-hover:text-blue-600">
                              {product.name}
                            </h4>
                            <p className="text-xs text-gray-500">
                              {specs.width}/{specs.height} R{specs.diameter} {specs.load_index}{specs.speed_index}
                              {specs.autres_categories && specs.autres_categories.length > 0 && (
                                <span className="ml-1">• {specs.autres_categories.join(', ')}</span>
                              )}
                            </p>
                            <p className="text-xs text-gray-400 mt-1">
                              {product.category || 'Auto'} {product.pa_tipo && `• ${product.pa_tipo}`}
                            </p>
                          </div>

                          {/* Price */}
                          <div className="flex-shrink-0 text-right">
                            <p className="font-bold text-gray-800">
                              €{product.base_price?.toFixed(2) || '0.00'}
                            </p>
                          </div>
                        </div>
                      </button>
                    );
                  })}
                </div>
              )}
            </div>

            {/* Footer */}
            {searchQuery.length >= 2 && searchResults.length > 0 && (
              <div className="p-4 border-t bg-gray-50">
                <Link
                  href={`/search?q=${encodeURIComponent(searchQuery)}`}
                  onClick={() => {
                    setSearchOpen(false);
                    setSearchQuery('');
                  }}
                  className="text-sm text-blue-600 hover:text-blue-800 font-medium text-center block"
                >
                  Voir tous les résultats pour "{searchQuery}"
                </Link>
              </div>
            )}
          </div>
        </div>
      )}
    </header>
    <PromoBanner />
    </>
  );
}

"use client";

import React, { useEffect, useMemo, useRef, useState } from "react";
import Link from "next/link";
import { createClient } from "@/lib/supabase";
import { buildPromotionSearchHref } from "@/lib/promotion-search-url";
import { ChevronLeft, ChevronRight, Loader2 } from "lucide-react";

const CATEGORY_ORDER = ["Auto", "Moto", "Camion", "Tracteurs"] as const;
type ParentCategory = (typeof CATEGORY_ORDER)[number];

const BADGE_CLASS: Record<string, string> = {
  red: "bg-red-600 text-white",
  green: "bg-green-600 text-white",
  blue: "bg-blue-600 text-white",
  orange: "bg-orange-500 text-white",
};

const CARD_GRADIENTS = [
  "bg-gradient-to-br from-gray-900 to-gray-800",
  "bg-gradient-to-br from-blue-900 to-blue-800",
  "bg-gradient-to-br from-gray-800 to-black",
];

/** Dégradé sombre par-dessus la photo (bas → haut) pour lisibilité du texte blanc */
const OVERLAY_GRADIENT: Record<string, string> = {
  strong: "from-black/90 via-black/65 to-black/35",
  medium: "from-black/80 via-black/50 to-black/25",
  soft: "from-black/55 via-black/35 to-black/10",
};

function normalizeParentCategory(raw: string | null | undefined): ParentCategory | null {
  const t = (raw || "").trim();
  if (!t) return null;
  const l = t.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  if (l === "auto" || l === "automobile" || l === "voiture") return "Auto";
  if (l === "moto" || l === "motos") return "Moto";
  if (l === "camion" || l === "camions" || l === "poids lourd" || l === "poids lourds") return "Camion";
  if (l === "tracteur" || l === "tracteurs" || l === "agricole" || l === "agricoles") return "Tracteurs";
  return null;
}

function isActiveByDate(p: { start_date?: string | null; end_date?: string | null }) {
  const now = new Date();
  if (p.start_date && new Date(p.start_date) > now) return false;
  if (p.end_date && new Date(p.end_date) < now) return false;
  return true;
}

type PromoRow = {
  id: string;
  title: string;
  discount_text?: string | null;
  description?: string | null;
  link_url?: string | null;
  start_date?: string | null;
  end_date?: string | null;
  sort_order?: number | null;
  parent_category?: string | null;
  badge_text?: string | null;
  badge_color?: string | null;
  card_image_url?: string | null;
  card_overlay?: string | null;
};

function OfferCard({ p, index }: { p: PromoRow; index: number }) {
  const badgeLabel = (p.badge_text || p.discount_text || "OFFRE").trim() || "OFFRE";
  const badgeKey = (p.badge_color || "red").toLowerCase();
  const badgeCls = BADGE_CLASS[badgeKey] || BADGE_CLASS.red;
  const grad = CARD_GRADIENTS[index % CARD_GRADIENTS.length];
  const bgUrl = p.card_image_url?.trim();
  const overlayKey = (p.card_overlay || "medium").toLowerCase();
  const overlayGrad =
    OVERLAY_GRADIENT[overlayKey === "strong" || overlayKey === "soft" ? overlayKey : "medium"];

  const shell =
    "relative min-h-[152px] rounded-2xl overflow-hidden shadow-md border border-white/10 transition-transform hover:scale-[1.02] focus-within:ring-2 focus-within:ring-blue-400/60 focus-within:ring-offset-2 focus-within:ring-offset-[#F1F1F1]";

  const inner = (
    <div className={shell}>
      {bgUrl ? (
        <>
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src={bgUrl}
            alt=""
            className="absolute inset-0 h-full w-full object-cover"
            loading="lazy"
            decoding="async"
          />
          <div
            className={`pointer-events-none absolute inset-0 bg-gradient-to-t ${overlayGrad}`}
            aria-hidden
          />
        </>
      ) : (
        <div className={`absolute inset-0 ${grad}`} aria-hidden />
      )}
      <div className="relative z-10 flex min-h-[152px] flex-col justify-end p-5">
        <span className={`mb-2 w-fit rounded px-2 py-1 text-xs font-bold shadow-sm ${badgeCls}`}>{badgeLabel}</span>
        <h3 className="line-clamp-2 text-lg font-bold leading-snug text-white drop-shadow-sm">{p.title}</h3>
        {p.description ? (
          <p className="mt-1 line-clamp-2 text-sm text-white/90 drop-shadow-sm">{p.description}</p>
        ) : null}
      </div>
    </div>
  );

  const wrap = "block min-w-[min(100%,280px)] md:min-w-[300px] snap-center shrink-0";

  if (p.link_url?.trim()) {
    const href = p.link_url.trim();
    if (/^https?:\/\//i.test(href)) {
      return (
        <a href={href} target="_blank" rel="noopener noreferrer" className={wrap}>
          {inner}
        </a>
      );
    }
    return (
      <Link href={href} className={wrap}>
        {inner}
      </Link>
    );
  }

  const defaultHref = buildPromotionSearchHref({ id: p.id, parent_category: p.parent_category });
  return (
    <Link href={defaultHref} className={`${wrap} cursor-pointer`}>
      {inner}
    </Link>
  );
}

function OffersCarouselRow({ category, items }: { category: ParentCategory; items: PromoRow[] }) {
  const scrollRef = useRef<HTMLDivElement>(null);

  const scroll = (direction: "left" | "right") => {
    const el = scrollRef.current;
    if (!el) return;
    el.scrollBy({ left: direction === "left" ? -320 : 320, behavior: "smooth" });
  };

  return (
    <section className="py-3 md:py-5 bg-transparent relative group">
      <div className="layout-container">
        <h2 className="text-sm font-bold text-gray-900 mb-3 md:mb-4 uppercase tracking-wide">
          Offres — {category}
        </h2>
        <div className="relative">
          <button
            type="button"
            onClick={() => scroll("left")}
            className="hidden md:flex absolute left-[-12px] top-1/2 -translate-y-1/2 z-10 bg-white shadow-lg border border-gray-100 p-2.5 rounded-full text-gray-600 hover:text-blue-600 transition-all opacity-0 group-hover:opacity-100"
            aria-label="Défiler vers la gauche"
          >
            <ChevronLeft size={22} />
          </button>
          <div
            ref={scrollRef}
            className="flex overflow-x-auto gap-3 md:gap-4 pb-2 scrollbar-hide snap-x snap-mandatory scroll-smooth"
          >
            {items.map((p, idx) => (
              <OfferCard key={p.id} p={p} index={idx} />
            ))}
          </div>
          <button
            type="button"
            onClick={() => scroll("right")}
            className="hidden md:flex absolute right-[-12px] top-1/2 -translate-y-1/2 z-10 bg-white shadow-lg border border-gray-100 p-2.5 rounded-full text-gray-600 hover:text-blue-600 transition-all opacity-0 group-hover:opacity-100"
            aria-label="Défiler vers la droite"
          >
            <ChevronRight size={22} />
          </button>
        </div>
      </div>
    </section>
  );
}

interface HomeOffersCarouselsProps {
  /** Si défini (ex. page catégorie), un seul carrousel pour cette catégorie mère. */
  categoryFilter?: string | null;
}

export default function HomeOffersCarousels({ categoryFilter }: HomeOffersCarouselsProps) {
  const [rows, setRows] = useState<PromoRow[]>([]);
  const [loading, setLoading] = useState(true);
  const supabase = createClient();

  useEffect(() => {
    let cancelled = false;
    (async () => {
      setLoading(true);
      const { data, error } = await supabase
        .from("promotions")
        .select(
          "id, title, discount_text, description, link_url, start_date, end_date, sort_order, parent_category, badge_text, badge_color, card_image_url, card_overlay"
        )
        .eq("is_active", true)
        .order("sort_order", { ascending: true });

      if (cancelled) return;
      if (error) {
        console.error("promotions carrousel:", error);
        setRows([]);
        setLoading(false);
        return;
      }
      const list = (data || []) as PromoRow[];
      const active = list.filter(isActiveByDate);
      setRows(active);
      setLoading(false);
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const sections = useMemo(() => {
    const withParent = rows.filter((p) => normalizeParentCategory(p.parent_category));
    const filterUi = categoryFilter ? normalizeParentCategory(categoryFilter) : null;

    const buckets: Record<ParentCategory, PromoRow[]> = {
      Auto: [],
      Moto: [],
      Camion: [],
      Tracteurs: [],
    };

    for (const p of withParent) {
      const c = normalizeParentCategory(p.parent_category);
      if (!c) continue;
      if (filterUi && c !== filterUi) continue;
      buckets[c].push(p);
    }

    const out: { category: ParentCategory; items: PromoRow[] }[] = [];
    for (const cat of CATEGORY_ORDER) {
      if (filterUi && cat !== filterUi) continue;
      const items = buckets[cat];
      if (items.length > 0) out.push({ category: cat, items });
    }
    return out;
  }, [rows, categoryFilter]);

  if (loading) {
    return (
      <div className="layout-container py-6 flex justify-center">
        <Loader2 className="animate-spin text-gray-400" aria-hidden />
      </div>
    );
  }

  if (sections.length === 0) return null;

  return (
    <>
      {sections.map(({ category, items }) => (
        <OffersCarouselRow key={category} category={category} items={items} />
      ))}
    </>
  );
}

"use client";

import React from "react";
import { ExternalLink, Truck } from "lucide-react";

function euros(n: number | string | null | undefined) {
  const v = Number(n);
  if (Number.isNaN(v)) return "—";
  return `€${v.toFixed(2)}`;
}

function deliveryLabel(type: string | null | undefined) {
  if (type === "fast") return "Livraison rapide (24–72 h)";
  if (type === "normal") return "Livraison normale (~5 j. ouvrés)";
  return type || "—";
}

function paymentLabel(status: string | null | undefined) {
  if (status === "paid") return "Payé";
  if (status === "pending") return "Paiement en attente";
  if (status === "failed") return "Échoué";
  if (status === "canceled") return "Annulé";
  if (status === "refunded") return "Remboursé";
  if (status === "partially_refunded") return "Remboursement partiel";
  return status || "—";
}

function fulfillmentLabel(status: string | null | undefined) {
  if (status === "submitted") return "Envoyée au fournisseur";
  if (status === "error") return "Erreur fournisseur";
  if (status === "pending") return "En attente";
  if (status === "none") return "—";
  return status || "—";
}

export default function OrderPurchaseDetails({
  order,
  compact = false,
  /** Fournisseur : seules certaines lignes sont visibles ; ne pas présenter les montants comme « les vôtres ». */
  supplierView = false,
}: {
  order: any;
  /** Masque le bloc « client » si déjà affiché ailleurs (ex. tableau admin) */
  compact?: boolean;
  supplierView?: boolean;
}) {
  const items = order.order_items || [];
  const shipments = order.order_shipments || [];
  const supplierOrder = order.supplier_orders?.[0] || order.supplier_order || null;
  const linesSubtotal = items.reduce(
    (s: number, it: any) =>
      s + Number(it.price || 0) * Number(it.quantity || 0),
    0
  );
  const subtotal =
    order.subtotal_amount != null && !supplierView
      ? Number(order.subtotal_amount)
      : linesSubtotal;
  const delivery = Number(order.delivery_fee ?? 0);
  const warrantyFee = Number(order.warranty_fee ?? 0);
  const warrantyOn = Boolean(order.warranty_included);
  const total = Number(order.total_amount ?? 0);

  return (
    <div
      className={
        compact
          ? "text-sm space-y-3"
          : "border-t border-gray-100 bg-gray-50/90 p-4 md:p-6 text-sm space-y-4"
      }
    >
      {!compact && (
        <div className="grid md:grid-cols-2 gap-4">
          <div>
            <h4 className="font-bold text-gray-800 mb-2">Client & livraison</h4>
