"use client";

import React from 'react';
import { Star, Fuel, CloudRain, Volume2, Sun, CloudLightning, CloudSnow } from 'lucide-react';
import Link from 'next/link';
import { useProductPrice } from '@/hooks/useProductPrice';
import CategoryTooltip from './CategoryTooltip';

interface ProductCardProps {
  product: any;
}

const TireLabel = ({ type, value, color }: { type: 'fuel' | 'wet' | 'noise', value: string | number, color: string }) => {
  const icons = {
    fuel: <Fuel size={12} className="text-gray-600" />,
    wet: <CloudRain size={12} className="text-gray-600" />,
    noise: <Volume2 size={12} className="text-gray-600" />
  };

  return (
    <div className="flex items-center gap-1">
      <div className="w-4 flex justify-center">{icons[type]}</div>
      {type === 'noise' ? (
        <div className="flex items-center bg-gray-600 text-white text-[9px] font-bold px-1 h-4 rounded-r-sm relative ml-2 w-10 justify-between">
           <div className="absolute -left-1.5 top-0 w-0 h-0 border-t-[8px] border-t-transparent border-r-[6px] border-r-gray-600 border-b-[8px] border-b-transparent"></div>
           <span className="ml-0.5">{value}</span>
           <span className="text-[6px] scale-75">dB</span>
        </div>
      ) : (
        <div className={`flex items-center text-white text-[10px] font-bold px-1 h-4 rounded-r-sm relative ml-2 w-6 justify-center ${color}`}>
           <div className={`absolute -left-1.5 top-0 w-0 h-0 border-t-[8px] border-t-transparent border-r-[6px] border-b-[8px] border-b-transparent`} style={{ borderRightColor: 'inherit' }}></div>
           {value}
        </div>
      )}
    </div>
  );
};

export default function ProductCard({ product }: ProductCardProps) {
  // Garantir que specs seja um objeto e autres_categories seja array
  let specs: any = {};
  try {
    if (typeof product.specs === 'string') {
      specs = JSON.parse(product.specs);
    } else {
      specs = product.specs || {};
    }
  } catch (e) {
    specs = {};
  }
  
  // Garantir que autres_categories seja array
  if (specs.autres_categories && typeof specs.autres_categories === 'string') {
    specs.autres_categories = specs.autres_categories.split(/[,;|]/).map((c: string) => c.trim()).filter((c: string) => c.length > 0);
  } else if (!Array.isArray(specs.autres_categories)) {
    specs.autres_categories = [];
  }
  
  const labels = product.labels || {};
  const { finalPrice } = useProductPrice(product.base_price || 0, product.category || 'Auto');
  
  // Determine Label Colors
  const fuelColor = (labels.fuel === 'A' || labels.fuel === 'B') ? 'bg-green-500 border-green-500' : (labels.fuel === 'C' || labels.fuel === 'D') ? 'bg-yellow-400 border-yellow-400' : 'bg-orange-500 border-orange-500';
  const wetColor = (labels.wet === 'A' || labels.wet === 'B') ? 'bg-green-500 border-green-500' : (labels.wet === 'C' || labels.wet === 'D') ? 'bg-yellow-400 border-yellow-400' : 'bg-orange-500 border-orange-500';

  // Season Icon
  const getSeasonIcon = (season: string) => {
    const s = season?.toLowerCase() || '';
    if (s.includes('hiver') || s.includes('winter')) return <CloudSnow size={14} className="text-blue-400" />;
    if (s.includes('4') || s.includes('all')) return <CloudLightning size={14} className="text-green-500" />;
    return <Sun size={14} className="text-orange-400" />;
  };

  return (
    <div className="bg-[#FAF9F6] rounded-xl shadow-sm border border-gray-100 p-5 h-full flex flex-col justify-between relative group">
      
      {/* 1. Header: Brand, Stars, Price - Alinhados horizontalmente */}
      <div className="flex justify-between items-center mb-2">
        {/* Brand Logo */}
        <div className="h-6 flex items-center">
          {product.brands?.logo_url ? (
            <img 
              src={product.brands.logo_url} 
              alt={product.brands?.name || product.brand || 'Marque'} 
              className="h-full w-auto object-contain" 
            />
          ) : (
            <span className="text-xs font-bold text-gray-700 uppercase">
              {product.brands?.name || product.brand || 'Marque'}
            </span>
          )}
        </div>

        {/* Stars and Price - Alinhados horizontalmente */}
        <div className="flex items-center gap-3">
          {/* Stars */}
          <div className="flex items-center gap-1">
             <div className="flex text-orange-300 text-[10px]">
               {[...Array(5)].map((_, i) => <Star key={i} size={10} fill={i < 4 ? "currentColor" : "none"} />)}
             </div>
             <span className="text-[10px] text-gray-400 font-medium">4,3/5</span>
          </div>
          {/* Price */}
          <span className="text-2xl font-bold text-[#5c7c9e]">€{finalPrice.toFixed(2)}</span>
        </div>
      </div>

      {/* 3. Main Content: Image & Info */}
      <div className="flex gap-6 mb-4">
        {/* Left: Image */}
        <div className="w-32 flex-shrink-0 flex items-center justify-center">
          <img 
            src={product.images?.[0] || 'https://placehold.co/200x200/f3f4f6/d1d5db?text=Pneu'} 
            alt={product.name} 
            className="w-full h-auto object-contain mix-blend-multiply opacity-90 group-hover:scale-105 transition-transform duration-300"
          />
        </div>

        {/* Right: Info */}
        <div className="flex-1 flex flex-col justify-center pt-2">
          {/* Title */}
          <h3 className="font-bold text-gray-800 text-base uppercase leading-tight tracking-wide mb-1">
            {[product.brands?.name || product.brand, product.name].filter(Boolean).join(' ')}
          </h3>

          {/* Specs */}
          <p className="text-gray-900 font-medium text-sm mb-2">
            <span>{specs.width}/{specs.height} R{specs.diameter} {specs.load_index} {specs.speed_index}</span>
            {specs.autres_categories && specs.autres_categories.length > 0 && (
              <>
                {' '}
                {specs.autres_categories.map((cat: string, index: number) => (
                  <React.Fragment key={index}>
                    {index > 0 && ', '}
                    <CategoryTooltip category={cat} />
                  </React.Fragment>
                ))}
              </>
            )}
          </p>

          {/* Season & Category */}
          <div className="flex items-center gap-2 text-xs text-gray-400">
            <div className="flex items-center gap-1 text-orange-400">
              {getSeasonIcon(specs.season)}
              <span className="font-medium text-gray-500">{specs.season || 'Été'}</span>
            </div>
            <span>•</span>
            <span>{product.category || 'Auto'}</span>
          </div>
        </div>
      </div>

      {/* 4. Footer: Labels & Button */}
      <div className="flex justify-between items-end mt-auto">
        {/* Labels */}
        <div className="flex gap-2 mb-1">
          <TireLabel type="fuel" value={labels.fuel || '-'} color={fuelColor} />
          <TireLabel type="wet" value={labels.wet || '-'} color={wetColor} />
          <TireLabel type="noise" value={labels.noise || '-'} color="bg-gray-600" />
        </div>

        {/* Button */}
        <Link href={`/product/${product.id}`}>
          <button className="bg-[#5c8bc0] hover:bg-[#4a72a0] text-white text-xs font-bold py-2 px-8 rounded shadow-sm transition-colors uppercase tracking-wider">
            VOIR
          </button>
        </Link>
      </div>

    </div>
  );
}

"use client";

import React, { useEffect, useState } from 'react';
import Link from 'next/link';
import { createClient } from '@/lib/supabase';
import { buildPromotionSearchHref } from '@/lib/promotion-search-url';
import { Tag } from 'lucide-react';

export default function PromoBanner() {
  const [promotions, setPromotions] = useState<any[]>([]);
  const supabase = createClient();

  useEffect(() => {
    const fetchPromotions = async () => {
      try {
        const { data, error } = await supabase
          .from('promotions')
          .select(
            'id, title, discount_text, description, link_url, start_date, end_date, parent_category'
          )
          .eq('is_active', true)
          .order('sort_order', { ascending: true })
          .limit(20);
        if (error) {
          console.error('Erro ao buscar promoções:', error);
          return;
        }
        const list = data || [];
        const now = new Date();
        const active = list.filter((p: any) => {
          if (String(p.parent_category || '').trim()) return false;
          if (p.start_date && new Date(p.start_date) > now) return false;
          if (p.end_date && new Date(p.end_date) < now) return false;
          return true;
        });
        setPromotions(active.slice(0, 5));
      } catch {
        setPromotions([]);
      }
    };
    fetchPromotions();
  }, []);

  if (promotions.length === 0) return null;

  return (
    <div className="layout-container pb-2 md:pb-3 pt-1">
      <div className="bg-gradient-to-r from-amber-500 to-orange-500 text-white rounded-xl md:rounded-2xl px-3 py-2 sm:px-4 shadow-sm">
        <div className="flex flex-wrap items-center justify-center gap-x-6 gap-y-1 text-sm font-medium">
          {promotions.map((p) => {
            const content = (
              <span className="inline-flex items-center gap-2">
                <Tag size={16} className="flex-shrink-0" />
                {p.discount_text && (
                  <span className="font-bold">{p.discount_text}</span>
                )}
                {p.title}
                {p.description && (
                  <span className="opacity-90 hidden sm:inline"> — {p.description}</span>
                )}
              </span>
            );
            const href = p.link_url?.trim()
              ? p.link_url.trim()
              : buildPromotionSearchHref({ id: p.id, parent_category: p.parent_category });
            if (/^https?:\/\//i.test(href)) {
              return (
                <a
                  key={p.id}
                  href={href}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="hover:underline focus:outline-none focus:underline"
                >
                  {content}
                </a>
              );
            }
            return (
              <Link key={p.id} href={href} className="hover:underline focus:outline-none focus:underline">
                {content}
              </Link>
            );
          })}
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useEffect, useState, useRef } from 'react';
import { Loader2, ChevronLeft, ChevronRight } from 'lucide-react';
import { createClient } from '@/lib/supabase';
import VerticalProductCard from './VerticalProductCard';

interface RelatedProductsProps {
  productId: string;
  category?: string;
  brandId?: string;
  brandName?: string;
  specs?: {
    width?: string;
    height?: string;
    diameter?: string;
  };
}

export default function RelatedProducts({ 
  productId, 
  category, 
  brandId, 
  brandName,
  specs 
}: RelatedProductsProps) {
  const [products, setProducts] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const scrollRef = useRef<HTMLDivElement>(null);
  const supabase = createClient();

  useEffect(() => {
    const fetchRelatedProducts = async () => {
      setLoading(true);
      
      let query = supabase
        .from('products')
        .select('*, brands(id, name, logo_url)')
        .eq('is_active', true)
        .neq('id', productId) // Excluir o produto atual
        .limit(12);

      // Filtrar por categoria - garantir match exato para evitar mistura
      if (category) {
        const normalizedCategory = category.trim();
        // Filtrar por categoria exata - garantir que categorias diferentes não se misturem
        query = query.or(
          `category.eq.${normalizedCategory},category.eq.${normalizedCategory.toLowerCase()},category.eq.${normalizedCategory.toUpperCase()}`
        );
      }

      // Filtrar por marca (brand_id ou brand texto)
      if (brandId) {
        query = query.eq('brand_id', brandId);
      } else if (brandName) {
        query = query.ilike('brand', `%${brandName}%`);
      }

      // Filtrar por medidas (width, height, diameter)
      if (specs?.width) {
        query = query.contains('specs', { width: specs.width });
      }
      if (specs?.height) {
        query = query.contains('specs', { height: specs.height });
      }
      if (specs?.diameter) {
        query = query.contains('specs', { diameter: specs.diameter });
      }

      const { data, error } = await query;

      if (error) {
        console.error("Error fetching related products:", error);
      } else {
        // Filtro adicional no cliente para garantir match exato (case-insensitive)
        const normalizedCategory = category?.trim().toLowerCase();
        const filtered = (data || []).filter((product: any) => {
          if (!category) return true;
          const productCategory = (product.category || '').toLowerCase();
          return productCategory === normalizedCategory;
        });
        setProducts(filtered);
      }
      setLoading(false);
    };

    if (productId) {
      fetchRelatedProducts();
    }
  }, [productId, category, brandId, brandName, specs]);

  const scroll = (direction: 'left' | 'right') => {
    if (scrollRef.current) {
      const { current } = scrollRef;
      const scrollAmount = direction === 'left' ? -320 : 320;
      current.scrollBy({ left: scrollAmount, behavior: 'smooth' });
    }
  };

  if (loading) {
    return (
      <section className="py-8 bg-transparent">
        <div className="layout-container flex justify-center">
          <Loader2 className="animate-spin text-gray-400" />
        </div>
      </section>
    );
  }

  if (products.length === 0) return null;

  return (
    <section className="py-8 bg-transparent relative group">
      <div className="layout-container">
        <h2 className="text-sm font-bold text-gray-900 mb-6 uppercase tracking-wide">
          Produits similaires
        </h2>
        
        <div className="relative">
          {/* Scroll Buttons - Visible on Desktop Hover */}
          <button 
            onClick={() => scroll('left')} 
            className="hidden md:flex absolute left-[-20px] top-1/2 -translate-y-1/2 z-10 bg-white shadow-lg border border-gray-100 p-3 rounded-full text-gray-600 hover:text-blue-600 hover:scale-110 transition-all opacity-0 group-hover:opacity-100"
            aria-label="Scroll Left"
          >
            <ChevronLeft size={24} />
          </button>

          <div 
            ref={scrollRef}
            className="flex overflow-x-auto gap-4 md:gap-6 pb-4 scrollbar-hide snap-x scroll-smooth"
          >
            {products.map((product) => (
              <div key={product.id} className="min-w-[280px] md:min-w-[300px] snap-center h-full flex-shrink-0">
                <VerticalProductCard product={product} />
              </div>
            ))}
          </div>

          <button 
            onClick={() => scroll('right')} 
            className="hidden md:flex absolute right-[-20px] top-1/2 -translate-y-1/2 z-10 bg-white shadow-lg border border-gray-100 p-3 rounded-full text-gray-600 hover:text-blue-600 hover:scale-110 transition-all opacity-0 group-hover:opacity-100"
            aria-label="Scroll Right"
          >
            <ChevronRight size={24} />
          </button>
        </div>
      </div>
    </section>
  );
}

